// GERADO por scripts/build-engine-bundle.mjs (roda no "npm run build"). Não edite: mude os arquivos de origem e gere de novo.
// Pacote do motor de testes dinâmico que a IDE grava em .metabuilder/testes/engine.
export const ENGINE_VERSION = "6eeb64e1b0"
export const ENGINE_FILES: Record<string, string> = {
 "e2e/package.json": "{\n  \"name\": \"metabuilder-test-engine\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"description\": \"Motor de testes dinâmico do MetaBuilder PRO (instalado pela IDE; não editar)\",\n  \"devDependencies\": {\n    \"@playwright/test\": \"^1.49.0\",\n    \"bcryptjs\": \"^2.4.3\",\n    \"oracledb\": \"^6.5.0\",\n    \"pg\": \"^8.13.0\"\n  }\n}\n",
 "e2e/playwright.dynamic.config.ts": "import { defineConfig } from '@playwright/test'\nimport path from 'node:path'\nimport fs from 'node:fs'\nimport { CONFIG } from './dynamic/lib/config'\nimport { detectarApp } from './dynamic/lib/app.mjs'\nimport { envParaApp, tipoDoBanco } from './dynamic/lib/banco.mjs'\n\n/**\n * Testes dinâmicos: gerados a partir do manifesto do projeto (o que o dev configurou no Studio), contra o app exportado: Node ou Java (Spring Boot + Next),\n * com PostgreSQL ou Oracle. A configuração vem de E2E_CONFIG (JSON gravado pela IDE) ou, no repositório, do e2e/.env.real.\n * Rodar: npm run dyn:test  (E2E_MANIFEST=caminho.json para outro manifesto).\n */\nconst app = detectarApp(CONFIG.appDir)\nif (!CONFIG.appDir || !fs.existsSync(path.join(app.frontendDir, 'package.json'))) {\n  throw new Error(`Não achei o app exportado em \"${CONFIG.appDir}\". Ejete o projeto (IDE > Ejetar para uma pasta) e escolha essa pasta no Ambiente de Testes.`)\n}\n\n// com a configuração da IDE (E2E_CONFIG) o app sobe apontando para o banco de TESTE: a variável de ambiente vale mais que o .env.local (Node) e que o application.properties (Spring)\nconst bancoDeTeste = process.env.E2E_CONFIG && CONFIG.dbUrl ? envParaApp(CONFIG.dbUrl, app.pilha) : {}\nconst frontend = {\n  command: `npx next start -p ${CONFIG.port}`,\n  cwd: app.frontendDir,\n  url: `http://localhost:${CONFIG.port}/login`,\n  reuseExistingServer: false,\n  timeout: 90_000,\n  env: { EXPORT_DIR: CONFIG.exportDir, ...(app.pilha === 'node' ? bancoDeTeste : { NEXT_PUBLIC_API_URL: `http://localhost:${CONFIG.backendPort}` }) },\n}\n\nfunction backendJava() {\n  const target = path.join(app.backendDir!, 'target')\n  const jar = fs.existsSync(target) ? fs.readdirSync(target).find(n => n.endsWith('.jar') && !n.endsWith('.original')) : undefined\n  if (!jar) throw new Error(`O backend Java ainda não foi compilado (sem .jar em ${target}). A IDE o compila ao preparar o app.`)\n  const jdk = path.join(process.env.USERPROFILE || process.env.HOME || '', '.metabuilder', 'jdk21')\n  const javaExe = fs.existsSync(path.join(jdk, 'bin', 'java.exe')) ? path.join(jdk, 'bin', 'java.exe') : 'java'\n  // o log do backend (o erro de cada gravação que falha) fica num arquivo: sem ele os erros do Spring não aparecem\n  const log = path.resolve(import.meta.dirname, '.apps', 'backend-java.log')\n  fs.mkdirSync(path.dirname(log), { recursive: true })\n  return {\n    command: `\"${javaExe}\" -jar \"${path.join(target, jar)}\" > \"${log}\" 2>&1`,\n    cwd: app.backendDir!,\n    url: `http://localhost:${CONFIG.backendPort}/api-docs`,\n    reuseExistingServer: false,\n    timeout: 180_000,\n    env: { SERVER_PORT: String(CONFIG.backendPort), APP_CORS_ALLOWED_ORIGINS: `http://localhost:${CONFIG.port}`, ...bancoDeTeste },\n  }\n}\n\nexport default defineConfig({\n  testDir: './dynamic/tests',\n  timeout: 60_000,\n  expect: { timeout: 10_000 },\n  fullyParallel: false,\n  workers: 1,\n  retries: 0,\n  // o relator da IDE escreve uma linha por teste (começou/terminou) para o painel \"Ambiente de Testes\" mostrar o andamento ao vivo\n  reporter: [['list'], ['./dynamic/ide-reporter.ts'], ['html', { outputFolder: 'playwright-report-dynamic', open: 'never' }]],\n  outputDir: 'test-results-dynamic',\n  globalSetup: './dynamic/global-setup.ts',\n  globalTeardown: './dynamic/global-teardown.ts',\n  // E2E_HEADED=1 abre o navegador na tela (\"ver ao vivo\"); E2E_SLOWMO=<ms> espera entre as ações para dar tempo de acompanhar\n  use: { channel: (process.env.E2E_BROWSER || 'chrome') as 'chrome' | 'msedge', headless: process.env.E2E_HEADED !== '1', launchOptions: { slowMo: Number(process.env.E2E_SLOWMO || 0), args: process.env.E2E_HEADED === '1' ? ['--start-maximized'] : [] }, trace: 'retain-on-failure', screenshot: 'only-on-failure', locale: 'pt-BR', baseURL: `http://localhost:${CONFIG.port}` },\n  projects: [{ name: `dynamic-${tipoDoBanco(CONFIG.dbUrl) ?? 'banco'}-${app.pilha}` }],\n  webServer: app.pilha === 'java' ? [backendJava(), frontend] : frontend,\n})\n",
 "e2e/dynamic/ide-reporter.ts": "import type { FullResult, Reporter, TestCase, TestResult } from '@playwright/test/reporter'\nimport { eventLine, statusFromPlaywright, type TestEvent } from '../../src/lib/testing/results'\n\n/**\n * Relator para o painel \"Ambiente de Testes\" da IDE: escreve uma linha por evento (começou / terminou / acabou) na saída, em JSON, depois do prefixo\n * @@MB@@. O painel lê a saída, separa estas linhas e atualiza a tela ao vivo. Não substitui o relatório HTML: roda ao lado dele.\n */\nexport default class IdeReporter implements Reporter {\n  private total = 0\n  private passed = 0\n  private failed = 0\n  private skipped = 0\n\n  // o grupo é o \"describe\" (caso de uso) e o título é o do teste: os dois últimos itens do caminho (projeto, arquivo, grupo, teste)\n  private names(test: TestCase) {\n    const p = test.titlePath()\n    return { group: p[p.length - 2] ?? '', title: p[p.length - 1] ?? '' }\n  }\n\n  private emit(ev: TestEvent) { process.stdout.write(eventLine(ev) + '\\n') }\n\n  onTestBegin(test: TestCase) {\n    this.emit({ t: 'begin', ...this.names(test) })\n  }\n\n  onTestEnd(test: TestCase, result: TestResult) {\n    const status = statusFromPlaywright(result.status)\n    this.total++\n    if (status === 'passed') this.passed++\n    else if (status === 'skipped') this.skipped++\n    else this.failed++\n    const message = result.error?.message ?? ''\n    // sem os códigos de cor do terminal, e só o começo: o relatório HTML tem o resto\n    const error = message ? message.replace(/\\u001b\\[[0-9;]*m/g, '').split('\\n').slice(0, 6).join('\\n') : undefined\n    const reason = status === 'skipped' ? test.annotations.find(a => a.type === 'skip')?.description : undefined\n    const anexo = (nome: string) => result.attachments.find(a => a.name === nome)?.body?.toString()\n    const shot = anexo('mb-shot')\n    const video = anexo('mb-video')\n    this.emit({ t: 'end', ...this.names(test), status, ms: result.duration, ...(error ? { error } : {}), ...(reason ? { reason } : {}), ...(shot ? { shot } : {}), ...(video ? { video } : {}) })\n  }\n\n  onEnd(_result: FullResult) {\n    this.emit({ t: 'done', total: this.total, passed: this.passed, failed: this.failed, skipped: this.skipped })\n  }\n}\n",
 "e2e/dynamic/make-pdf.mjs": "// Gera um PDF a partir do HTML do relatório de testes (usado pelo botão Download > PDF do painel da IDE).\n// Uso: node dynamic/make-pdf.mjs <relatorio.html> <saida.pdf>\nimport { chromium } from '@playwright/test'\nimport path from 'node:path'\nimport { pathToFileURL } from 'node:url'\n\nconst [html, pdf] = process.argv.slice(2)\nif (!html || !pdf) {\n  console.error('Uso: node dynamic/make-pdf.mjs <relatorio.html> <saida.pdf>')\n  process.exit(2)\n}\n\nconst browser = await chromium.launch({ channel: process.env.E2E_BROWSER || 'chrome' })\ntry {\n  const page = await browser.newPage()\n  await page.goto(pathToFileURL(path.resolve(html)).href)\n  await page.emulateMedia({ media: 'print' })\n  await page.pdf({ path: path.resolve(pdf), format: 'A4', printBackground: true, margin: { top: '14mm', bottom: '14mm', left: '12mm', right: '12mm' } })\n} finally {\n  await browser.close()\n}\n",
 "e2e/dynamic/prepare-app.mjs": "// Prepara o app exportado para o teste: instala as dependências (se faltarem) e compila (se nunca foi compilado ou se o código mudou depois da última compilação).\n// Node: next build. Java: Maven (mvnw package, com o JDK 21 portátil da IDE) para o backend e next build do frontend apontando para o backend dos testes.\n// Uso: node dynamic/prepare-app.mjs   (a pasta do app vem de E2E_CONFIG ou de E2E_REAL_APP_DIR)\nimport { spawnSync } from 'node:child_process'\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport { detectarApp } from './lib/app.mjs'\nimport { envParaApp } from './lib/banco.mjs'\n\nconst cfg = process.env.E2E_CONFIG && fs.existsSync(process.env.E2E_CONFIG) ? JSON.parse(fs.readFileSync(process.env.E2E_CONFIG, 'utf8')) : {}\nconst appDir = cfg.appDir || process.env.E2E_REAL_APP_DIR\nconst app = detectarApp(appDir)\nif (!appDir || !fs.existsSync(path.join(app.frontendDir, 'package.json'))) {\n  console.error(`Não achei o app exportado em \"${appDir}\".`)\n  process.exit(1)\n}\nconst backendPort = cfg.backendPort || process.env.E2E_JAVA_BACKEND_PORT || 8090\n\n// o build também usa o banco de teste (o Next pode ler o banco ao pré-renderizar páginas)\nconst bancoDeTeste = cfg.dbUrl ? envParaApp(cfg.dbUrl, app.pilha) : {}\nconst jdk = path.join(process.env.USERPROFILE || process.env.HOME || '', '.metabuilder', 'jdk21')\nconst javaEnv = fs.existsSync(path.join(jdk, 'bin', 'java.exe')) ? { JAVA_HOME: jdk } : {}\n\nconst run = (cmd, args, cwd, extra = {}) => {\n  const r = spawnSync(cmd, args, { cwd, stdio: 'inherit', shell: true, env: { ...process.env, ...bancoDeTeste, ...extra } })\n  return r.status === 0\n}\nconst must = (ok, o) => { if (!ok) { console.error(`Falhou: ${o}`); process.exit(1) } }\n\n/** Data da última alteração do código (ignora dependências e a própria compilação). */\nfunction ultimaAlteracao(dir, ignorar = new Set(['node_modules', '.next', '.git', 'db', 'target', '.mvn'])) {\n  let max = 0\n  if (!fs.existsSync(dir)) return 0\n  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {\n    if (ignorar.has(e.name)) continue\n    const p = path.join(dir, e.name)\n    if (!e.isDirectory() && /\\.(md|log)$/i.test(e.name)) continue\n    max = Math.max(max, e.isDirectory() ? ultimaAlteracao(p, ignorar) : fs.statSync(p).mtimeMs)\n  }\n  return max\n}\n\nif (!fs.existsSync(path.join(app.frontendDir, 'node_modules'))) {\n  console.log('Preparando o app de teste: instalando as dependências (só na primeira vez, pode levar alguns minutos)...')\n  must(run('npm', ['install', '--no-audit', '--no-fund'], app.frontendDir), 'npm install')\n}\n\nif (app.pilha === 'java') {\n  // backend: compila o jar se não existe ou se o código mudou depois dele\n  const target = path.join(app.backendDir, 'target')\n  const jar = fs.existsSync(target) ? fs.readdirSync(target).find(n => n.endsWith('.jar') && !n.endsWith('.original')) : undefined\n  if (!jar || ultimaAlteracao(app.backendDir) > fs.statSync(path.join(target, jar)).mtimeMs) {\n    console.log('Preparando o app de teste: compilando o backend Java (Maven, sem testes; na primeira vez baixa dependências)...')\n    const mvnw = process.platform === 'win32' ? '.\\\\mvnw.cmd' : './mvnw'\n    if (!run(mvnw, ['-o', '-q', '-DskipTests', 'package'], app.backendDir, javaEnv)) {\n      console.log('Compilação offline falhou (falta alguma dependência no ~/.m2): tentando de novo com internet...')\n      must(run(mvnw, ['-q', '-DskipTests', 'package'], app.backendDir, javaEnv), 'mvnw package (backend)')\n    }\n  } else console.log('Backend Java já está compilado e atualizado.')\n}\n\n// frontend (Node: o próprio app; Java: a pasta frontend, apontando para o backend dos testes)\nconst marca = path.join(app.frontendDir, '.next', 'BUILD_ID')\nconst apiUrl = app.pilha === 'java' ? { NEXT_PUBLIC_API_URL: `http://localhost:${backendPort}` } : {}\nconst marcaApi = path.join(app.frontendDir, '.next', '.mb-api-url')\nconst apiMudou = app.pilha === 'java' && (!fs.existsSync(marcaApi) || fs.readFileSync(marcaApi, 'utf8') !== apiUrl.NEXT_PUBLIC_API_URL)\nif (!fs.existsSync(marca) || apiMudou || ultimaAlteracao(app.frontendDir) > fs.statSync(marca).mtimeMs) {\n  console.log('Preparando o app de teste: compilando o frontend (next build)...')\n  must(run('npx', ['next', 'build'], app.frontendDir, apiUrl), 'next build')\n  if (app.pilha === 'java') fs.writeFileSync(marcaApi, apiUrl.NEXT_PUBLIC_API_URL)\n} else {\n  console.log('Frontend de teste já está compilado e atualizado.')\n}\n",
 "e2e/dynamic/db-tool.mjs": "// Ferramenta de banco do motor de testes (a IDE a chama): testa a conexão com o banco de teste (Postgres ou Oracle), cria o usuário de teste do app e o remove.\n//   node dynamic/db-tool.mjs check     -> conecta e confere se as tabelas dos casos de uso existem\n//   node dynamic/db-tool.mjs prepare   -> cria o usuário de teste (ou renova a senha dele), com a senha gerada, e o põe no grupo de administração, se houver\n//   node dynamic/db-tool.mjs copy      -> (só Postgres) cria, no mesmo servidor, uma cópia do banco (CREATE DATABASE ... TEMPLATE); dbUrl = banco de origem, copyName = nome da cópia\n//   node dynamic/db-tool.mjs remove    -> remove o usuário de teste e o vínculo dele com o grupo\n// Entrada: E2E_CONFIG (JSON com dbUrl e, opcionalmente, robotPassword) e E2E_MANIFEST (manifesto com a configuração de login). Saída: uma linha @@MB-DB@@{json}.\nimport crypto from 'node:crypto'\nimport fs from 'node:fs'\nimport pg from 'pg'\nimport { abrirBanco, lerUrl, tipoDoBanco } from './lib/banco.mjs'\nimport { colocarNoGrupo, grupoAdmin, upsertUsuario, apagarUsuario } from './lib/acesso.mjs'\n\nconst MARCA = '@@MB-DB@@'\nconst ROBO_EMAIL = 'e2e_motor@metabuilder.local'\nconst ROBO_NOME = 'E2E Motor (testes automáticos)'\n\nconst out = o => { console.log(MARCA + JSON.stringify(o)); process.exit(o.ok ? 0 : 1) }\nconst cfg = JSON.parse(fs.readFileSync(process.env.E2E_CONFIG, 'utf8'))\nconst manifest = process.env.E2E_MANIFEST && fs.existsSync(process.env.E2E_MANIFEST) ? JSON.parse(fs.readFileSync(process.env.E2E_MANIFEST, 'utf8')) : null\nconst action = process.argv[2]\nconst limpar = msg => String(msg || '').replace(/(:\\/\\/[^:@/]+:)[^@]+@/g, '$1***@')\n\nif (!tipoDoBanco(cfg.dbUrl)) out({ ok: false, error: `Banco \"${String(cfg.dbUrl).split(':')[0]}\" ainda não é suportado pelos testes automáticos (só PostgreSQL e Oracle).` })\n\nif (action === 'copy') {\n  // a cópia é feita por quem NÃO está conectado ao banco de origem (o Postgres não deixa copiar um banco em uso), por isso antes de abrir a conexão principal\n  if (tipoDoBanco(cfg.dbUrl) !== 'postgres') out({ ok: false, error: 'A cópia automática só existe para PostgreSQL. No Oracle, peça ao administrador do banco (use o script da IDE).' })\n  const origem = lerUrl(cfg.dbUrl).banco\n  const nome = String(cfg.copyName || '').trim()\n  if (!/^[a-z_][a-z0-9_]{0,62}$/.test(nome)) out({ ok: false, error: 'Nome inválido para a cópia: use letras minúsculas, números e _ (começando por letra).' })\n  if (nome === origem) out({ ok: false, error: 'A cópia precisa ter um nome diferente do banco original.' })\n  const adm = new URL(cfg.dbUrl); adm.pathname = '/postgres'\n  const a = new pg.Client({ connectionString: adm.toString(), connectionTimeoutMillis: 8000 })\n  try { await a.connect() } catch (e) { out({ ok: false, error: limpar(e.message) }) }\n  try {\n    if ((await a.query('select 1 from pg_database where datname = $1', [nome])).rowCount > 0) out({ ok: true, existed: true, name: nome })\n    const tam = Number((await a.query('select pg_database_size($1) as s', [origem])).rows[0].s)\n    await a.query(`create database \"${nome}\" template \"${origem.replace(/\"/g, '\"\"')}\"`)\n    out({ ok: true, name: nome, sizeMb: Math.round(tam / 1048576) })\n  } catch (e) {\n    const porCodigo = { '55006': 'O banco original está em uso por outro programa (o app, DBeaver...). Feche as conexões com ele e tente de novo, ou use o script para o administrador.', '42501': 'O usuário do banco não tem permissão para criar bancos (CREATEDB). Peça ao administrador do banco ou use o script.' }\n    out({ ok: false, error: porCodigo[e.code] || limpar(e.message) })\n  }\n}\n\nlet d\ntry {\n  d = await abrirBanco(cfg.dbUrl)\n} catch (e) {\n  out({ ok: false, error: limpar(e.message) })\n}\n\ntry {\n  if (action === 'check') {\n    const v = await d.versao()\n    const esperadas = manifest ? [...new Set(manifest.views.flatMap(x => [x.table, ...x.details.map(t => t.table)]).filter(Boolean))] : []\n    const achadas = await d.tabelas()\n    const faltam = esperadas.filter(t => !achadas.has(t.toLowerCase()))\n    out({ ok: true, database: v.banco, size: v.tamanho, version: v.versao, tables: { expected: esperadas.length, missing: faltam }, authType: manifest?.auth?.type ?? null })\n  }\n\n  const auth = manifest?.auth\n  if (!auth || auth.type === 'none') out({ ok: true, noAuth: true })\n  if (auth.type !== 'database') out({ ok: false, error: `O login do tipo \"${auth.type}\" ainda não é suportado pelos testes automáticos.` })\n  const { usersTable, emailColumn, passwordColumn } = auth\n  if (!usersTable || !emailColumn || !passwordColumn) out({ ok: false, error: 'A configuração de login do projeto não informa a tabela de usuários e as colunas de e-mail e senha.' })\n\n  const pkUser = auth.usersPk || 'id'\n  const achar = async () => (await d.query(`select ${d.ident(pkUser)}::text as id from ${d.ident(usersTable)} where ${d.ident(emailColumn)} = $1`, [ROBO_EMAIL]))[0]?.id\n\n  if (action === 'remove') {\n    const uid = await achar()\n    if (uid) await apagarUsuario(d, auth, uid)\n    out({ ok: true, removed: !!uid })\n  }\n\n  if (action === 'prepare') {\n    const senha = cfg.robotPassword || crypto.randomBytes(18).toString('base64url')\n    const formato = String(auth.hash || 'bcrypt').toLowerCase()\n    const colunas = (await d.colunas(usersTable)).map(r => r.column_name)\n    if (colunas.length === 0) out({ ok: false, error: `A tabela de usuários \"${usersTable}\" não existe no banco de teste.` })\n    if (!colunas.includes(emailColumn.toLowerCase()) || !colunas.includes(passwordColumn.toLowerCase())) out({ ok: false, error: `A tabela \"${usersTable}\" não tem as colunas ${emailColumn} e ${passwordColumn}.` })\n\n    const { id: uid, criado } = await upsertUsuario(d, auth, { email: ROBO_EMAIL, nome: ROBO_NOME, senha })\n\n    // gestão de acesso: coloca o usuário no grupo de administração, se o projeto tiver um (não cria grupo nenhum)\n    let grupo = null\n    const admin = uid ? await grupoAdmin(d, auth) : null\n    if (admin) { grupo = admin.nome; await colocarNoGrupo(d, auth, uid, admin.id) }\n    out({ ok: true, user: ROBO_EMAIL, password: senha, created: criado, group: grupo, hash: formato })\n  }\n\n  out({ ok: false, error: `ação desconhecida: ${action}` })\n} catch (e) {\n  out({ ok: false, error: limpar(e.message) })\n} finally {\n  await d?.fechar()\n}\n",
 "e2e/dynamic/global-setup.ts": "import fs from 'node:fs'\nimport path from 'node:path'\nimport { limparSegurancaDoBanco } from './lib/seguranca'\nimport { alvosDeLimpeza, arquivoBase, assertSeguro, impressaoDigital, limparDiario, limparSobras, tabelasDoManifesto } from './lib/guard'\nimport type { TestManifest } from '../../src/lib/testing/manifestTypes'\n\n/** Antes da rodada: confere que o banco é o de teste e guarda a impressão digital das tabelas dos casos de uso. */\nexport default async function globalSetup() {\n  assertSeguro()\n  const manifesto = process.env.E2E_MANIFEST || path.join(import.meta.dirname, 'manifests', 'vendas-pg.sample.json')\n  const m = JSON.parse(fs.readFileSync(manifesto, 'utf8')) as TestManifest\n  const tabelas = tabelasDoManifesto(m)\n  // teste de integração: sobras de uma rodada anterior interrompida saem antes de guardar a impressão digital (a rodada começa limpa)\n  const tipos = (process.env.E2E_TYPES || '').split(',')\n  const gravaDados = tipos.includes('integracao') || tipos.includes('seguranca')\n  const limpeza = gravaDados ? alvosDeLimpeza(m) : []\n  if (limpeza.length > 0) await limparSobras(limpeza)\n  if (gravaDados) await limparDiario() // registros criados sem marcador por uma rodada interrompida\n  const seguranca = tipos.includes('seguranca') ? m.auth ?? null : null\n  if (seguranca) await limparSegurancaDoBanco(seguranca) // usuários e grupos temporários de uma rodada interrompida\n  fs.mkdirSync(path.dirname(arquivoBase()), { recursive: true })\n  fs.writeFileSync(arquivoBase(), JSON.stringify({ tabelas, limpeza, seguranca, gravaDados, antes: await impressaoDigital(tabelas) }))\n}\n",
 "e2e/dynamic/global-teardown.ts": "import fs from 'node:fs'\nimport { limparSegurancaDoBanco } from './lib/seguranca'\nimport { arquivoBase, diferencas, impressaoDigital, limparDiario, limparSobras, type Impressao } from './lib/guard'\n\n/** Depois da rodada: a impressão digital das tabelas tem de ser a mesma do início; senão a rodada falha e avisa. */\nexport default async function globalTeardown() {\n  if (!fs.existsSync(arquivoBase())) return\n  const { tabelas, antes, limpeza = [], seguranca, gravaDados } = JSON.parse(fs.readFileSync(arquivoBase(), 'utf8')) as { tabelas: string[]; antes: Impressao; limpeza?: Array<{ tabela: string; coluna: string }>; seguranca?: any; gravaDados?: boolean }\n  if (gravaDados) await limparDiario() // registros criados sem marcador e não excluídos\n  if (limpeza.length > 0) await limparSobras(limpeza) // o que um teste de integração deixou para trás sai antes da conferência\n  if (seguranca) await limparSegurancaDoBanco(seguranca) // e os usuários e grupos temporários dos testes de segurança\n  const difs = diferencas(antes, await impressaoDigital(tabelas))\n  if (difs.length > 0) {\n    throw new Error(`ATENÇÃO: os dados do banco mudaram durante a rodada (${difs.join('; ')}). Confira o banco de teste antes de rodar de novo.`)\n  }\n  console.log(`\\nBanco intacto: ${tabelas.length} tabela(s) dos casos de uso continuam exatamente como estavam (quantidade e conteúdo conferidos).`)\n}\n",
 "e2e/dynamic/lib/config.ts": "import fs from 'node:fs'\nimport path from 'node:path'\n\n/**\n * Configuração do motor de testes dinâmico. Duas origens:\n *  - E2E_CONFIG = caminho de um JSON (é o que a IDE grava para o motor instalado na pasta do usuário);\n *  - sem ela, o modo do repositório: variáveis E2E_REAL_* e o arquivo e2e/.env.real (criado por `npm run real:robot`).\n */\nexport interface EngineConfig {\n  /** pasta do app exportado a testar (a que tem package.json e .env.local) */\n  appDir: string\n  port: number\n  /** conexão com o banco de TESTE (o mesmo que o app exportado usa): é nele que o motor confere que nada foi alterado */\n  dbUrl: string\n  /** usuário do app que o robô usa para entrar */\n  user: string\n  password: string\n  /** copy = uma cópia do banco que o cliente informou (padrão) · original = o banco do próprio app, só com o consentimento do cliente */\n  mode: 'copy' | 'original'\n  /** o cliente confirmou na IDE que o banco informado é uma cópia de teste (modo copy) */\n  copyConfirmed: boolean\n  /** o cliente consentiu na IDE em rodar no banco original (modo original) */\n  consentOriginal: boolean\n  /** app sem login: o robô não entra */\n  noAuth: boolean\n  /** permite banco que não é desta máquina (só com o consentimento do cliente, dado na IDE) */\n  allowRemote: boolean\n  /** bancos permitidos; vazio = o próprio banco de dbUrl */\n  allowedDbs: string[]\n  /** pasta onde o app grava as exportações durante o teste */\n  exportDir: string\n  /** porta do backend Java (Spring Boot) dos testes; só vale para apps com backend Java */\n  backendPort: number\n}\n\nconst engineRoot = path.join(import.meta.dirname, '..', '..')\n\nfunction parseEnv(file: string): Record<string, string> {\n  const out: Record<string, string> = {}\n  if (!fs.existsSync(file)) return out\n  for (const line of fs.readFileSync(file, 'utf8').split(/\\r?\\n/)) {\n    if (!line.includes('=') || line.startsWith('#')) continue\n    out[line.slice(0, line.indexOf('='))] = line.slice(line.indexOf('=') + 1)\n  }\n  return out\n}\n\nexport function loadConfig(): EngineConfig {\n  const exportDir = path.join(engineRoot, '.apps', 'exports-dynamic')\n  const file = process.env.E2E_CONFIG\n  if (file) {\n    const j = JSON.parse(fs.readFileSync(file, 'utf8')) as Partial<EngineConfig>\n    return { appDir: '', port: 3102, dbUrl: '', user: '', password: '', mode: 'copy', copyConfirmed: false, consentOriginal: false, noAuth: false, allowRemote: false, allowedDbs: [], exportDir, backendPort: 8090, ...j }\n  }\n  const env = parseEnv(path.join(engineRoot, '.env.real'))\n  const val = (k: string, d = '') => process.env[k] ?? env[k] ?? d\n  return {\n    appDir: val('E2E_REAL_APP_DIR', ''),\n    port: Number(val('E2E_REAL_PORT', '3102')),\n    dbUrl: val('E2E_REAL_PG_URL'),\n    user: val('E2E_REAL_USER'),\n    password: val('E2E_REAL_PASSWORD'),\n    mode: 'original',\n    copyConfirmed: false,\n    consentOriginal: true, // modo do repositório: o dev usa o próprio banco de desenvolvimento, com as travas antigas (lista de bancos permitidos, só local)\n    noAuth: false,\n    allowRemote: false,\n    allowedDbs: val('E2E_REAL_ALLOWED_DBS', 'crm').split(',').map(s => s.trim()).filter(Boolean),\n    exportDir,\n    backendPort: Number(val('E2E_JAVA_BACKEND_PORT', '8090')),\n  }\n}\n\nexport const CONFIG = loadConfig()\n",
 "e2e/dynamic/lib/db.ts": "import { CONFIG } from './config'\nimport { abrirBanco, tipoDoBanco } from './banco.mjs'\n\nexport type Banco = Awaited<ReturnType<typeof abrirBanco>>\n\n/** Abre o banco de teste (Postgres ou Oracle, pela URL da configuração), roda a função e fecha. */\nexport async function comBanco<T>(fn: (d: Banco) => Promise<T>): Promise<T> {\n  const d = await abrirBanco(CONFIG.dbUrl)\n  try { return await fn(d) } finally { await d.fechar() }\n}\n\n/** Consulta o banco de teste. O SQL é escrito do jeito do Postgres; no Oracle o adaptador o traduz (banco.mjs). As linhas voltam com as colunas em minúsculas. */\nexport async function consultar<T = any>(sql: string, params: unknown[] = []): Promise<T[]> {\n  return comBanco(d => d.query(sql, params) as Promise<T[]>)\n}\n\nexport const dialeto = (): 'postgres' | 'oracle' | null => tipoDoBanco(CONFIG.dbUrl)\n\n/** Nome do campo no HTML do app exportado: o Oracle usa as colunas em MAIÚSCULAS (NOME_EMPRESA), o Postgres como estão. */\nexport const nomeDoCampo = (coluna: string): string => (dialeto() === 'oracle' && !/^virt_/i.test(coluna) ? coluna.toUpperCase() : coluna)\n/** Nome do campo de filtro: o sufixo _filter é sempre minúsculo (NOME_EMPRESA_filter). */\nexport const nomeDoFiltro = (coluna: string): string => `${nomeDoCampo(coluna)}_filter`\n",
 "e2e/dynamic/lib/guard.ts": "import fs from 'node:fs'\nimport os from 'node:os'\nimport path from 'node:path'\nimport { CONFIG } from './config'\nimport { comBanco } from './db'\nimport { bancoDoApp, detectarApp } from './app.mjs'\nimport { lerUrl, tipoDoBanco } from './banco.mjs'\nimport type { TestManifest } from '../../../src/lib/testing/manifestTypes'\nimport { campoMarcador, PREFIXO_E2E } from '../../../src/lib/testing/plan'\n\n/**\n * Trava de segurança do motor dinâmico, para qualquer projeto e banco (Postgres ou Oracle; não conhece tabelas de antemão):\n *  1. antes de começar: o banco de teste tem de ser uma cópia que o cliente confirmou, ou o banco original com o consentimento dele; o motor injeta esta conexão no app, então o app e a conferência usam o mesmo banco;\n *  2. durante: o motor só lê; a única regra que poderia gravar (salvar o formulário vazio) apaga o que criou e falha;\n *  3. no fim: a \"impressão digital\" de cada tabela dos casos de uso (quantidade de linhas e um resumo de todo o conteúdo) tem de ser a mesma do início.\n */\n\nconst IDENT = /^[a-zA-Z_][a-zA-Z0-9_]*$/\nconst LIMITE_RESUMO = 200_000\n\n/** Endereços desta máquina (o Oracle escuta no IP da placa de rede, não em localhost). */\nconst enderecosDestaMaquina = () => new Set(['localhost', '127.0.0.1', '::1', os.hostname().toLowerCase(), ...Object.values(os.networkInterfaces()).flatMap(l => (l || []).map(i => i.address.toLowerCase()))])\n\nexport function assertSeguro() {\n  const app = detectarApp(CONFIG.appDir)\n  if (!CONFIG.appDir || !fs.existsSync(path.join(app.frontendDir, 'package.json'))) throw new Error(`Não achei o app exportado em \"${CONFIG.appDir}\".`)\n  if (!CONFIG.dbUrl) throw new Error('Falta a conexão com o banco de teste (dbUrl).')\n  const tipo = tipoDoBanco(CONFIG.dbUrl)\n  if (!tipo) throw new Error(`O banco \"${CONFIG.dbUrl.split(':')[0]}\" ainda não é suportado pelos testes automáticos (só PostgreSQL e Oracle).`)\n  if (!CONFIG.noAuth && (!CONFIG.user || !CONFIG.password)) throw new Error('Falta o usuário de teste do app (a IDE o cria no banco de teste).')\n  const teste = lerUrl(CONFIG.dbUrl)\n  if (CONFIG.mode === 'copy') {\n    // cópia informada pelo cliente: pode estar em qualquer lugar, mas só vale se ele confirmou que é uma cópia (o motor injeta esta conexão no app)\n    if (!CONFIG.copyConfirmed) throw new Error('Recusado: falta a confirmação de que o banco informado é uma cópia de teste (não o banco de produção).')\n  } else {\n    // banco original do app: só com o consentimento do cliente (ou, no repositório, na lista de bancos permitidos e local)\n    if (!CONFIG.consentOriginal) throw new Error('Recusado: rodar no banco original do app exige o consentimento do cliente, dado na IDE.')\n    const doApp = bancoDoApp(app)\n    if (!doApp) throw new Error('Não consegui descobrir qual banco o app exportado usa (DATABASE_URL, DB_CONNECTION_STRING ou application.properties).')\n    const mesmo = doApp.host.toLowerCase() === teste.host.toLowerCase() && doApp.banco.toLowerCase() === teste.banco.toLowerCase() && doApp.tipo === tipo\n    if (!mesmo) throw new Error(`Recusado: o app exportado usa o banco \"${doApp.banco}\" em ${doApp.host}, mas o banco de teste configurado é \"${teste.banco}\" em ${teste.host}. Eles precisam ser o mesmo.`)\n    if (!CONFIG.allowRemote && !enderecosDestaMaquina().has(teste.host.toLowerCase())) throw new Error(`Recusado: o banco de teste está em ${teste.host}, que não é esta máquina, e não há consentimento do cliente para banco remoto.`)\n  }\n  const permitidos = (CONFIG.allowedDbs.length > 0 ? CONFIG.allowedDbs : [teste.banco]).map(b => b.toLowerCase())\n  if (!permitidos.includes(teste.banco.toLowerCase())) throw new Error(`Recusado: o banco \"${teste.banco}\" está fora da lista permitida (${permitidos.join(', ')}).`)\n}\n\n/** Tabelas que os casos de uso leem ou gravam (a do caso de uso, as abas de detalhe e os subdetalhes). */\nexport function tabelasDoManifesto(m: TestManifest): string[] {\n  const set = new Set<string>()\n  for (const v of m.views) {\n    if (v.table) set.add(v.table)\n    for (const d of v.details) { set.add(d.table); for (const s of d.subDetails) set.add(s.table) }\n  }\n  return [...set].filter(t => IDENT.test(t)).sort()\n}\n\nexport type Impressao = Record<string, { linhas: number; resumo: string }>\n\n/** Quantidade de linhas e um resumo de todo o conteúdo de cada tabela (md5 no Postgres, soma de hashes no Oracle); em tabelas enormes, só a quantidade. */\nexport async function impressaoDigital(tabelas: string[]): Promise<Impressao> {\n  return comBanco(async d => {\n    const out: Impressao = {}\n    for (const t of tabelas) {\n      let n = -1\n      try { n = Number((await d.query(`select count(*) as n from \"${t}\"`))[0].n) } catch { /* tabela inexistente */ }\n      if (n < 0) { out[t] = { linhas: -1, resumo: 'tabela inexistente' }; continue }\n      let resumo = ''\n      if (n <= LIMITE_RESUMO) {\n        if (d.dialect === 'oracle') {\n          // um hash por coluna (CLOB: os primeiros 1000 caracteres; RAW: hexadecimal; BLOB fica de fora), cada um com um peso diferente conforme a posição da coluna; a soma de todas as linhas é o resumo.\n          // Nada de concatenar as colunas numa expressão só: ela estoura o limite de texto do Oracle (ORA-01489) em tabelas largas.\n          const cols = (await d.colunas(t)).filter((c: any) => !/blob|^long|xmltype|bfile/.test(c.data_type))\n          const parte = (c: any, i: number) => {\n            const id = d.ident(c.column_name)\n            const texto = /clob/.test(c.data_type) ? `nvl(dbms_lob.substr(${id}, 1000, 1), '-')` : /^raw/.test(c.data_type) ? `nvl(rawtohex(${id}), '-')` : `nvl(to_char(${id}), '-')`\n            return `ora_hash(${texto}) * ${2 * i + 3}`\n          }\n          resumo = cols.length ? String((await d.query(`select nvl(sum(${cols.map(parte).join(' + ')}), 0) as h from \"${t}\"`))[0].h) : ''\n        } else {\n          resumo = String((await d.query(`select coalesce(md5(string_agg(x::text, ',' order by x::text)), '') as h from \"${t}\" x`))[0].h)\n        }\n      }\n      out[t] = { linhas: n, resumo }\n    }\n    return out\n  })\n}\n\nexport function diferencas(antes: Impressao, depois: Impressao): string[] {\n  const difs: string[] = []\n  for (const t of Object.keys(antes)) {\n    const a = antes[t], d = depois[t]\n    if (a.linhas !== d?.linhas) difs.push(`${t}: ${a.linhas} → ${d?.linhas} linhas`)\n    else if (a.resumo !== d?.resumo) difs.push(`${t}: o conteúdo de linhas existentes foi alterado`)\n  }\n  return difs\n}\n\nexport const arquivoBase = (): string => path.join(import.meta.dirname, '..', '..', 'test-results-dynamic', 'baseline.json')\n\n/** Onde o teste de integração pode ter deixado linhas: (tabela, coluna de identificação) dos casos de uso Pesquisa + Cadastro. */\nexport function alvosDeLimpeza(m: TestManifest): Array<{ tabela: string; coluna: string }> {\n  const out: Array<{ tabela: string; coluna: string }> = []\n  for (const v of m.views) {\n    const c = v.logicType === 'pesquisa_cadastro' ? campoMarcador(v) : undefined\n    if (c && IDENT.test(v.table) && IDENT.test(c.column) && !out.some(o => o.tabela === v.table && o.coluna === c.column)) out.push({ tabela: v.table, coluna: c.column })\n  }\n  return out\n}\n\n/**\n * Apaga as linhas geradas pelo teste de integração (texto que começa com \"E2E-\" na coluna de identificação): sobras de uma rodada interrompida ou de uma falha no meio.\n * Dá algumas passadas porque uma linha pode depender de outra (chave estrangeira): o erro da primeira tentativa some quando a dependente já foi apagada.\n */\nexport async function limparSobras(alvos: Array<{ tabela: string; coluna: string }>) {\n  await comBanco(async d => {\n    for (let passada = 0; passada < 3; passada++) {\n      for (const { tabela, coluna } of alvos) {\n        await d.query(`delete from \"${tabela}\" where \"${coluna}\"::text like $1`, [PREFIXO_E2E + '%']).catch(() => {})\n      }\n    }\n  })\n}\n\n// ---------------------------------------------------------------------------------------------------------------------\n// Diário dos registros criados pelo teste de integração em telas SEM campo de texto para marcar com E2E-\n// ---------------------------------------------------------------------------------------------------------------------\n\ninterface Anotacao { tabela: string; pk: string; id: string }\nconst arquivoDiario = () => path.join(import.meta.dirname, '..', '..', '.apps', 'crud-journal.json')\nconst lerDiario = (): Anotacao[] => { try { return JSON.parse(fs.readFileSync(arquivoDiario(), 'utf8')) as Anotacao[] } catch { return [] } }\nconst gravarDiario = (a: Anotacao[]) => { fs.mkdirSync(path.dirname(arquivoDiario()), { recursive: true }); fs.writeFileSync(arquivoDiario(), JSON.stringify(a)) }\n\n/** Anota o registro recém-criado: se o teste cair antes de excluí-lo, a próxima limpeza (ou a do fim da rodada) o apaga pelo id. */\nexport function anotarCriado(tabela: string, pk: string, id: string) { gravarDiario([...lerDiario().filter(x => x.id !== id || x.tabela !== tabela), { tabela, pk, id }]) }\nexport function riscarCriado(tabela: string, id: string) { gravarDiario(lerDiario().filter(x => !(x.tabela === tabela && x.id === id))) }\n\n/** Apaga o que o diário ainda lista (sobras). Uma linha que depende de outra pode exigir mais de uma passada. */\nexport async function limparDiario() {\n  const itens = lerDiario().filter(x => IDENT.test(x.tabela) && IDENT.test(x.pk))\n  if (itens.length === 0) return\n  await comBanco(async d => {\n    for (let passada = 0; passada < 3; passada++) {\n      for (const x of itens) await d.query(`delete from \"${x.tabela}\" where \"${x.pk}\"::text = $1`, [x.id]).catch(() => {})\n    }\n  })\n  gravarDiario([])\n}\n",
 "e2e/dynamic/lib/acesso.mjs": "// Usuários, grupos e permissões de teste no banco de teste, para QUALQUER projeto e para os dois bancos (Postgres e Oracle): tabelas e colunas vêm da configuração\n// de login do manifesto (auth); o adaptador (banco.mjs) cuida das diferenças de SQL. Usado pela ferramenta de banco (db-tool.mjs) e pelos testes de segurança.\n// Só mexe no que cria: usuários e2e_* , grupos E2E-Perm* e as linhas deles.\nimport crypto from 'node:crypto'\nimport bcrypt from 'bcryptjs'\n\nconst q = s => `'${String(s).replace(/'/g, \"''\")}'`\n\nexport const EMAIL_SEG = 'e2e_seg_%@metabuilder.local'\nexport const GRUPO_SEG = 'E2E-Perm%'\n\nexport function hashSenha(formato, senha) {\n  const f = String(formato || 'bcrypt').toLowerCase()\n  return f === 'bcrypt' ? bcrypt.hashSync(senha, 10)\n    : f === 'md5' ? crypto.createHash('md5').update(senha).digest('hex')\n    : f === 'sha256' ? crypto.createHash('sha256').update(senha).digest('hex')\n    : senha\n}\n\n/** Valor SQL para uma coluna obrigatória que o teste não conhece: o mínimo que a faz aceitar a linha. */\nfunction valorPadrao(d, col, ehChave, rotulo) {\n  const t = col.data_type\n  if (ehChave && /char|text/.test(t)) return q(`e2e-${crypto.randomBytes(6).toString('hex')}`)\n  if (t === 'boolean') return 'true'\n  if (t === 'uuid') return 'gen_random_uuid()'\n  if (/timestamp|date|time/.test(t)) return d.agora\n  if (/int|numeric|decimal|real|double|number|float/.test(t)) return '0'\n  if (/json/.test(t)) return \"'{}'\"\n  return q(rotulo)\n}\n\n/** Coluna de \"ativo\" do usuário: boolean no Postgres, texto 'true' no Oracle. */\nconst ehAtivo = (d, col) => ['ativo', 'active', 'enabled'].includes(col.column_name) && (col.data_type === 'boolean' || (d.dialect === 'oracle' && /char/.test(col.data_type)))\n\n/** Insere uma linha informando só o que se sabe (`dados`: coluna → valor) e completando as colunas obrigatórias sem valor padrão. Devolve a chave primária (texto). */\nasync function inserir(d, tabela, pk, dados, rotulo) {\n  const cols = await d.colunas(tabela)\n  if (cols.length === 0) throw new Error(`A tabela \"${tabela}\" não existe no banco de teste.`)\n  const nomes = [], exprs = [], params = []\n  const usadas = new Set(Object.keys(dados).map(c => c.toLowerCase()))\n  for (const [col, v] of Object.entries(dados)) { nomes.push(d.ident(col)); exprs.push(`$${params.push(v)}`) }\n  for (const col of cols) {\n    if (usadas.has(col.column_name)) continue\n    const ativo = ehAtivo(d, col)\n    const obrigatoria = col.is_nullable === 'NO' && col.column_default == null\n    if (!ativo && !obrigatoria) continue\n    nomes.push(d.ident(col.column_name)); exprs.push(ativo ? d.verdadeiro : valorPadrao(d, col, col.column_name === pk.toLowerCase(), rotulo))\n  }\n  return d.inserir(d.ident(tabela), pk, nomes, exprs, params)\n}\n\nconst usuarioPor = async (d, auth, email) => (await d.query(`select ${d.ident(auth.usersPk || 'id')}::text as id from ${d.ident(auth.usersTable)} where ${d.ident(auth.emailColumn)} = $1`, [email]))[0]?.id\n\n/** Cria o usuário (ou renova a senha do que já existe). Devolve { id, criado }. */\nexport async function upsertUsuario(d, auth, { email, nome, senha }) {\n  const hash = hashSenha(auth.hash, senha)\n  const pkU = auth.usersPk || 'id'\n  let uid = await usuarioPor(d, auth, email)\n  if (uid) {\n    const cols = await d.colunas(auth.usersTable)\n    const sets = [`${d.ident(auth.passwordColumn)} = $1`]\n    for (const col of cols) if (ehAtivo(d, col)) sets.push(`${d.ident(col.column_name)} = ${d.verdadeiro}`)\n    await d.query(`update ${d.ident(auth.usersTable)} set ${sets.join(', ')} where ${d.ident(pkU)}::text = $2`, [hash, uid])\n    return { id: uid, criado: false }\n  }\n  const dados = { [auth.emailColumn]: email, [auth.passwordColumn]: hash }\n  if (auth.nameColumn) dados[auth.nameColumn] = nome\n  uid = await inserir(d, auth.usersTable, pkU, dados, nome)\n  return { id: uid || await usuarioPor(d, auth, email), criado: true }\n}\n\n/** Coloca o usuário no grupo: linha na tabela de vínculo, ou a coluna do grupo na própria tabela de usuários (só se estiver vazia). */\nexport async function colocarNoGrupo(d, auth, userId, groupId) {\n  const link = auth.access?.link\n  if (link?.kind === 'table') {\n    const ja = (await d.query(`select 1 as x from ${d.ident(link.table)} where ${d.ident(link.userColumn)}::text = $1 and ${d.ident(link.roleColumn)}::text = $2`, [userId, groupId])).length > 0\n    if (!ja) await d.query(`insert into ${d.ident(link.table)} (${d.ident(link.userColumn)}, ${d.ident(link.roleColumn)}) values ($1, $2)`, [userId, groupId])\n  } else if (link?.kind === 'column') {\n    await d.query(`update ${d.ident(auth.usersTable)} set ${d.ident(link.column)} = $1 where ${d.ident(auth.usersPk || 'id')}::text = $2 and ${d.ident(link.column)} is null`, [groupId, userId])\n  }\n}\n\n/** Grupo de administração do projeto (o primeiro cujo nome tem \"admin\"), ou null. */\nexport async function grupoAdmin(d, auth) {\n  const ac = auth.access\n  if (!ac) return null\n  const grupos = await d.query(`select ${d.ident(ac.groupsPk)}::text as id, ${d.ident(ac.groupsNameColumn)}::text as nome from ${d.ident(ac.groupsTable)}`).catch(() => [])\n  return grupos.find(g => /admin/i.test(g.nome)) ?? null\n}\n\n/** Cria um grupo temporário (nome E2E-Perm...). Devolve o id dele. */\nexport async function criarGrupo(d, auth, nome) {\n  const ac = auth.access\n  return inserir(d, ac.groupsTable, ac.groupsPk, { [ac.groupsNameColumn]: nome }, nome)\n}\n\n/** Define o nível de acesso (none, read, write) do grupo numa tela. */\nexport async function definirNivel(d, auth, groupId, viewSlug, nivel) {\n  const ac = auth.access\n  await d.query(`delete from ${d.ident(ac.permsTable)} where ${d.ident(ac.permsRoleColumn)}::text = $1 and ${d.ident(ac.permsViewColumn)} = $2`, [groupId, viewSlug])\n  await d.query(`insert into ${d.ident(ac.permsTable)} (${d.ident(ac.permsRoleColumn)}, ${d.ident(ac.permsViewColumn)}, ${d.ident(ac.permsLevelColumn)}) values ($1, $2, $3)`, [groupId, viewSlug, nivel])\n}\n\nexport async function apagarUsuario(d, auth, userId) {\n  const link = auth.access?.link\n  if (link?.kind === 'table') await d.query(`delete from ${d.ident(link.table)} where ${d.ident(link.userColumn)}::text = $1`, [userId])\n  await d.query(`delete from ${d.ident(auth.usersTable)} where ${d.ident(auth.usersPk || 'id')}::text = $1`, [userId])\n}\n\nexport async function apagarGrupo(d, auth, groupId) {\n  const ac = auth.access\n  await d.query(`delete from ${d.ident(ac.permsTable)} where ${d.ident(ac.permsRoleColumn)}::text = $1`, [groupId])\n  if (ac.link?.kind === 'table') await d.query(`delete from ${d.ident(ac.link.table)} where ${d.ident(ac.link.roleColumn)}::text = $1`, [groupId])\n  await d.query(`delete from ${d.ident(ac.groupsTable)} where ${d.ident(ac.groupsPk)}::text = $1`, [groupId])\n}\n\n/** Valor do usuário que uma regra por linha compara (e-mail, nome ou uma coluna da tabela de usuários). null = a regra não tem o dado dele. */\nexport async function valorDoUsuario(d, auth, userId, source, attr) {\n  const coluna = source === 'user.email' ? auth.emailColumn : source === 'user.name' ? auth.nameColumn : source === 'user.attr' ? attr : null\n  if (!coluna) return null\n  return (await d.query(`select ${d.ident(coluna)}::text as v from ${d.ident(auth.usersTable)} where ${d.ident(auth.usersPk || 'id')}::text = $1`, [userId]))[0]?.v ?? null\n}\n\n/** Remove o que os testes de segurança criaram e ficou para trás: usuários e2e_seg_*, grupos E2E-Perm* (com permissões e vínculos). */\nexport async function limparSeguranca(d, auth) {\n  if (!auth?.usersTable) return\n  const usuarios = await d.query(`select ${d.ident(auth.usersPk || 'id')}::text as id from ${d.ident(auth.usersTable)} where ${d.ident(auth.emailColumn)} like $1`, [EMAIL_SEG]).catch(() => [])\n  for (const u of usuarios) await apagarUsuario(d, auth, u.id).catch(() => {})\n  const ac = auth.access\n  if (ac) {\n    const grupos = await d.query(`select ${d.ident(ac.groupsPk)}::text as id from ${d.ident(ac.groupsTable)} where ${d.ident(ac.groupsNameColumn)}::text like $1`, [GRUPO_SEG]).catch(() => [])\n    for (const g of grupos) await apagarGrupo(d, auth, g.id).catch(() => {})\n  }\n}\n\n// ---------------------------------------------------------------------------------------------------------------------\n// Conferências das telas de gestão de acesso (só leem, exceto apagar o que o próprio teste criou)\n// ---------------------------------------------------------------------------------------------------------------------\n\nexport const usuarioPorEmail = (d, auth, email) => usuarioPor(d, auth, email)\n\n/** Id do grupo do usuário (vínculo em tabela ou coluna do próprio usuário); null = sem grupo. */\nexport async function grupoDoUsuario(d, auth, userId) {\n  const link = auth.access?.link\n  if (link?.kind === 'table') return (await d.query(`select ${d.ident(link.roleColumn)}::text as g from ${d.ident(link.table)} where ${d.ident(link.userColumn)}::text = $1`, [userId]))[0]?.g ?? null\n  if (link?.kind === 'column') return (await d.query(`select ${d.ident(link.column)}::text as g from ${d.ident(auth.usersTable)} where ${d.ident(auth.usersPk || 'id')}::text = $1`, [userId]))[0]?.g ?? null\n  return null\n}\n\n/** Os grupos do projeto: [{ id, nome }]. */\nexport async function listarGrupos(d, auth) {\n  const ac = auth.access\n  return d.query(`select ${d.ident(ac.groupsPk)}::text as id, ${d.ident(ac.groupsNameColumn)}::text as nome from ${d.ident(ac.groupsTable)}`)\n}\n\n/** Usuários de verdade (fora os temporários e o robô do motor), para conferir a lista da tela. */\nexport async function usuariosReais(d, auth, limite = 5) {\n  const todos = await d.query(`select ${d.ident(auth.usersPk || 'id')}::text as id, ${d.ident(auth.emailColumn)}::text as email from ${d.ident(auth.usersTable)}`)\n  return todos.filter(u => !/^e2e_(seg_|motor)/i.test(String(u.email))).slice(0, limite)\n}\n\n/** Resumo do vínculo usuário-grupo de TODOS os usuários que não são temporários: não pode mudar quando se troca o grupo de um usuário ou se exclui um. */\nexport async function vinculosDeOutros(d, auth) {\n  const link = auth.access?.link\n  let rows = []\n  if (link?.kind === 'table') {\n    rows = await d.query(`select ${d.ident('u')}.${d.ident(auth.emailColumn)}::text as email, l.${d.ident(link.roleColumn)}::text as g from ${d.ident(link.table)} l join ${d.ident(auth.usersTable)} u on u.${d.ident(auth.usersPk || 'id')} = l.${d.ident(link.userColumn)}`)\n  } else if (link?.kind === 'column') {\n    rows = await d.query(`select ${d.ident(auth.emailColumn)}::text as email, ${d.ident(link.column)}::text as g from ${d.ident(auth.usersTable)}`)\n  }\n  return JSON.stringify(rows.filter(r => !/^e2e_seg_/i.test(String(r.email))).map(r => `${r.email}|${r.g}`).sort())\n}\n\nexport async function lerHashDoUsuario(d, auth, userId) {\n  return (await d.query(`select ${d.ident(auth.passwordColumn)}::text as h from ${d.ident(auth.usersTable)} where ${d.ident(auth.usersPk || 'id')}::text = $1`, [userId]))[0]?.h ?? null\n}\n\n/** A senha confere com o hash gravado (no formato do projeto)? */\nexport function confereSenha(formato, senha, hash) {\n  const f = String(formato || 'bcrypt').toLowerCase()\n  return f === 'bcrypt' ? bcrypt.compareSync(senha, String(hash)) : hashSenha(f, senha) === hash\n}\n\n/** Nível gravado do grupo numa tela (none, read, write); null = sem linha (a tela segue o padrão). */\nexport async function nivelDoGrupo(d, auth, groupId, viewSlug) {\n  const ac = auth.access\n  return (await d.query(`select ${d.ident(ac.permsLevelColumn)}::text as n from ${d.ident(ac.permsTable)} where ${d.ident(ac.permsRoleColumn)}::text = $1 and ${d.ident(ac.permsViewColumn)} = $2`, [groupId, viewSlug]))[0]?.n ?? null\n}\n",
 "e2e/dynamic/lib/banco.mjs": "// Acesso ao banco de teste em dois dialetos (Postgres e Oracle) com a mesma interface, para o motor inteiro (trava, ferramenta de banco, testes de segurança e specs).\n// O SQL do motor é escrito no jeito do Postgres; para o Oracle ele é traduzido aqui (binds, identificadores em maiúsculas, ::text, limit).\n// Conexão por URL: postgres://usuario:senha@host:5432/banco · oracle://usuario:senha@host:1521/SERVICO\nimport crypto from 'node:crypto'\nimport pg from 'pg'\n\nconst IDENT = /^[a-zA-Z_][a-zA-Z0-9_$]*$/\n\n/** Tipo de banco da URL: postgres ou oracle (null = ainda sem suporte nos testes). */\nexport function tipoDoBanco(url) {\n  const p = String(url || '').split(':')[0].toLowerCase()\n  return p.startsWith('oracle') ? 'oracle' : p.startsWith('postgres') ? 'postgres' : null\n}\n\nexport function lerUrl(url) {\n  const u = new URL(url)\n  return { tipo: tipoDoBanco(url), host: u.hostname, porta: u.port || (tipoDoBanco(url) === 'oracle' ? '1521' : '5432'), banco: decodeURIComponent(u.pathname.replace(/^\\//, '')), usuario: decodeURIComponent(u.username), senha: decodeURIComponent(u.password) }\n}\n\n/** SQL do jeito do Postgres → SQL do Oracle: $1 vira bind nomeado, \"ident\" fica em maiúsculas, x::text vira to_char(x), outros casts somem, now() e limit N. */\nexport function traduzirParaOracle(sql, params = []) {\n  const binds = {}\n  // só fora dos textos entre aspas simples ('12:00:00' não é bind)\n  const texto = sql.split(/('(?:[^']|'')*')/).map((parte, i) => {\n    if (i % 2 === 1) return parte\n    return parte\n      .replace(/\\$(\\d+)/g, (_m, n) => { binds['b' + n] = params[Number(n) - 1]; return ':b' + n })\n      .replace(/\"([A-Za-z_][A-Za-z0-9_$]*)\"/g, (_m, id) => `\"${id.toUpperCase()}\"`)\n      .replace(/((?:(?:\"[^\"]+\"|\\b[A-Za-z_][A-Za-z0-9_$]*)\\.)*(?:\"[^\"]+\"|\\b[A-Za-z_][A-Za-z0-9_$]*))::text\\b/g, 'to_char($1)')\n      .replace(/::\\w+/g, '')\n      .replace(/\\bnow\\(\\)/gi, 'systimestamp')\n  }).join('').replace(/\\blimit\\s+(\\d+)\\s*$/i, 'fetch first $1 rows only')\n  return { texto, binds }\n}\n\nconst minusculas = row => Object.fromEntries(Object.entries(row).map(([k, v]) => [k.toLowerCase(), v]))\n\nasync function abrirPostgres(url) {\n  const c = new pg.Client({ connectionString: url, connectionTimeoutMillis: 8000 })\n  await c.connect()\n  return {\n    dialect: 'postgres',\n    ident: n => { if (!IDENT.test(n)) throw new Error(`nome inválido: ${n}`); return `\"${n}\"` },\n    verdadeiro: 'true',\n    agora: 'now()',\n    txt: (ident) => `${ident}::text`,\n    query: async (sql, params = []) => (await c.query(sql, params)).rows,\n    /** insere e devolve a chave primária (texto) */\n    inserir: async (tabela, pk, nomes, exprs, params) => (await c.query(`insert into ${tabela} (${nomes.join(', ')}) values (${exprs.join(', ')}) returning \"${pk}\"::text as pk`, params)).rows[0].pk,\n    colunas: async tabela => (await c.query(\"select column_name, data_type, is_nullable, column_default, character_maximum_length as max_length from information_schema.columns where table_schema = current_schema() and table_name = $1\", [tabela])).rows,\n    tabelas: async () => new Set((await c.query(\"select table_name from information_schema.tables where table_schema not in ('pg_catalog','information_schema')\")).rows.map(r => r.table_name)),\n    versao: async () => { const r = (await c.query('select version() as v, current_database() as d, pg_size_pretty(pg_database_size(current_database())) as sz')).rows[0]; return { banco: r.d, versao: String(r.v).split(' ').slice(0, 2).join(' '), tamanho: r.sz } },\n    fechar: () => c.end().catch(() => {}),\n  }\n}\n\nasync function abrirOracle(url) {\n  const db = (await import('oracledb')).default\n  db.fetchAsString = [db.CLOB]\n  const u = lerUrl(url)\n  const conn = await db.getConnection({ user: u.usuario, password: u.senha, connectString: `${u.host}:${u.porta}/${u.banco}` })\n  // formato da sessão do motor igual ao do Postgres: ponto decimal e datas em ISO (senão to_char devolve '15,5' e '25/10/26 12:00:00,000000' conforme o idioma do servidor)\n  await conn.execute(\"alter session set nls_numeric_characters = '.,' nls_date_format = 'YYYY-MM-DD HH24:MI:SS' nls_timestamp_format = 'YYYY-MM-DD HH24:MI:SS.FF6' nls_timestamp_tz_format = 'YYYY-MM-DD HH24:MI:SS.FF6 TZH:TZM'\")\n  const rodar = async (texto, binds = {}, extra = {}) => conn.execute(texto, binds, { outFormat: db.OUT_FORMAT_OBJECT, autoCommit: true, ...extra })\n  return {\n    dialect: 'oracle',\n    ident: n => { if (!IDENT.test(n)) throw new Error(`nome inválido: ${n}`); return `\"${n.toUpperCase()}\"` },\n    // o Oracle do projeto guarda \"booleano\" como texto 'true'/'false'\n    verdadeiro: \"'true'\",\n    agora: 'systimestamp',\n    txt: (ident, tipo) => (tipo === 'data' || tipo === 'data-hora') ? `to_char(${ident}, 'YYYY-MM-DD HH24:MI:SS')` : `to_char(${ident})`,\n    query: async (sql, params = []) => { const { texto, binds } = traduzirParaOracle(sql, params); return ((await rodar(texto, binds)).rows || []).map(minusculas) },\n    inserir: async (tabela, pk, nomes, exprs, params) => {\n      const { texto, binds } = traduzirParaOracle(`insert into ${tabela} (${nomes.join(', ')}) values (${exprs.join(', ')})`, params)\n      const r = await rodar(`${texto} returning \"${pk.toUpperCase()}\" into :rid`, { ...binds, rid: { dir: db.BIND_OUT, type: db.STRING, maxSize: 4000 } })\n      return String(r.outBinds.rid[0])\n    },\n    colunas: async tabela => ((await rodar('select column_name, data_type, char_length, nullable, data_default from user_tab_columns where table_name = :t order by column_id', { t: String(tabela).toUpperCase() })).rows || []).map(r => ({\n      column_name: String(r.COLUMN_NAME).toLowerCase(), data_type: String(r.DATA_TYPE).toLowerCase(), is_nullable: r.NULLABLE === 'Y' ? 'YES' : 'NO',\n      column_default: r.DATA_DEFAULT == null ? null : String(r.DATA_DEFAULT).trim(), max_length: r.CHAR_LENGTH ? Number(r.CHAR_LENGTH) : null,\n    })),\n    tabelas: async () => new Set(((await rodar('select table_name from user_tables')).rows || []).map(r => String(r.TABLE_NAME).toLowerCase())),\n    versao: async () => ({ banco: u.banco, versao: String(((await rodar(\"select banner from v$version where rownum = 1\")).rows || [])[0]?.BANNER || 'Oracle').split(' - ')[0].slice(0, 60), tamanho: '—' }),\n    fechar: () => conn.close().catch(() => {}),\n  }\n}\n\n/** Abre a conexão do banco de teste. Quem abre fecha (`fechar`). */\nexport async function abrirBanco(url) {\n  const tipo = tipoDoBanco(url)\n  if (tipo === 'oracle') return abrirOracle(url)\n  if (tipo === 'postgres') return abrirPostgres(url)\n  throw new Error(`Banco \"${String(url).split(':')[0]}\" ainda não é suportado pelos testes automáticos (só PostgreSQL e Oracle).`)\n}\n\nexport const novoUuid = () => crypto.randomUUID()\n\n/**\n * O que o app exportado lê para saber qual banco usar, por pilha. O motor injeta estas variáveis ao subir o app, para ele usar o banco de TESTE\n * (variável de ambiente vale mais que o .env.local do Node e que o application.properties do Spring).\n */\nexport function envParaApp(url, pilha) {\n  const u = lerUrl(url)\n  if (pilha === 'java') {\n    return {\n      SPRING_DATASOURCE_URL: u.tipo === 'oracle' ? `jdbc:oracle:thin:@//${u.host}:${u.porta}/${u.banco}` : `jdbc:postgresql://${u.host}:${u.porta}/${u.banco}`,\n      SPRING_DATASOURCE_USERNAME: u.usuario, SPRING_DATASOURCE_PASSWORD: u.senha,\n    }\n  }\n  if (u.tipo === 'oracle') return { DB_CONNECTION_STRING: `${u.host}:${u.porta}/${u.banco}`, DB_USER: u.usuario, DB_PASSWORD: u.senha }\n  return { DATABASE_URL: url }\n}\n",
 "e2e/dynamic/lib/app.mjs": "// O app exportado: Node (uma pasta com o Next) ou Java (backend/ Spring Boot + frontend/ Next), e qual banco ele usa.\nimport fs from 'node:fs'\nimport path from 'node:path'\n\n/** Pilha do app a partir da pasta escolhida: Java se tem backend/pom.xml e frontend/package.json; senão Node. */\nexport function detectarApp(appDir) {\n  const java = !!appDir && fs.existsSync(path.join(appDir, 'backend', 'pom.xml')) && fs.existsSync(path.join(appDir, 'frontend', 'package.json'))\n  return java\n    ? { pilha: 'java', raiz: appDir, frontendDir: path.join(appDir, 'frontend'), backendDir: path.join(appDir, 'backend') }\n    : { pilha: 'node', raiz: appDir, frontendDir: appDir, backendDir: null }\n}\n\nconst lerEnv = arquivo => {\n  const out = {}\n  if (!fs.existsSync(arquivo)) return out\n  for (const l of fs.readFileSync(arquivo, 'utf8').split(/\\r?\\n/)) {\n    const m = /^([A-Z_0-9]+)=(.*)$/.exec(l)\n    if (m) out[m[1]] = m[2].replace(/^\"|\"$/g, '')\n  }\n  return out\n}\n\n/** Banco que o app exportado usa por conta própria (sem a injeção do motor): { tipo, host, banco }. null se não deu para descobrir. */\nexport function bancoDoApp(app) {\n  if (app.pilha === 'java') {\n    const f = path.join(app.backendDir, 'src', 'main', 'resources', 'application.properties')\n    if (!fs.existsSync(f)) return null\n    const m = /^spring\\.datasource\\.url\\s*=\\s*jdbc:(postgresql|oracle:thin):(?:@)?(?:\\/\\/)?([^:/\\s]+)(?::(\\d+))?\\/([^\\s?]+)/m.exec(fs.readFileSync(f, 'utf8'))\n    return m ? { tipo: m[1] === 'postgresql' ? 'postgres' : 'oracle', host: m[2], banco: m[4] } : null\n  }\n  const env = lerEnv(path.join(app.frontendDir, '.env.local'))\n  if (env.DB_CONNECTION_STRING) {\n    const m = /^(?:\\/\\/)?([^:/]+)(?::(\\d+))?\\/(.+)$/.exec(env.DB_CONNECTION_STRING)\n    return m ? { tipo: 'oracle', host: m[1], banco: m[3] } : null\n  }\n  if (env.DATABASE_URL) { try { const u = new URL(env.DATABASE_URL); return { tipo: 'postgres', host: u.hostname, banco: u.pathname.replace(/^\\//, '') } } catch { return null } }\n  return null\n}\n",
 "e2e/dynamic/lib/seguranca.ts": "import crypto from 'node:crypto'\nimport { CONFIG } from './config'\nimport * as acesso from './acesso.mjs'\nimport { abrirBanco } from './banco.mjs'\nimport type { ManifestAuth } from '../../../src/lib/testing/manifestTypes'\n\n/** Ligação dos testes de segurança com o banco de teste (Postgres ou Oracle): usuários, grupos e níveis de acesso temporários (tudo em lib/acesso.mjs). */\n\ntype Banco = Awaited<ReturnType<typeof abrirBanco>>\n\nexport async function comBanco<T>(fn: (d: Banco) => Promise<T>): Promise<T> {\n  const d = await abrirBanco(CONFIG.dbUrl)\n  try { return await fn(d) } finally { await d.fechar() }\n}\n\nexport interface UsuarioTemporario { id: string; email: string; senha: string; grupoId?: string }\n\n/** Sufixo único desta rodada (para os nomes dos usuários e grupos temporários). */\nexport const unico = () => crypto.randomBytes(4).toString('hex')\n\n/**\n * Cria um usuário temporário (e2e_seg_...) e, se pedido, um grupo temporário (E2E-Perm...) com o nível de acesso dado numa tela.\n * Devolve o que o teste precisa para entrar e para limpar depois.\n */\nexport async function criarUsuarioTemporario(auth: ManifestAuth, opts: { nivel?: { viewSlug: string; nivel: 'none' | 'read' | 'write' }; grupoSemRestricao?: boolean } = {}): Promise<UsuarioTemporario> {\n  const sufixo = unico()\n  const email = `e2e_seg_${sufixo}@metabuilder.local`\n  const senha = crypto.randomBytes(12).toString('base64url')\n  return comBanco(async d => {\n    let grupoId: string | undefined\n    // com a gestão de acesso ligada, quem não está em nenhum grupo não acessa tela nenhuma: o usuário temporário precisa de um grupo (sem linhas de permissão = telas liberadas)\n    if ((opts.nivel || opts.grupoSemRestricao) && auth.access) {\n      grupoId = await acesso.criarGrupo(d, auth, `E2E-Perm-${sufixo}`)\n      if (opts.nivel) await acesso.definirNivel(d, auth, grupoId, opts.nivel.viewSlug, opts.nivel.nivel)\n    }\n    const u = await acesso.upsertUsuario(d, auth, { email, nome: `E2E Seg ${sufixo}`, senha })\n    if (grupoId) await acesso.colocarNoGrupo(d, auth, u.id, grupoId)\n    return { id: u.id, email, senha, grupoId }\n  })\n}\n\n/** Apaga o usuário e o grupo temporários (e o que pendura neles). */\nexport async function removerUsuarioTemporario(auth: ManifestAuth, u: UsuarioTemporario) {\n  await comBanco(async d => {\n    await acesso.apagarUsuario(d, auth, u.id).catch(() => {})\n    if (u.grupoId) await acesso.apagarGrupo(d, auth, u.grupoId).catch(() => {})\n  })\n}\n\n/** Valor do usuário que a regra por linha compara. */\nexport async function valorDaRegra(auth: ManifestAuth, userId: string, source: string, attr?: string): Promise<string | null> {\n  return comBanco(d => acesso.valorDoUsuario(d, auth, userId, source, attr))\n}\n\nexport async function limparSegurancaDoBanco(auth: ManifestAuth | undefined) {\n  if (!auth || auth.type !== 'database') return\n  await comBanco(d => acesso.limparSeguranca(d, auth))\n}\n",
 "e2e/dynamic/lib/login.ts": "import { expect, type Page } from '@playwright/test'\nimport { CONFIG } from './config'\n\n/** Entra no app exportado com o usuário de teste. */\nexport async function entrar(page: Page) {\n  if (CONFIG.noAuth) return // app sem login\n  await entrarComo(page, CONFIG.user, CONFIG.password)\n}\n\n/** Entra com um usuário qualquer (os testes de segurança entram com usuários temporários). */\nexport async function entrarComo(page: Page, email: string, senha: string) {\n  await page.goto('/login')\n  await page.locator('input[name=\"email\"]').fill(email)\n  await page.locator('input[name=\"password\"]').fill(senha)\n  await page.locator('button[type=\"submit\"]').click()\n  await page.waitForURL(url => !url.pathname.startsWith('/login'), { timeout: 20_000 })\n  await expect(page.getByText('Sair do Sistema').first()).toBeVisible()\n}\n",
 "e2e/dynamic/tests/manifest.spec.ts": "import { test as base, expect, type BrowserContext, type Locator, type Page, type TestInfo } from '@playwright/test'\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport { entrar, entrarComo } from '../lib/login'\nimport { criarUsuarioTemporario, removerUsuarioTemporario, valorDaRegra } from '../lib/seguranca'\nimport * as acesso from '../lib/acesso.mjs'\nimport { detectarApp } from '../lib/app.mjs'\nimport { unico } from '../lib/seguranca'\nimport { comBanco, consultar, dialeto, nomeDoCampo, nomeDoFiltro } from '../lib/db'\nimport { anotarCriado, riscarCriado } from '../lib/guard'\nimport { CONFIG } from '../lib/config'\nimport type { ManifestField, ManifestView, TestManifest } from '../../../src/lib/testing/manifestTypes'\nimport { aplicarMascara, camposDeTipo, camposEditaveis, campoDeFiltro, campoMarcador, describeName, ehData, mascaraDePadrao, planView, PREFIXO_E2E, regraDeLinha, type TestType, detalhesPreenchiveis } from '../../../src/lib/testing/plan'\n\n/**\n * Testes DINÂMICOS: não há um teste escrito por caso de uso. Este arquivo lê o manifesto (o que o dev configurou no Studio) e gera os testes de cada\n * caso de uso a partir do PLANO (src/lib/testing/plan.ts), o mesmo que o painel da IDE mostra antes de rodar. Caso de uso novo ou alterado no Studio\n * → manifesto novo → testes novos, sem escrever nada.\n *\n * Regras: todo caso de uso, de qualquer tipo, ganha \"a tela abre sem erro\". Pesquisa + Cadastro ganha também lista, formulário (campos, obrigatórios,\n * somente leitura, máscaras), grid (total, ordenação, filtro) e exportação (CSV, JSON, Excel). Outros tipos ganham o seu gabarito aos poucos.\n *\n * Segurança: nenhuma regra daqui grava no banco. A única que poderia (salvar o formulário vazio) só passa se o app RECUSAR; se algum registro for\n * criado por engano o teste apaga o que foi criado e falha. O guard (banco local da lista permitida, contagens e ligações conferidas no fim) vale como nos demais.\n *\n * Variáveis: E2E_MANIFEST (caminho do manifesto) e E2E_VIEWS (slugs dos casos de uso a testar, separados por vírgula; vazio = todos).\n */\n/**\n * \"Navegador interno\" da IDE: com E2E_STREAM=1 o navegador roda escondido e cada quadro da tela (screencast do Chrome) é gravado em E2E_LIVE_DIR/frame.jpg;\n * o painel da IDE lê esse arquivo e mostra a execução dentro dele. Grava num arquivo temporário e renomeia, para o painel nunca ler um quadro pela metade.\n */\nasync function transmitirTela(ctx: BrowserContext, pagina: Page): Promise<() => Promise<void>> {\n  if (process.env.E2E_STREAM !== '1') return async () => {}\n  const dir = process.env.E2E_LIVE_DIR || path.join(import.meta.dirname, '..', 'live')\n  fs.mkdirSync(dir, { recursive: true })\n  const quadro = path.join(dir, 'frame.jpg')\n  const tmp = path.join(dir, 'frame.tmp')\n  const cdp = await ctx.newCDPSession(pagina)\n  cdp.on('Page.screencastFrame', (f: { data: string; sessionId: number }) => {\n    try { fs.writeFileSync(tmp, Buffer.from(f.data, 'base64')); fs.renameSync(tmp, quadro) } catch { /* o painel leu no mesmo instante: o próximo quadro cobre */ }\n    cdp.send('Page.screencastFrameAck', { sessionId: f.sessionId }).catch(() => {})\n  })\n  await cdp.send('Page.startScreencast', { format: 'jpeg', quality: 60, maxWidth: 1280, maxHeight: 800 })\n  return async () => { await cdp.send('Page.stopScreencast').catch(() => {}) }\n}\n\n/**\n * Evidências das falhas (E2E_ARTIFACTS_DIR): captura da tela no momento da falha e vídeo do teste que falhou. O caminho dos arquivos vai para o\n * relator (anexos \"mb-shot\" e \"mb-video\") e dali para o painel e o histórico. O vídeo só existe quando cada teste tem a sua página (modo sem janela\n * do sistema); com a janela do sistema fica a captura de tela.\n */\nconst ARTEFATOS = process.env.E2E_ARTIFACTS_DIR || ''\nconst COM_JANELA = process.env.E2E_HEADED === '1'\n/** O vídeo precisa do ffmpeg do Playwright (npx playwright install ffmpeg). Sem ele, a falha fica só com a captura de tela. */\nconst TEM_FFMPEG = (() => {\n  try {\n    const raiz = process.env.PLAYWRIGHT_BROWSERS_PATH && process.env.PLAYWRIGHT_BROWSERS_PATH !== '0' ? process.env.PLAYWRIGHT_BROWSERS_PATH : path.join(process.env.LOCALAPPDATA || path.join(process.env.HOME || '', '.cache'), 'ms-playwright')\n    return fs.readdirSync(raiz).some(d => d.startsWith('ffmpeg-') && fs.readdirSync(path.join(raiz, d)).some(f => f.startsWith('ffmpeg')))\n  } catch { return false }\n})()\nconst nomeSeguro = (s: string) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60)\nconst anexar = (info: TestInfo, nome: string, arquivo: string) => info.attach(nome, { body: Buffer.from(arquivo), contentType: 'text/plain' })\nlet sequencia = 0\nlet compartilhada: Page | undefined\n\n/**\n * Com a janela do sistema: uma só janela para a rodada inteira (não abre e fecha a cada teste). Sem ela: uma página nova por teste (é o que permite\n * gravar o vídeo de cada um). Nos dois casos a sessão começa limpa (cookies apagados = logout) e o login é refeito, então cada teste começa do zero.\n */\nconst test = base.extend<object, { contexto: BrowserContext }>({\n  contexto: [async ({ browser }, use) => {\n    const ctx = await browser.newContext({\n      baseURL: `http://localhost:${CONFIG.port}`, locale: 'pt-BR',\n      ...(COM_JANELA ? { viewport: null } : { viewport: { width: 1280, height: 800 } }),\n      ...(!COM_JANELA && ARTEFATOS && TEM_FFMPEG ? { recordVideo: { dir: path.join(ARTEFATOS, '_video'), size: { width: 1280, height: 800 } } } : {}),\n    })\n    await use(ctx)\n    await ctx.close()\n  }, { scope: 'worker' }],\n  page: async ({ contexto }, use, testInfo) => {\n    await contexto.clearCookies()\n    let pagina: Page\n    if (COM_JANELA) {\n      if (!compartilhada || compartilhada.isClosed()) compartilhada = await contexto.newPage()\n      pagina = compartilhada\n      await pagina.goto('about:blank')\n    } else {\n      pagina = await contexto.newPage()\n    }\n    const parar = await transmitirTela(contexto, pagina)\n    await use(pagina)\n    await parar()\n    const falhou = testInfo.status !== testInfo.expectedStatus\n    const base = `${String(++sequencia).padStart(3, '0')}-${nomeSeguro(testInfo.title)}`\n    if (ARTEFATOS && falhou) {\n      fs.mkdirSync(ARTEFATOS, { recursive: true })\n      try { const png = path.join(ARTEFATOS, base + '.png'); await pagina.screenshot({ path: png }); await anexar(testInfo, 'mb-shot', png) } catch { /* página já fechada */ }\n    }\n    if (!COM_JANELA) {\n      const video = pagina.video()\n      await pagina.close().catch(() => {})\n      if (video) {\n        try {\n          if (ARTEFATOS && falhou) { const webm = path.join(ARTEFATOS, base + '.webm'); await video.saveAs(webm); await anexar(testInfo, 'mb-video', webm) }\n          await video.delete()\n        } catch { /* sem vídeo desta vez */ }\n      }\n    }\n  },\n})\n\nconst MANIFEST_PATH = process.env.E2E_MANIFEST || path.join(import.meta.dirname, '..', 'manifests', 'vendas-pg.sample.json')\nconst manifest: TestManifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8'))\n/** Tipos de teste desta rodada (E2E_TYPES): funcional só lê; integracao grava no banco de teste; seguranca cria usuários e grupos temporários. */\nconst TIPOS = (process.env.E2E_TYPES || 'funcional').split(',').map(x => x.trim()).filter((x): x is TestType => x === 'funcional' || x === 'integracao' || x === 'seguranca')\nconst escolhidos = (process.env.E2E_VIEWS || '').split(',').map(s => s.trim()).filter(Boolean)\n\nconst escapar = (s: string) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')\nconst norm = (s: string) => s.replace(/\\s+/g, ' ').trim().toLowerCase()\n\nasync function abrir(page: Page, rota: string) {\n  await page.goto(rota)\n  await page.waitForLoadState('networkidle').catch(() => {})\n}\n\n/**\n * A lista passa por uma tela de \"Conectando ao banco...\" a cada pesquisa, ordenação ou página: só depois dela aparece o \"TOTAL: n\". Ler as linhas antes\n * disso devolve uma grid vazia. Espera o total (ou, sem ele, qualquer linha).\n */\nasync function aguardarLista(page: Page) {\n  await page.waitForLoadState('networkidle', { timeout: 10_000 }).catch(() => {})\n  await page.getByText(/Conectando ao banco/i).first().waitFor({ state: 'hidden', timeout: 15_000 }).catch(() => {})\n  await page.getByText(/TOTAL:\\s*\\d+/i).first().waitFor({ timeout: 15_000 }).catch(() => {})\n}\n\n/** Telas que não são lista (kanban, mapa, BI...): não têm \"TOTAL: n\"; espera a rede assentar e as mensagens de carregamento sumirem. */\nasync function aguardarTela(page: Page) {\n  await page.waitForLoadState('networkidle', { timeout: 10_000 }).catch(() => {})\n  await page.getByText(/Conectando ao banco|Carregando/i).first().waitFor({ state: 'hidden', timeout: 15_000 }).catch(() => {})\n}\n\n/**\n * Clica em algo que NAVEGA a lista (ordenar, pesquisar, limpar) e espera a navegação terminar: a URL muda e os dados novos chegam. Sem isso o teste lê a\n * grid da página antiga (o \"TOTAL\" dela ainda está na tela) ou no meio da troca.\n */\nasync function clicarENavegar(page: Page, alvo: Locator) {\n  const antes = page.url()\n  await alvo.click()\n  await page.waitForURL(u => u.href !== antes, { timeout: 8_000 }).catch(() => {})\n  await aguardarLista(page)\n}\n\n/** \"TOTAL: 16\" que a lista mostra. null = não achou. */\nasync function totalMostrado(page: Page): Promise<number | null> {\n  const el = page.getByText(/TOTAL:\\s*\\d+/i).first()\n  if (!(await el.count())) return null\n  const m = /TOTAL:\\s*(\\d+)/i.exec(await el.innerText())\n  return m ? Number(m[1]) : null\n}\n\n/** O total da lista; uma lista sem nenhuma linha não mostra \"TOTAL: n\" e conta como 0. */\nasync function totalOuZero(page: Page): Promise<number | null> {\n  const total = await totalMostrado(page)\n  if (total !== null) return total\n  return (await linhasDoGrid(page)).length === 0 ? 0 : null\n}\n\n/** Posição da coluna do grid pelo rótulo (o cabeçalho e as células têm a mesma ordem). */\nasync function indiceColuna(page: Page, rotulo: string): Promise<number> {\n  const ths = await page.locator('thead th').allInnerTexts()\n  return ths.findIndex(t => norm(t).startsWith(norm(rotulo)))\n}\n\n/** Textos das células de cada linha de dados do grid (a linha \"sem registros\" tem uma célula só e fica de fora). */\nasync function linhasDoGrid(page: Page): Promise<string[][]> {\n  return page.locator('tbody tr').evaluateAll(trs =>\n    trs.map(tr => Array.from(tr.querySelectorAll('td')).map(td => (td as HTMLElement).innerText.trim())).filter(c => c.length > 1))\n}\n\nasync function baixar(page: Page, formato: RegExp) {\n  await page.getByRole('button', { name: /^Exportar/ }).first().click()\n  const [download] = await Promise.all([page.waitForEvent('download'), page.getByRole('button', { name: formato }).click()])\n  return { name: download.suggestedFilename(), buf: fs.readFileSync((await download.path())!) }\n}\n\n/** Cabeçalho e número de registros de um CSV (aspas protegem quebras de linha dentro do texto). */\nfunction lerCsv(texto: string): { cabecalho: string; registros: number } {\n  const t = texto.replace(/^﻿/, '')\n  const linhas: string[] = []\n  let emAspas = false\n  let inicio = 0\n  for (let i = 0; i < t.length; i++) {\n    const ch = t[i]\n    if (ch === '\"') emAspas = !emAspas\n    else if (ch === '\\n' && !emAspas) { linhas.push(t.slice(inicio, i).replace(/\\r$/, '')); inicio = i + 1 }\n  }\n  if (inicio < t.length) linhas.push(t.slice(inicio))\n  const dados = linhas.filter(l => l.length > 0)\n  return { cabecalho: dados[0] ?? '', registros: Math.max(0, dados.length - 1) }\n}\n\n// ---------------------------------------------------------------------------------------------------------------------\n// Integração: cadastro, reabrir, edição e exclusão com dados gerados (gravam no banco de teste; só com o tipo \"integracao\")\n// ---------------------------------------------------------------------------------------------------------------------\n\n/** Identificador desta rodada: todo texto gerado começa com \"E2E-\" (a limpeza de sobras só apaga linhas assim). */\nconst RODADA = PREFIXO_E2E + new Date().toISOString().replace(/[-:T]/g, '').slice(2, 12) // E2E-2610191430\n\ninterface Preenchido { tipo: 'texto' | 'texto-mascara' | 'numero-mascara' | 'numero' | 'data' | 'data-hora' | 'hora' | 'bool' | 'opcao'; esperado: string; numero?: number }\ninterface EstadoCrud { marcador: string; id?: string; preenchidos: Record<string, Preenchido>; criouEm?: number; filhos?: Array<{ tabela: string; pk: string; fk: string; id: string }> }\n/**\n * O estado entre as etapas (cadastro → reabrir → edição → exclusão) fica em arquivo, não na memória: quando um teste falha o Playwright reinicia o\n * processo de teste e a memória se perde, e as etapas seguintes ficariam sem saber qual registro foi criado.\n */\nconst arquivoEstado = (slug: string) => path.join(import.meta.dirname, '..', '..', 'test-results-dynamic', `crud-${slug}.json`)\nconst lerEstado = (slug: string): EstadoCrud | undefined => { try { return JSON.parse(fs.readFileSync(arquivoEstado(slug), 'utf8')) as EstadoCrud } catch { return undefined } }\nfunction gravarEstado(slug: string, e: EstadoCrud | undefined) {\n  fs.mkdirSync(path.dirname(arquivoEstado(slug)), { recursive: true })\n  if (e) fs.writeFileSync(arquivoEstado(slug), JSON.stringify(e))\n  else fs.rmSync(arquivoEstado(slug), { force: true })\n}\n\n/** Tamanho máximo das colunas de texto da tabela (para o valor gerado caber). */\nasync function limitesDaTabela(tabela: string): Promise<Record<string, number>> {\n  const cols = await comBanco(d => d.colunas(tabela))\n  return Object.fromEntries(cols.filter((x: any) => x.max_length).map((x: any) => [String(x.column_name).toLowerCase(), Number(x.max_length)]))\n}\nconst caber = (txt: string, limite?: number) => (limite && txt.length > limite ? txt.slice(0, limite) : txt)\n\n/** Preenche UM campo do formulário com um valor gerado, pelo tipo do componente na tela. Devolve o que gravou, ou null se o campo não dá para preencher. */\nasync function preencherCampo(page: Page, f: ManifestField, n: number, limites: Record<string, number>, marcador?: string, alvo?: (nome: string) => Locator): Promise<Preenchido | null> {\n  const campo = alvo ? alvo(nomeDoCampo(f.column)) : page.locator(`[name=\"${nomeDoCampo(f.column)}\"]`).first()\n  if (!(await campo.count())) return null\n  if ((await campo.isDisabled()) || (await campo.getAttribute('readonly')) !== null) return null\n  const tag = await campo.evaluate(e => e.tagName.toLowerCase())\n  const tipo = (await campo.getAttribute('type')) ?? ''\n  if (tag === 'select') {\n    const opcoes = await campo.locator('option').evaluateAll(os => os.map(o => (o as HTMLOptionElement).value).filter(v => v !== ''))\n    if (opcoes.length === 0) return null\n    await campo.selectOption(opcoes[0])\n    return { tipo: 'opcao', esperado: opcoes[0] }\n  }\n  if (tipo === 'checkbox') { await campo.check(); return { tipo: 'bool', esperado: 'true' } }\n  if (tipo === 'date') { await campo.fill('2026-10-25'); return { tipo: 'data', esperado: '2026-10-25' } }\n  if (tipo === 'datetime-local') { await campo.fill('2026-10-25T12:00'); return { tipo: 'data-hora', esperado: '2026-10-25' } }\n  if (tipo === 'time') { await campo.fill('12:00'); return { tipo: 'hora', esperado: '12:00' } }\n  if (tipo === 'number') { await campo.fill(String(7 + n)); return { tipo: 'numero', esperado: String(7 + n), numero: 7 + n } }\n  if (tag !== 'input' && tag !== 'textarea') return null\n  // máscara de padrão (CPF, CNPJ, telefone...): digita os dígitos e a tela formata. Em campo numérico, \"0.000\" e \"0.000,00\" são máscaras de número (milhar e centavos), tratadas abaixo\n  if (mascaraDePadrao(f.mask) && !(f.mask && /^0[0.,]*0$/.test(f.mask) && /int|numeric|decimal|float|double|number/i.test(f.dataType))) {\n    const digitos = '1234567890123456789'.slice(0, (f.mask as string).split('0').length - 1)\n    await campo.click(); await campo.pressSequentially(digitos)\n    return { tipo: 'texto-mascara', esperado: digitos }\n  }\n  // máscara numérica (0.000,00 / 0.000): os dígitos entram como centavos\n  if (f.mask && /^0[0.,]*0$/.test(f.mask) && /int|numeric|decimal|float|double|number/i.test(f.dataType)) {\n    const casas = f.mask.includes(',') ? f.mask.split(',')[1].length : 0\n    const digitos = String(1250 + n * 100)\n    await campo.click(); await campo.pressSequentially(casas ? digitos : String(7 + n))\n    return { tipo: 'numero-mascara', esperado: casas ? digitos : String(7 + n), numero: casas ? Number(digitos) / 10 ** casas : 7 + n }\n  }\n  if (/int|numeric|decimal|float|double|number/i.test(f.dataType)) { await campo.fill(String(7 + n)); return { tipo: 'numero', esperado: String(7 + n), numero: 7 + n } }\n  const texto = marcador ?? (/e-?mail/i.test(f.column) ? `e2e${n}@e2e.com.br` : `E2E texto ${n}`)\n  const valor = caber(texto, limites[f.column.toLowerCase()])\n  await campo.fill(valor)\n  return { tipo: 'texto', esperado: valor }\n}\n\n/** O que está no banco confere com o que o teste preencheu? Devolve a descrição da diferença, ou null se confere. */\nfunction conferirNoBanco(f: ManifestField, esp: Preenchido, noBanco: string | null): string | null {\n  const v = noBanco ?? ''\n  const ok = esp.tipo === 'bool' ? /^(t|true|1)$/i.test(v)\n    : esp.tipo === 'data' || esp.tipo === 'data-hora' ? v.startsWith(esp.esperado.slice(0, 10))\n    : esp.tipo === 'hora' ? v.startsWith(esp.esperado)\n    : esp.tipo === 'numero' || esp.tipo === 'numero-mascara' ? Number(v) === esp.numero\n    : esp.tipo === 'texto-mascara' ? v.replace(/\\D/g, '') === esp.esperado\n    : v === esp.esperado\n  return ok ? null : `\"${f.label}\": esperado ${esp.esperado}, no banco \"${v}\"`\n}\n\n/** A tela, ao reabrir o registro, mostra o que foi gravado? */\nasync function conferirNaTela(page: Page, f: ManifestField, esp: Preenchido): Promise<string | null> {\n  const campo = page.locator(`[name=\"${nomeDoCampo(f.column)}\"]`).first()\n  if (esp.tipo === 'bool') return (await campo.isChecked()) ? null : `\"${f.label}\": a caixa deveria estar marcada`\n  const v = await campo.inputValue()\n  const ok = esp.tipo === 'data' ? v === esp.esperado\n    : esp.tipo === 'data-hora' ? v.startsWith(esp.esperado.slice(0, 10))\n    : esp.tipo === 'numero' ? Number(v) === esp.numero\n    : esp.tipo === 'numero-mascara' ? Number(v.replace(/\\./g, '').replace(',', '.')) === esp.numero\n    : esp.tipo === 'texto-mascara' ? v.replace(/\\D/g, '') === esp.esperado\n    : v === esp.esperado\n  return ok ? null : `\"${f.label}\": esperado ${esp.esperado}, a tela mostra \"${v}\"`\n}\n\n/** O registro criado pelo cadastro ainda está no banco? Se não, as etapas seguintes falham logo, com a causa, em vez de esperar o tempo limite da tela. */\nasync function registroExiste(view: ManifestView, id: string): Promise<boolean> {\n  return Number((await consultar(`select count(*)::int n from \"${view.table}\" where \"${view.primaryKey}\"::text = $1`, [id]))[0].n) > 0\n}\n\n/** Valor de uma coluna numa linha fotografada (a foto do Postgres e a do Oracle usam o nome da coluna em caixas diferentes). */\nconst val = (j: Record<string, unknown> | undefined, nome: string): unknown => (j ? j[Object.keys(j).find(k => k.toLowerCase() === nome.toLowerCase()) ?? nome] : undefined)\n\n/**\n * Como cada coluna do Oracle é lida e devolvida sem perder nada: datas e horas com fração de segundo e números viram texto exato.\n * (Ler uma data como objeto do JavaScript perderia os microssegundos, e a devolução deixaria a linha diferente do que era.)\n */\nfunction formatoOracle(tipo: string): { ler: (c: string) => string; gravar: (b: string) => string } {\n  const NUM = `'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''`\n  if (/^timestamp.*with (local )?time zone/.test(tipo)) return { ler: c => `to_char(${c}, 'YYYY-MM-DD\"T\"HH24:MI:SS.FF9TZH:TZM')`, gravar: b => `to_timestamp_tz(${b}, 'YYYY-MM-DD\"T\"HH24:MI:SS.FF9TZH:TZM')` }\n  if (/^timestamp/.test(tipo)) return { ler: c => `to_char(${c}, 'YYYY-MM-DD\"T\"HH24:MI:SS.FF9')`, gravar: b => `to_timestamp(${b}, 'YYYY-MM-DD\"T\"HH24:MI:SS.FF9')` }\n  if (tipo === 'date') return { ler: c => `to_char(${c}, 'YYYY-MM-DD\"T\"HH24:MI:SS')`, gravar: b => `to_date(${b}, 'YYYY-MM-DD\"T\"HH24:MI:SS')` }\n  if (/^(number|float|binary_)/.test(tipo)) return { ler: c => `to_char(${c}, ${NUM})`, gravar: b => `to_number(${b}, ${NUM})` }\n  return { ler: c => c, gravar: b => b }\n}\n\n/** A tabela inteira, uma linha por id, exatamente como está (Postgres: JSON; Oracle: texto exato por coluna), para devolver depois as linhas que um arraste mudou. */\nasync function fotografar(view: ManifestView): Promise<Map<string, Record<string, unknown>>> {\n  const pk = view.primaryKey\n  if (dialeto() === 'oracle') {\n    const cols = await comBanco(d => d.colunas(view.table))\n    const lista = cols.map((c: any) => `${formatoOracle(String(c.data_type)).ler(`\"${String(c.column_name).toUpperCase()}\"`)} as \"${String(c.column_name).toUpperCase()}\"`).join(', ')\n    return new Map((await consultar(`select ${lista} from \"${view.table}\"`)).map(r => [String(val(r, pk)), r as Record<string, unknown>]))\n  }\n  return new Map((await consultar(`select \"${pk}\"::text as id, to_jsonb(t) as j from \"${view.table}\" t`)).map(r => [String(r.id), r.j as Record<string, unknown>]))\n}\n\n/**\n * Devolve ao que era (inclusive a auditoria de quem/quando gravou) as linhas que mudaram desde a foto. Os gatilhos de auditoria da tabela são\n * desligados só durante a devolução, senão a própria devolução marcaria a linha de novo (Postgres: trigger user; Oracle: all triggers).\n */\nasync function devolverLinhas(view: ManifestView, originais: Map<string, Record<string, unknown>>) {\n  const pk = view.primaryKey\n  const aDevolver = [...(await fotografar(view))].filter(([id, j]) => originais.has(id) && JSON.stringify(j) !== JSON.stringify(originais.get(id)))\n  if (aDevolver.length === 0) return\n  if (dialeto() === 'oracle') {\n    const cols = ((await comBanco(d => d.colunas(view.table))) as any[]).filter(c => String(c.column_name).toLowerCase() !== pk.toLowerCase())\n    await comBanco(async d => {\n      await d.query(`alter table \"${view.table}\" disable all triggers`)\n      try {\n        for (const [id] of aDevolver) {\n          const orig = originais.get(id)!\n          const sets = cols.map((c, i) => `\"${String(c.column_name).toUpperCase()}\" = ${formatoOracle(String(c.data_type)).gravar(`$${i + 2}`)}`)\n          await d.query(`update \"${view.table}\" set ${sets.join(', ')} where \"${pk}\" = $1`, [id, ...cols.map(c => val(orig, String(c.column_name)) ?? null)])\n        }\n      } finally { await d.query(`alter table \"${view.table}\" enable all triggers`) }\n    })\n    return\n  }\n  await comBanco(async d => {\n    await d.query('begin')\n    try {\n      await d.query(`alter table \"${view.table}\" disable trigger user`)\n      for (const [id, j] of aDevolver) await d.query(`update \"${view.table}\" t set (${Object.keys(j).map(c => `\"${c}\"`).join(', ')}) = (select ${Object.keys(j).map(c => `r.\"${c}\"`).join(', ')} from jsonb_populate_record(null::\"${view.table}\", $2::jsonb) r) where t.\"${pk}\"::text = $1`, [id, JSON.stringify(originais.get(id))])\n      await d.query(`alter table \"${view.table}\" enable trigger user`)\n      await d.query('commit')\n    } catch (e) { await d.query('rollback').catch(() => {}); throw e }\n  })\n}\n\n/** Os ids da tabela (para achar o registro novo quando não há campo de texto para marcar). null se a tabela é grande demais para isso. */\nasync function idsDaTabela(view: ManifestView): Promise<Set<string> | null> {\n  if (Number((await consultar(`select count(*)::int n from \"${view.table}\"`))[0].n) > 20_000) return null\n  return new Set((await consultar(`select \"${view.primaryKey}\"::text as id from \"${view.table}\"`)).map(r => String(r.id)))\n}\n\n/**\n * Muda UM campo já preenchido do formulário de edição (o que dá para mudar com segurança: texto, número, data ou outra opção da lista) e devolve o que ficou esperado.\n * Usado nas telas sem campo de texto marcador, onde a edição não pode mexer no identificador.\n */\nasync function editarUmCampo(page: Page, view: ManifestView, estado: EstadoCrud, limites: Record<string, number>): Promise<{ coluna: string; novo: Preenchido } | null> {\n  const ordem = ['texto', 'numero', 'data', 'opcao']\n  const candidatos = Object.entries(estado.preenchidos).sort((a, b) => ordem.indexOf(a[1].tipo) - ordem.indexOf(b[1].tipo)).filter(([, p]) => ordem.includes(p.tipo))\n  for (const [coluna, p] of candidatos) {\n    const campo = page.locator(`[name=\"${nomeDoCampo(coluna)}\"]`).first()\n    if (!(await campo.count()) || (await campo.isDisabled())) continue\n    if (p.tipo === 'texto') { const v = caber(`${p.esperado} ED`, limites[coluna.toLowerCase()]); if (v === p.esperado) continue; await campo.fill(v); return { coluna, novo: { tipo: 'texto', esperado: v } } }\n    if (p.tipo === 'numero') { const n = (p.numero ?? 0) + 1; await campo.fill(String(n)); return { coluna, novo: { tipo: 'numero', esperado: String(n), numero: n } } }\n    if (p.tipo === 'data') { await campo.fill('2026-10-26'); return { coluna, novo: { tipo: 'data', esperado: '2026-10-26' } } }\n    if (p.tipo === 'opcao') {\n      const outras = (await campo.locator('option').evaluateAll(os => os.map(o => (o as HTMLOptionElement).value).filter(v => v !== ''))).filter(v => v !== p.esperado)\n      if (outras.length === 0) continue\n      await campo.selectOption(outras[0]); return { coluna, novo: { tipo: 'opcao', esperado: outras[0] } }\n    }\n  }\n  return null\n}\n\n/** Lê, como texto, os campos preenchidos de uma linha (achada por uma coluna). As datas voltam como AAAA-MM-DD HH:MM:SS nos dois bancos. */\nasync function lerLinha(view: ManifestView, colunaBusca: string, valor: string, preenchidos: Record<string, Preenchido>): Promise<Record<string, string | null>> {\n  return comBanco(async d => {\n    const sel = Object.entries(preenchidos).map(([c, p]) => `${d.txt(d.ident(c), p.tipo)} as ${d.ident(c)}`)\n    const rows = await d.query(`select ${d.txt(d.ident(view.primaryKey))} as ${d.ident('__id')}${sel.length ? ', ' + sel.join(', ') : ''} from ${d.ident(view.table)} where ${d.txt(d.ident(colunaBusca))} = $1`, [valor])\n    return Object.fromEntries(Object.entries(rows[0] ?? {}).map(([k, v]) => [k.toLowerCase(), v == null ? null : String(v)]))\n  })\n}\n\n/**\n * Acha, na lista, a linha do registro pelo id dele (o link de Visualizar/Editar da linha leva o id), passando pelas páginas: a linha criada pode não estar\n * na primeira, e a coluna que identifica o registro pode nem aparecer no grid.\n */\nasync function acharLinha(page: Page, id: string): Promise<Locator | null> {\n  for (let pagina = 1; pagina <= 20; pagina++) {\n    const linha = page.locator('tbody tr').filter({ has: page.locator(`a[href*=\"${id}\"]`) }).first()\n    if (await linha.count()) return linha\n    const proxima = page.getByRole('link', { name: String(pagina + 1), exact: true })\n    if (!(await proxima.count())) return null\n    await clicarENavegar(page, proxima)\n  }\n  return null\n}\n\n/** Confirma a exclusão: caixa de diálogo do navegador ou janela de confirmação do app. */\nasync function confirmarExclusao(page: Page) {\n  page.once('dialog', d => d.accept())\n  await page.getByRole('button', { name: /excluir|confirmar/i }).last().click({ timeout: 4000 }).catch(() => {})\n}\n\nfor (const view of manifest.views.filter(v => escolhidos.length === 0 || escolhidos.includes(v.slug))) {\n  test.describe(describeName(view), () => {\n    test.beforeEach(async ({ page }) => { await entrar(page) })\n\n    for (const t of planView(view, { types: TIPOS, auth: manifest.auth })) {\n      if (t.kind === 'abre') {\n        test(t.title, async ({ page }) => {\n          const erros: string[] = []\n          page.on('pageerror', e => erros.push(e.message.slice(0, 200)))\n          const resp = await page.goto(view.path)\n          expect(resp?.status() ?? 0, `HTTP de ${view.path}`).toBeLessThan(400)\n          await page.waitForLoadState('networkidle').catch(() => {})\n          await expect(page.locator('main').first()).toBeVisible()\n          const texto = await page.locator('body').innerText()\n          expect(texto).not.toMatch(/Application error|Internal Server Error|Unhandled Runtime Error|Erro ao carregar/i)\n          expect(texto.toLowerCase(), `o título \"${view.title}\" aparece na tela`).toContain(view.title.toLowerCase())\n          expect(erros, 'erros de JavaScript na página').toEqual([])\n        })\n      }\n\n      if (t.kind === 'lista') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          for (const f of view.filter) {\n            await expect.soft(page.locator(`[name=\"${nomeDoFiltro(f.column)}\"]`).first(), `filtro \"${f.label}\" (${f.column}_filter)`).toBeVisible()\n          }\n          for (const f of view.grid) {\n            await expect.soft(page.locator('thead th').filter({ hasText: new RegExp(escapar(f.label), 'i') }).first(), `coluna \"${f.label}\" no grid`).toBeVisible()\n          }\n        })\n      }\n\n      if (t.kind === 'formulario') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, `${view.path}/new`)\n          for (const f of camposEditaveis(view)) {\n            const campo = page.locator(`[name=\"${nomeDoCampo(f.column)}\"]`).first()\n            await expect.soft(campo, `campo \"${f.label}\" (${f.column})`).toBeVisible()\n            if (!(await campo.count())) continue\n            if (f.dataType !== 'boolean') {\n              const obrigatorio = (await campo.getAttribute('required')) !== null\n              expect.soft(obrigatorio, `\"${f.label}\": obrigatório esperado ${f.required}`).toBe(f.required)\n            }\n            if (f.readOnly) {\n              const travado = (await campo.getAttribute('readonly')) !== null || (await campo.isDisabled())\n              expect.soft(travado, `\"${f.label}\": deveria ser somente leitura`).toBe(true)\n            }\n          }\n        })\n      }\n\n      if (t.kind === 'mascara') {\n        const f = view.form.find(x => x.column === t.field)!\n        test(t.title, async ({ page }) => {\n          await abrir(page, `${view.path}/new`)\n          const digitos = '1234567890123456789'.slice(0, (f.mask as string).split('0').length - 1)\n          const campo = page.locator(`[name=\"${nomeDoCampo(f.column)}\"]`).first()\n          await campo.click()\n          await campo.pressSequentially(digitos)\n          await expect(campo).toHaveValue(aplicarMascara(digitos, f.mask as string))\n        })\n      }\n\n      if (t.kind === 'obrigatorios') {\n        test(t.title, async ({ page }) => {\n          const ids = async () => new Set((await consultar(`select ${view.primaryKey}::text as id from ${view.table}`)).map(r => String(r.id)))\n          const antes = await ids()\n          await abrir(page, `${view.path}/new`)\n          await page.getByRole('button', { name: 'Criar Registro' }).first().click()\n          await page.waitForTimeout(1500)\n          const novos = [...(await ids())].filter(id => !antes.has(id))\n          if (novos.length > 0) {\n            // o app aceitou salvar vazio: apaga só o que esta tela criou e falha\n            for (const id of novos) await consultar(`delete from ${view.table} where ${view.primaryKey}::text = $1`, [id])\n          }\n          expect(novos, `o app criou ${novos.length} registro(s) com os campos obrigatórios vazios`).toEqual([])\n        })\n      }\n\n      if (t.kind === 'grid_total') {\n        test(t.title, async ({ page }) => {\n          const noBanco = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const naTela = await totalMostrado(page)\n          expect(naTela, 'a lista mostra \"TOTAL: n\"').not.toBeNull()\n          expect(naTela, `total da tela × linhas da tabela ${view.table}`).toBe(noBanco)\n        })\n      }\n\n      if (t.kind === 'grid_ordenacao') {\n        const campo = view.grid.find(x => x.column === t.field)!\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const idx = await indiceColuna(page, campo.label)\n          expect(idx, `coluna \"${campo.label}\" no grid`).toBeGreaterThanOrEqual(0)\n          const clicar = () => clicarENavegar(page, page.locator('thead th').nth(idx).locator('a, button').first())\n          await clicar()\n          const asc = (await linhasDoGrid(page)).map(c => c[idx])\n          await clicar()\n          const desc = (await linhasDoGrid(page)).map(c => c[idx])\n          const total = await totalMostrado(page)\n          if (total) expect(asc.length, 'linhas na ordem crescente (a lista não pode vir vazia se o total é maior que zero)').toBeGreaterThan(0)\n          test.skip(asc.length < 2 || new Set(asc).size < 2, 'poucos valores diferentes para conferir a ordem')\n          if (total !== null && total > asc.length) expect(desc[0], 'com várias páginas, o primeiro da ordem decrescente muda').not.toBe(asc[0])\n          else expect(desc, 'a ordem decrescente é o inverso da crescente').toEqual([...asc].reverse())\n        })\n      }\n\n      if (t.kind === 'grid_filtro') {\n        const campo = view.filter.find(x => x.column === t.field)!\n        test(t.title, async ({ page }) => {\n          const linha = (await consultar(`select ${campo.column}::text as v from ${view.table} where ${campo.column} is not null limit 30`)).find(r => String(r.v ?? '').trim() !== '')\n          test.skip(!linha, 'a tabela não tem dados para filtrar')\n          const valor = String(linha.v)\n          const busca = (valor.split(/\\s+/).find(w => w.length >= 3) ?? valor).slice(0, 20)\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const entrada = page.locator(`[name=\"${nomeDoFiltro(campo.column)}\"]`).first()\n          await entrada.fill(busca)\n          await clicarENavegar(page, page.getByRole('button', { name: 'Pesquisar' }).first())\n          const linhas = await linhasDoGrid(page)\n          expect(linhas.length, `linhas depois de filtrar por \"${busca}\"`).toBeGreaterThan(0)\n          for (const c of linhas) expect.soft(c.join(' ').toLowerCase(), 'linha fora do filtro').toContain(busca.toLowerCase())\n          await clicarENavegar(page, page.getByRole('link', { name: 'Limpar' }).or(page.getByRole('button', { name: 'Limpar' })).first())\n          await expect(page.locator(`[name=\"${nomeDoFiltro(campo.column)}\"]`).first()).toHaveValue('')\n        })\n      }\n\n      if (t.kind === 'exportacao') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const total = await totalMostrado(page)\n          if (t.format === 'csv') {\n            const r = await baixar(page, /csv/i)\n            expect(r.name).toMatch(/\\.csv$/i)\n            const csv = lerCsv(r.buf.toString('utf8'))\n            for (const f of view.grid) expect.soft(csv.cabecalho, `coluna \"${f.label}\" no cabeçalho do CSV`).toContain(f.label)\n            if (total !== null) expect(csv.registros, 'linhas do CSV × total da lista').toBe(total)\n          } else if (t.format === 'json') {\n            const r = await baixar(page, /json/i)\n            expect(r.name).toMatch(/\\.json$/i)\n            const itens = JSON.parse(r.buf.toString('utf8'))\n            expect(Array.isArray(itens), 'o JSON é uma lista').toBe(true)\n            if (total !== null) expect(itens.length, 'itens do JSON × total da lista').toBe(total)\n          } else {\n            const r = await baixar(page, /excel|xlsx/i)\n            expect(r.name).toMatch(/\\.xlsx$/i)\n            expect(r.buf.subarray(0, 2).toString('latin1'), 'um .xlsx é um zip (começa com PK)').toBe('PK')\n            expect(r.buf.length).toBeGreaterThan(1000)\n          }\n        })\n      }\n\n      // ---------------------------------------------------------------------------------------------------------------------\n      // Fase 3 (só leitura)\n      // ---------------------------------------------------------------------------------------------------------------------\n\n      if (t.kind === 'grid_paginacao') {\n        test(t.title, async ({ page }) => {\n          const noBanco = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const seletor = page.locator('main select').last()\n          const rotulos = await seletor.locator('option').allInnerTexts()\n          const tamanhos = rotulos.map(r => ({ r, n: Number(/\\d+/.exec(r)?.[0]) })).filter(x => x.n > 0).sort((a, b) => a.n - b.n)\n          expect(tamanhos.length, 'o seletor de linhas por página tem opções').toBeGreaterThan(0)\n          const menor = tamanhos[0]\n          const antes = page.url()\n          await seletor.selectOption({ label: menor.r })\n          await page.waitForURL(u => u.href !== antes, { timeout: 8_000 }).catch(() => {})\n          await aguardarLista(page)\n          expect(await totalMostrado(page), 'o total não muda com o tamanho da página').toBe(noBanco)\n          expect((await linhasDoGrid(page)).length, `linhas com ${menor.n} por página`).toBe(Math.min(menor.n, noBanco))\n          if (noBanco > menor.n) {\n            await clicarENavegar(page, page.getByRole('link', { name: '2', exact: true }))\n            expect((await linhasDoGrid(page)).length, 'linhas da página 2').toBe(Math.min(menor.n, noBanco - menor.n))\n          }\n        })\n      }\n\n      if (t.kind === 'filtro_opcoes') {\n        const campo = view.filter.find(x => x.column === t.field)!\n        const gcol = view.grid.find(x => x.column === t.field)!\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          let escolha: { label: string; n: number } | undefined\n          for (const o of campo.options ?? []) {\n            const n = Number((await consultar(`select count(*) n from ${view.table} where ${campo.column}::text = $1`, [o.value]))[0].n)\n            if (n > 0 && n < total) { escolha = { label: o.label, n }; break }\n          }\n          test.skip(!escolha, 'nenhuma opção do filtro separa as linhas (todas ou nenhuma)')\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          await page.locator(`select[name=\"${nomeDoFiltro(campo.column)}\"]`).selectOption({ label: escolha!.label })\n          await clicarENavegar(page, page.getByRole('button', { name: 'Pesquisar' }).first())\n          expect(await totalMostrado(page), `total com \"${escolha!.label}\"`).toBe(escolha!.n)\n          const idx = await indiceColuna(page, gcol.label)\n          expect(idx, `coluna \"${gcol.label}\"`).toBeGreaterThanOrEqual(0)\n          for (const c of await linhasDoGrid(page)) expect.soft(norm(c[idx]), 'linha de outra opção').toContain(norm(escolha!.label))\n          await clicarENavegar(page, page.getByRole('link', { name: 'Limpar' }).or(page.getByRole('button', { name: 'Limpar' })).first())\n          expect(await totalMostrado(page), 'Limpar volta ao total').toBe(total)\n        })\n      }\n\n      if (t.kind === 'visualizar') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const icone = page.locator('main a[title=\"Visualizar\"]').first()\n          test.skip(!(await icone.count()), 'sem registros para visualizar')\n          await icone.click()\n          await page.waitForURL(/mode=view/, { timeout: 8_000 })\n          await page.waitForLoadState('networkidle').catch(() => {})\n          const editavel = camposEditaveis(view).find(f => f.dataType !== 'boolean')\n          if (editavel) {\n            const campo = page.locator(`[name=\"${nomeDoCampo(editavel.column)}\"]`).first()\n            await expect(campo).toBeVisible()\n            const travado = (await campo.isDisabled()) || (await campo.getAttribute('readonly')) !== null\n            expect(travado, `\"${editavel.label}\" deveria estar travado no modo Visualizar`).toBe(true)\n          }\n          await expect(page.getByRole('button', { name: /Salvar Alterações|Criar Registro/ })).toHaveCount(0)\n        })\n      }\n\n      if (t.kind === 'exportacao_filtrada') {\n        const campo = view.filter.find(x => x.column === (campoDeFiltro(view) as ManifestField).column)!\n        test(t.title, async ({ page }) => {\n          const linha = (await consultar(`select ${campo.column}::text as v from ${view.table} where ${campo.column} is not null limit 30`)).find(r => String(r.v ?? '').trim() !== '')\n          test.skip(!linha, 'a tabela não tem dados para filtrar')\n          const busca = (String(linha.v).split(/\\s+/).find(w => w.length >= 3) ?? String(linha.v)).slice(0, 20)\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const todos = await totalMostrado(page)\n          await page.locator(`[name=\"${nomeDoFiltro(campo.column)}\"]`).first().fill(busca)\n          await clicarENavegar(page, page.getByRole('button', { name: 'Pesquisar' }).first())\n          const filtrados = await totalMostrado(page)\n          expect(filtrados, 'o filtro achou registros').toBeGreaterThan(0)\n          const r = await baixar(page, /csv/i)\n          const csv = lerCsv(r.buf.toString('utf8'))\n          expect(csv.registros, `linhas do CSV × total filtrado (o banco inteiro tem ${todos})`).toBe(filtrados)\n        })\n      }\n\n      if (t.kind === 'exportacao_marcadas') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const marcas = page.locator('tbody input[type=\"checkbox\"]')\n          test.skip((await marcas.count()) < 2, 'menos de 2 linhas para marcar')\n          await marcas.nth(0).check()\n          await marcas.nth(1).check()\n          await expect(page.getByRole('button', { name: /^Exportar.*\\(2\\)/ })).toBeVisible()\n          const r = await baixar(page, /json/i)\n          expect((JSON.parse(r.buf.toString('utf8')) as unknown[]).length, 'itens exportados × linhas marcadas').toBe(2)\n          await page.locator('thead input[type=\"checkbox\"]').check()\n          const total = await marcas.count()\n          await expect(page.getByRole('button', { name: new RegExp(`^Exportar.*\\\\(${total}\\\\)`) })).toBeVisible()\n          await page.locator('thead input[type=\"checkbox\"]').uncheck()\n          await expect(page.getByRole('button', { name: /^Exportar/ }).first()).not.toContainText('(')\n        })\n      }\n\n      if (t.kind === 'central_downloads') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const r = await baixar(page, /csv/i)\n          const base = r.name.replace(/-\\d{4}-\\d{2}-\\d{2}\\.csv$/i, '')\n          await abrir(page, '/downloads')\n          const arquivos = page.getByText(new RegExp(`^${escapar(base)}-\\\\d{8}-\\\\d{6}-[0-9a-f]{4}\\\\.csv$`))\n          await expect(arquivos.first(), `a Central de Downloads lista a exportação de ${base}`).toBeVisible()\n          const [dl] = await Promise.all([page.waitForEvent('download'), page.locator('a[title=\"Baixar\"]').first().click()])\n          const conteudo = fs.readFileSync((await dl.path())!).toString('utf8')\n          expect(lerCsv(conteudo).cabecalho.length, 'o arquivo baixado tem cabeçalho').toBeGreaterThan(0)\n        })\n      }\n\n      if (t.kind === 'acoes_linha') {\n        test(t.title, async ({ page }) => {\n          const acoes = [...new Set(view.buttons.filter(b => b.actionType === 'custom' && b.placement === 'row').map(b => b.label))]\n          for (const rotulo of acoes) {\n            await abrir(page, view.path)\n            await aguardarLista(page)\n            // o primeiro registro da lista: o id vem do endereço do link da linha\n            const hrefs = await page.locator('tbody tr').first().locator('a[href]').evaluateAll(as => as.map(a => a.getAttribute('href') ?? ''))\n            const id = hrefs.map(h => h.split('?')[0].split('/').pop() ?? '').find(x => x && x !== 'new')\n            test.skip(!id, 'a lista está vazia: não há linha para usar a ação')\n            await page.locator('tbody tr').first().locator(`button[title=\"${rotulo}\"]`).click()\n            await expect(page.locator(`iframe[src*=\"${id}\"]`).first(), `a ação \"${rotulo}\" abre a outra tela em janela, filtrada pelo registro`).toBeVisible({ timeout: 15_000 })\n            await expect.soft(page.getByText(/Application error|Erro ao carregar/i)).toHaveCount(0)\n          }\n        })\n      }\n\n      if (t.kind === 'botoes') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const linhas = (await linhasDoGrid(page)).length\n          for (const b of view.buttons) {\n            const nome = new RegExp(`^${escapar(b.label)}`, 'i')\n            if (b.actionType === 'export') await expect.soft(page.getByRole('button', { name: nome }).first(), `botão \"${b.label}\"`).toBeVisible()\n            else if (b.actionType === 'search') await expect.soft(page.getByRole('button', { name: nome }).first(), `botão \"${b.label}\"`).toBeVisible()\n            else if (b.actionType === 'clear') await expect.soft(page.getByRole('link', { name: nome }).or(page.getByRole('button', { name: nome })).first(), `botão \"${b.label}\"`).toBeVisible()\n            else if (linhas > 0 && ['view', 'edit', 'delete'].includes(b.actionType)) {\n              expect.soft(await page.locator(`main [title=\"${b.label}\"]`).count(), `ícone \"${b.label}\" nas linhas`).toBeGreaterThan(0)\n            }\n          }\n        })\n      }\n\n      if (t.kind === 'campos_tipos') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, `${view.path}/new`)\n          for (const f of camposDeTipo(view)) {\n            const campo = page.locator(`[name=\"${nomeDoCampo(f.column)}\"]`).first()\n            if (!(await campo.count())) { expect.soft(0, `campo \"${f.label}\" (${f.column}) existe`).toBeGreaterThan(0); continue }\n            const tag = await campo.evaluate(e => e.tagName.toLowerCase())\n            const tipo = (await campo.getAttribute('type')) ?? ''\n            if (f.options?.length) {\n              expect.soft(tag, `\"${f.label}\" com opções é uma lista de seleção`).toBe('select')\n              if (tag === 'select') expect.soft(await campo.locator('option').count(), `opções de \"${f.label}\"`).toBeGreaterThanOrEqual(f.options.length)\n            } else if (f.dataType === 'boolean') {\n              expect.soft(tipo, `\"${f.label}\" é uma caixa de marcar`).toBe('checkbox')\n            } else if (ehData(f)) {\n              expect.soft(['date', 'datetime-local', 'time'], `\"${f.label}\" usa o seletor de data`).toContain(tipo)\n            } else if (/select/i.test(f.componentType || '')) {\n              expect.soft(tag, `\"${f.label}\" é uma lista de seleção`).toBe('select')\n            } else if (/int|numeric|decimal|float|double|number/i.test(f.dataType)) {\n              expect.soft(['number', 'text'], `\"${f.label}\" é um campo numérico`).toContain(tipo)\n            } else {\n              expect.soft(['input', 'textarea', 'select'], `\"${f.label}\" é um campo de entrada`).toContain(tag)\n            }\n          }\n        })\n      }\n\n      if (t.kind === 'abas') {\n        test(t.title, async ({ page }) => {\n          const [reg] = await consultar(`select ${view.primaryKey}::text as id from ${view.table} limit 1`)\n          test.skip(!reg, 'a tabela não tem registros para abrir')\n          await abrir(page, `${view.path}/${reg.id}`)\n          for (const d of view.details) {\n            const nome = new RegExp(`^${escapar(d.label)}$`, 'i')\n            if (d.displayMode === 'tab') {\n              const aba = page.getByRole('button', { name: nome }).first()\n              await expect.soft(aba, `aba \"${d.label}\"`).toBeVisible()\n              if (await aba.count()) {\n                await aba.click()\n                await expect.soft(page.getByText(/Application error|Erro ao carregar/i), `erro ao abrir a aba \"${d.label}\"`).toHaveCount(0)\n              }\n            } else {\n              await expect.soft(page.getByText(nome).first(), `seção \"${d.label}\"`).toBeVisible()\n            }\n          }\n        })\n      }\n\n      // --- gabaritos por tipo de tela (todos só leem) ---\n\n      if (t.kind === 'filtros_tela') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          let achados = 0\n          for (const f of view.filter) if (await page.locator(`[name=\"${nomeDoFiltro(f.column)}\"]`).count()) achados++\n          if (achados > 0) expect(achados, 'filtros com nome na tela × filtros configurados').toBe(view.filter.length)\n          else {\n            // tela sem nomes nos campos (ex.: timeline): confere pela quantidade de listas de seleção\n            const listas = view.filter.filter(f => f.options?.length || /select|autocomplete/i.test(f.componentType || '') || /uuid/i.test(f.dataType)).length\n            expect(await page.locator('main select').count(), 'listas de filtro na tela').toBeGreaterThanOrEqual(Math.min(listas, 1))\n          }\n        })\n      }\n\n      if (t.kind === 'tipo_galeria') {\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.locator('main img'), 'um cartão (imagem) por registro').toHaveCount(total)\n        })\n      }\n\n      if (t.kind === 'tipo_kanban') {\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          const cartoes = await page.locator('main button[title=\"Detalhes\"]').count()\n          const mais = Number(/CARREGAR MAIS\\s+(\\d+)/i.exec(await page.locator('main').innerText())?.[1] ?? 0)\n          expect(cartoes + mais, `cartões na tela (${cartoes}) + a carregar (${mais}) × registros da tabela`).toBe(total)\n        })\n      }\n\n      if (t.kind === 'tipo_fluxo') {\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.locator('.react-flow')).toBeVisible()\n          await expect(page.getByText(new RegExp(`${total} ETAPAS`, 'i')).first(), `\"${total} ETAPAS\" na tela`).toBeVisible()\n        })\n      }\n\n      if (t.kind === 'tipo_timeline') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.locator('button[title=\"Atualizar Dados\"], button:has-text(\"Atualizar Dados\")').first()).toBeVisible()\n          await page.locator('button[title=\"Atualizar Dados\"], button:has-text(\"Atualizar Dados\")').first().click()\n          await page.waitForLoadState('networkidle').catch(() => {})\n          await expect(page.getByText(/Application error|Erro ao carregar/i)).toHaveCount(0)\n        })\n      }\n\n      if (t.kind === 'tipo_gantt') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.getByRole('button', { name: /^Hoje$/i })).toBeVisible()\n          for (const tam of ['Pequeno', 'Normal', 'Grande']) await expect.soft(page.locator(`main button[title=\"${tam}\"]`).first(), `tamanho \"${tam}\"`).toBeVisible()\n          const linhas = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          if (linhas > 0) expect(await page.locator('main [title=\"Editar\"]').count(), 'ações de linha (Editar)').toBeGreaterThan(0)\n          // ação de linha \"Visualizar\": abre o registro (em janela ou em outra página) sem gravar nada\n          if (linhas > 0 && (await page.locator('main [title=\"Visualizar\"]').count()) > 0) {\n            const antes = page.url()\n            await page.locator('main [title=\"Visualizar\"]').first().click()\n            await expect.poll(async () => page.url() !== antes || (await page.locator('.fixed.inset-0, [role=\"dialog\"]').count()) > 0, { message: 'Visualizar abre o registro (janela ou página)', timeout: 10_000 }).toBe(true)\n            await expect(page.getByText(/Application error|Erro ao carregar/i)).toHaveCount(0)\n          }\n        })\n      }\n\n      if (t.kind === 'tipo_agenda') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.getByText(/de 20\\d\\d/i).first()).toBeVisible()\n          const texto = async () => (await page.locator('main').innerText()).replace(/\\s+/g, ' ')\n          const mes = await texto()\n          await page.getByRole('button', { name: 'Semana', exact: true }).click()\n          const semana = await texto()\n          await page.getByRole('button', { name: 'Dia', exact: true }).click()\n          const dia = await texto()\n          expect(new Set([mes, semana, dia]).size, 'mês, semana e dia mostram coisas diferentes').toBe(3)\n          await page.getByRole('button', { name: 'Mês', exact: true }).click()\n          await expect(page.getByText('DOM').first()).toBeVisible()\n        })\n      }\n\n      if (t.kind === 'tipo_mapa_mental') {\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.getByText(new RegExp(`${total} REGISTROS`, 'i')).first(), `\"${total} REGISTROS\" na tela`).toBeVisible()\n        })\n      }\n\n      if (t.kind === 'tipo_mapa') {\n        test(t.title, async ({ page }) => {\n          const total = Number((await consultar(`select count(*) n from ${view.table}`))[0].n)\n          const lat = view.form.find(f => /^lat/i.test(f.column))?.column\n          const lng = view.form.find(f => /^(lng|lon)/i.test(f.column))?.column\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.locator('.leaflet-container')).toBeVisible()\n          await expect(page.getByText(new RegExp(`REGISTROS \\\\(${total}\\\\)`, 'i')).first(), `\"REGISTROS (${total})\"`).toBeVisible()\n          if (lat && lng) {\n            const comGps = Number((await consultar(`select count(*) n from ${view.table} where ${lat} is not null and ${lng} is not null`))[0].n)\n            await expect(page.getByText(new RegExp(`${comGps} DE ${total} REGISTROS COM COORDENADAS`, 'i')).first()).toBeVisible()\n          }\n        })\n      }\n\n      if (t.kind === 'tipo_bi') {\n        test(t.title, async ({ page }) => {\n          await abrir(page, view.path)\n          await aguardarTela(page)\n          await expect(page.getByRole('button', { name: 'Organizar Dashboard' })).toBeVisible()\n          // o BI exportado em Java não tem atualização manual nem automática (o botão \"Atualizar agora\" fica desligado no modelo Java): só o app Node a tem\n          if (detectarApp(CONFIG.appDir).pilha === 'java') {\n            await expect(page.getByText(/Application error|Erro ao carregar/i)).toHaveCount(0)\n            return\n          }\n          await expect(page.getByRole('button', { name: 'Atualizar agora' })).toBeVisible()\n          await page.getByRole('button', { name: 'Atualizar agora' }).click()\n          await page.waitForLoadState('networkidle').catch(() => {})\n          await expect(page.getByText(/Application error|Erro ao carregar/i)).toHaveCount(0)\n          expect(await page.locator('tbody tr').count(), 'linhas na tabela de dados').toBeGreaterThan(0)\n        })\n      }\n\n      // --- integração: grava no banco de teste (só roda com o tipo \"integracao\") ---\n\n      if (t.kind === 'crud_cadastro') {\n        test(t.title, async ({ page }) => {\n          const marcadorCampo = campoMarcador(view) // sem ele (telas só com listas, datas e números), o registro é achado pelo id novo\n          const editaveis = camposDeTipo(view).filter(f => !f.readOnly)\n          const limites = await limitesDaTabela(view.table)\n          const marcador = marcadorCampo ? caber(`${RODADA}-${view.slug.replace(/[^a-z0-9]/gi, '').slice(0, 6)}`, limites[marcadorCampo.column.toLowerCase()]) : ''\n          test.skip(!!marcadorCampo && (!marcador.startsWith(PREFIXO_E2E) || marcador.length < 8), 'a coluna de identificação é curta demais para o prefixo E2E-')\n          const idsAntes = marcadorCampo ? null : await idsDaTabela(view)\n          test.skip(!marcadorCampo && idsAntes === null, 'a tabela é grande demais para identificar o registro criado pelo id')\n          const estado: EstadoCrud = { marcador, preenchidos: {} }\n          gravarEstado(view.slug, estado)\n\n          await abrir(page, `${view.path}/new`)\n          const naoPreenchidos: string[] = []\n          let n = 0\n          for (const f of editaveis) {\n            const p = await preencherCampo(page, f, ++n, limites, marcadorCampo && f.column === marcadorCampo.column ? marcador : undefined)\n            if (p) estado.preenchidos[f.column] = p\n            else if (f.required) naoPreenchidos.push(f.label)\n          }\n          test.skip(naoPreenchidos.length > 0, `campo(s) obrigatório(s) que o motor ainda não sabe preencher: ${naoPreenchidos.join(', ')}`)\n          test.skip(Object.keys(estado.preenchidos).length === 0, 'o motor não soube preencher nenhum campo desta tela')\n          if (process.env.E2E_DEBUG) console.log(`[crud ${view.slug}] preenchido: ${JSON.stringify(estado.preenchidos)}`)\n\n          await page.getByRole('button', { name: 'Criar Registro' }).first().click()\n          let linha: Record<string, string | null>\n          if (marcadorCampo) {\n            await expect.poll(async () => (await consultar(`select count(*)::int n from \"${view.table}\" where \"${marcadorCampo.column}\"::text = $1`, [marcador]))[0].n, { message: 'o registro aparece no banco', timeout: 15_000 }).toBe(1)\n            linha = await lerLinha(view, marcadorCampo.column, marcador, estado.preenchidos)\n          } else {\n            const novos = async () => [...((await idsDaTabela(view)) ?? [])].filter(id => !idsAntes!.has(id))\n            await expect.poll(async () => (await novos()).length, { message: 'um registro novo aparece no banco', timeout: 15_000 }).toBe(1)\n            linha = await lerLinha(view, view.primaryKey, (await novos())[0], estado.preenchidos)\n          }\n          estado.id = String(linha.__id)\n          anotarCriado(view.table, view.primaryKey, estado.id) // se o teste cair antes de excluir, a limpeza apaga pelo id\n          gravarEstado(view.slug, estado)\n          // auditoria: se a tabela tem criado_por, o app precisa tê-lo gravado (quem criou o registro)\n          const temAuditoria = (await comBanco(d => d.colunas(view.table))).some((c: any) => c.column_name === 'criado_por')\n          if (temAuditoria) {\n            const [aud] = await consultar(`select case when \"criado_por\" is not null then 1 else 0 end as ok from \"${view.table}\" where \"${view.primaryKey}\"::text = $1`, [estado.id])\n            expect.soft(Number(aud.ok), 'auditoria: criado_por gravado no registro criado').toBe(1)\n          }\n          for (const f of editaveis) {\n            const esp = estado.preenchidos[f.column]\n            if (!esp) continue\n            const dif = conferirNoBanco(f, esp, linha[f.column.toLowerCase()])\n            expect.soft(dif, 'campo gravado no banco').toBeNull()\n          }\n        })\n      }\n\n      if (t.kind === 'crud_reabrir') {\n        test(t.title, async ({ page }) => {\n          const estado = lerEstado(view.slug) as EstadoCrud\n          test.skip(!estado?.id, 'o cadastro anterior não criou o registro')\n          expect(await registroExiste(view, estado.id!), 'o registro criado pelo cadastro continua no banco').toBe(true)\n          await abrir(page, `${view.path}/${estado.id}`)\n          for (const f of camposDeTipo(view)) {\n            const esp = estado.preenchidos[f.column]\n            if (!esp) continue\n            expect.soft(await conferirNaTela(page, f, esp), 'campo mostrado ao reabrir').toBeNull()\n          }\n        })\n      }\n\n      if (t.kind === 'crud_edicao') {\n        test(t.title, async ({ page }) => {\n          const estado = lerEstado(view.slug) as EstadoCrud\n          test.skip(!estado?.id, 'o cadastro anterior não criou o registro')\n          const marcadorCampo = campoMarcador(view)\n          const limites = await limitesDaTabela(view.table)\n          expect(await registroExiste(view, estado.id!), 'o registro criado pelo cadastro continua no banco').toBe(true)\n          await abrir(page, `${view.path}/${estado.id}`)\n          let coluna: string\n          let novo: Preenchido\n          if (marcadorCampo) {\n            // o campo que identifica o registro muda: o sufixo \" ED\" mostra na lista e no banco\n            const v = caber(`${estado.marcador} ED`, limites[marcadorCampo.column.toLowerCase()])\n            test.skip(v === estado.marcador, 'a coluna de identificação não comporta a alteração')\n            await page.locator(`[name=\"${nomeDoCampo(marcadorCampo.column)}\"]`).first().fill(v)\n            coluna = marcadorCampo.column; novo = { tipo: 'texto', esperado: v }\n          } else {\n            const r = await editarUmCampo(page, view, estado, limites)\n            test.skip(!r, 'nenhum campo preenchido pode ser alterado com segurança')\n            coluna = r!.coluna; novo = r!.novo\n          }\n          await page.getByRole('button', { name: 'Salvar Alterações' }).first().click()\n          const campoDef = camposDeTipo(view).find(f => f.column === coluna)!\n          await expect.poll(async () => conferirNoBanco(campoDef, novo, (await lerLinha(view, view.primaryKey, estado.id!, { [coluna]: novo }))[coluna.toLowerCase()]), { message: 'a alteração aparece no banco', timeout: 15_000 }).toBeNull()\n          if (marcadorCampo) estado.marcador = novo.esperado\n          estado.preenchidos[coluna] = novo\n          gravarEstado(view.slug, estado)\n          // só o campo alterado mudou: os demais continuam como foram gravados\n          const linha = await lerLinha(view, view.primaryKey, estado.id!, estado.preenchidos)\n          for (const f of camposDeTipo(view)) {\n            const esp = estado.preenchidos[f.column]\n            if (esp) expect.soft(conferirNoBanco(f, esp, linha[f.column.toLowerCase()]), 'campo depois da edição').toBeNull()\n          }\n        })\n      }\n\n      if (t.kind === 'detalhe_adicionar') {\n        test(t.title, async ({ page }) => {\n          const estado = lerEstado(view.slug) as EstadoCrud\n          test.skip(!estado?.id, 'o cadastro anterior não criou o registro')\n          estado.filhos = estado.filhos ?? []\n          let feitas = 0\n          const motivos: string[] = []\n          for (const d of detalhesPreenchiveis(view)) {\n            const pkFilho = d.primaryKey ?? 'id'\n            const idsDoPai = async () => new Set((await consultar(`select \"${pkFilho}\"::text as id from \"${d.table}\" where \"${d.foreignKey}\"::text = $1`, [estado.id!])).map(r => String(r.id)))\n            const antes = await idsDoPai()\n            await abrir(page, `${view.path}/${estado.id}`)\n            await page.getByRole('button', { name: d.label, exact: true }).first().click()\n            // aba vazia: botão com texto (\"Adicionar Pedidos\"); depois que já há linha, o ícone + (title \"Adicionar\")\n            const porTexto = page.locator('button').filter({ hasText: /^\\s*(Adicionar|Add|Agregar)/i }).locator('visible=true').first()\n            const mais = (await porTexto.count()) ? porTexto : page.locator('button[title=\"Adicionar\"]').locator('visible=true').first()\n            if (!(await mais.count())) {\n              const botoes = await page.locator('button').locator('visible=true').evaluateAll(bs => bs.map(b => ((b.getAttribute('title') || b.textContent || '').trim()).slice(0, 30)).filter(Boolean))\n              motivos.push(`aba \"${d.label}\": sem o botão +; botões visíveis: ${[...new Set(botoes)].join(' / ')}`); continue\n            }\n            await mais.click()\n            // a linha nova é a última com cada campo visível (as linhas que já existem têm os mesmos nomes)\n            const ultimo = (nome: string) => page.locator(`[name=\"${nome}\"]`).locator('visible=true').last()\n            const limites = await limitesDaTabela(d.table)\n            const editaveis = d.fields.filter(f => !f.readOnly && !f.hasFormula && !f.isPrimaryKey && f.column.toLowerCase() !== d.foreignKey.toLowerCase())\n            const preenchidos: Array<[ManifestField, Preenchido]> = []\n            const faltou: string[] = []\n            let n = 0\n            for (const f of editaveis) {\n              const p = await preencherCampo(page, f, ++n, limites, undefined, ultimo)\n              if (p) preenchidos.push([f, p]); else if (f.required) faltou.push(f.label)\n            }\n            if (faltou.length > 0 || preenchidos.length === 0) { motivos.push(`aba \"${d.label}\": ${faltou.length ? 'campo(s) obrigatório(s) que o motor ainda não sabe preencher (' + faltou.join(', ') + ')' : 'nenhum campo preenchível'}`); continue }\n            await page.getByRole('button', { name: 'Salvar Alterações' }).last().click()\n            await expect.poll(async () => (await idsDoPai()).size, { message: `uma linha nova na aba \"${d.label}\" aparece no banco`, timeout: 15_000 }).toBe(antes.size + 1)\n            const novoId = [...(await idsDoPai())].find(id => !antes.has(id))!\n            anotarCriado(d.table, pkFilho, novoId) // se a exclusão do pai não levar o filho, a limpeza o apaga pelo id\n            estado.filhos.push({ tabela: d.table, pk: pkFilho, fk: d.foreignKey, id: novoId })\n            gravarEstado(view.slug, estado)\n            for (const [f, p] of preenchidos) {\n              const noBanco = String((await consultar(`select \"${f.column}\"::text as v from \"${d.table}\" where \"${pkFilho}\"::text = $1`, [novoId]))[0]?.v ?? '')\n              expect.soft(conferirNoBanco(f, p, noBanco), `aba \"${d.label}\": campo gravado`).toBeNull()\n            }\n            const chaveDoPai = String((await consultar(`select \"${d.foreignKey}\"::text as v from \"${d.table}\" where \"${pkFilho}\"::text = $1`, [novoId]))[0]?.v ?? '')\n            expect(chaveDoPai, `aba \"${d.label}\": a linha nova guarda a chave do pai`).toBe(estado.id)\n            feitas++\n          }\n          test.skip(feitas === 0, motivos.join(' | ') || 'nenhuma aba de detalhe pôde receber uma linha')\n        })\n      }\n\n      if (t.kind === 'crud_exclusao') {\n        test(t.title, async ({ page }) => {\n          const estado = lerEstado(view.slug) as EstadoCrud\n          test.skip(!estado?.id, 'o cadastro anterior não criou o registro')\n          const contar = async () => Number((await consultar(`select count(*)::int n from \"${view.table}\"`))[0].n)\n          const antes = await contar()\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const linha = await acharLinha(page, estado.id!)\n          expect(linha, `a linha do registro criado (${estado.marcador || estado.id}) aparece na lista`).not.toBeNull()\n          await linha!.locator('button[title=\"Excluir\"], a[title=\"Excluir\"]').first().click()\n          await confirmarExclusao(page)\n          await expect.poll(async () => registroExiste(view, estado.id!), { message: 'o registro some do banco', timeout: 15_000 }).toBe(false)\n          expect(await contar(), 'só o registro criado pelo teste foi excluído').toBe(antes - 1)\n          // as linhas que as abas ganharam saem junto com o pai (cascata), sem deixar filho sem pai\n          for (const f of estado.filhos ?? []) {\n            expect(Number((await consultar(`select count(*)::int n from \"${f.tabela}\" where \"${f.pk}\"::text = $1`, [f.id]))[0].n), `a linha da aba \"${f.tabela}\" saiu junto com o registro`).toBe(0)\n            riscarCriado(f.tabela, f.id)\n          }\n          riscarCriado(view.table, estado.id!)\n          gravarEstado(view.slug, undefined)\n        })\n      }\n\n      // --- kanban: arrastar um cartão para outra coluna grava a coluna nova (a linha volta ao que era no fim) ---\n\n      if (t.kind === 'kanban_mover') {\n        test(t.title, async ({ page }) => {\n          const grupo = view.kanbanGroupColumn!\n          const pk = view.primaryKey\n          const total = Number((await consultar(`select count(*)::int n from \"${view.table}\"`))[0].n)\n          test.skip(total > 5000, 'a tabela é grande demais para guardar uma cópia e devolver a linha ao que era')\n          // a tabela como estava, em JSON (mantém a precisão exata de datas e números): a linha movida volta inteira, inclusive a auditoria de quem/quando gravou\n          const foto = () => fotografar(view)\n          const originais = await foto()\n          const valores = [...new Set([...originais.values()].map(j => String(val(j, grupo) ?? '')).filter(Boolean))]\n          test.skip(valores.length < 2, 'precisa de pelo menos dois valores diferentes na coluna do quadro para arrastar o cartão')\n          try {\n            await abrir(page, view.path)\n            await aguardarTela(page)\n            const colunas = page.locator('main div.w-80')\n            const titulo = async (c: Locator) => ((await c.locator('h3').first().innerText()).trim())\n            const largura = page.viewportSize()!.width\n            // origem: a primeira coluna com cartão; destino: a coluna vizinha que cabe na tela junto com ela (título igual a um valor da coluna no banco)\n            let origem: Locator | null = null\n            let iOrigem = -1\n            for (let i = 0; i < await colunas.count(); i++) if ((await colunas.nth(i).locator('div.cursor-grab').count()) > 0) { origem = colunas.nth(i); iOrigem = i; break }\n            test.skip(!origem, 'o quadro não mostra nenhum cartão')\n            await origem!.scrollIntoViewIfNeeded()\n            const tituloOrigem = await titulo(origem!)\n            let destino: Locator | null = null\n            for (const i of [iOrigem + 1, iOrigem - 1, iOrigem + 2, iOrigem - 2]) {\n              if (i < 0 || i >= await colunas.count()) continue\n              const c = colunas.nth(i)\n              const caixa = await c.boundingBox()\n              const tt = await titulo(c)\n              if (caixa && caixa.x >= 0 && caixa.x + caixa.width <= largura && valores.some(v => v.toLowerCase() === tt.toLowerCase())) { destino = c; break }\n            }\n            test.skip(!destino, 'nenhuma coluna vizinha cabe na tela com o título de um valor da coluna no banco')\n            const tituloDestino = await titulo(destino!)\n            const esperadoDestino = valores.find(v => v.toLowerCase() === tituloDestino.toLowerCase())!\n            const cartao = origem!.locator('div.cursor-grab').first()\n            await cartao.scrollIntoViewIfNeeded()\n            const de = (await cartao.boundingBox())!\n            const para = (await destino!.boundingBox())!\n            await page.mouse.move(de.x + de.width / 2, de.y + de.height / 2)\n            await page.mouse.down()\n            await page.mouse.move(de.x + de.width / 2 + 12, de.y + de.height / 2 + 12, { steps: 4 }) // passa do limite de 8px que ativa o arraste\n            await page.mouse.move(para.x + para.width / 2, de.y + de.height / 2, { steps: 25 })\n            await page.mouse.up()\n            // exatamente uma linha mudou de coluna, e foi para a coluna onde o cartão foi solto\n            const mudadas = async () => [...(await foto())].filter(([id, j]) => String(val(j, grupo) ?? '') !== String(val(originais.get(id), grupo) ?? ''))\n            await expect.poll(async () => (await mudadas()).length, { message: 'uma linha mudou de coluna no banco', timeout: 15_000 }).toBe(1)\n            const [idMovida, movida] = (await mudadas())[0]\n            expect(String(val(movida, grupo)), `o cartão foi gravado na coluna onde foi solto (\"${esperadoDestino}\", vinda de \"${tituloOrigem}\")`).toBe(esperadoDestino)\n            expect(String(val(originais.get(idMovida), grupo)).toLowerCase(), 'e saiu da coluna de onde foi arrastado').toBe(tituloOrigem.toLowerCase())\n            // depois de recarregar, o cartão continua na coluna nova\n            await abrir(page, view.path)\n            await aguardarTela(page)\n            const nova = page.locator('main div.w-80').filter({ has: page.locator('h3', { hasText: new RegExp(`^${escapar(tituloDestino)}$`, 'i') }) }).first()\n            expect.soft(await nova.locator('div.cursor-grab').count(), 'cartões na coluna de destino depois de recarregar').toBeGreaterThan(0)\n          } finally {\n            await devolverLinhas(view, originais) // o que o arraste mudou volta ao que era, mesmo se o teste falhou no meio\n          }\n        })\n      }\n\n      // --- fluxo: arrastar só move; ligar grava a etapa anterior; ciclo é recusado ---\n\n      if (t.kind === 'fluxo_conectar') {\n        test(t.title, async ({ page }) => {\n          const pred = view.blueprintPredecessorColumn!\n          const total = Number((await consultar(`select count(*)::int n from \"${view.table}\"`))[0].n)\n          test.skip(total > 500, 'a tabela é grande demais para o quadro mostrar todas as etapas')\n          const originais = await fotografar(view)\n          const anterioresDe = (m: Map<string, Record<string, unknown>>, id: string) => String(val(m.get(id), pred) ?? '').split(',').map(x => x.trim()).filter(Boolean)\n          const descendentes = (id: string): Set<string> => { const out = new Set<string>(); const fila = [id]; while (fila.length) { const x = fila.pop()!; for (const o of originais.keys()) if (!out.has(o) && anterioresDe(originais, o).includes(x)) { out.add(o); fila.push(o) } } return out }\n          try {\n            await abrir(page, view.path)\n            await aguardarTela(page)\n            await expect(page.locator('.react-flow')).toBeVisible()\n            await page.locator('.react-flow').scrollIntoViewIfNeeded()\n            await page.waitForTimeout(1200) // o quadro se ajusta sozinho à tela (fitView animado) logo que abre\n            const no = (id: string) => page.locator(`.react-flow__node[data-id=\"${id}\"]`)\n            const naTela = await page.locator('.react-flow__node').evaluateAll(ns => ns.map(n => n.getAttribute('data-id') ?? ''))\n            // destino: qualquer etapa (ligar troca a anterior dela); origem: outra que não seja descendente dela (senão fecharia um ciclo). Escolhe o par mais próximo na tela, para dar zoom nos dois.\n            const caixas = new Map<string, { x: number; y: number }>()\n            const pane = (await page.locator('.react-flow').boundingBox())!\n            // só as etapas que estão dentro do quadro (as outras ficam fora da parte visível)\n            for (const id of naTela) { const c = await no(id).boundingBox(); if (c && c.x >= pane.x && c.x + c.width <= pane.x + pane.width && c.y >= pane.y && c.y + c.height <= pane.y + Math.min(pane.height, 780 - pane.y + 0)) caixas.set(id, { x: c.x + c.width / 2, y: c.y + c.height / 2 }) }\n            const dist = (a: string, b: string) => Math.hypot(caixas.get(a)!.x - caixas.get(b)!.x, caixas.get(a)!.y - caixas.get(b)!.y)\n            let melhor: { B: string; A: string; d: number } | null = null\n            for (const b of naTela) {\n              if (!caixas.has(b) || !originais.has(b)) continue\n              const desc = descendentes(b)\n              for (const a of naTela) if (a !== b && caixas.has(a) && originais.has(a) && !desc.has(a) && (!melhor || dist(a, b) < melhor.d)) melhor = { B: b, A: a, d: dist(a, b) }\n            }\n            test.skip(!melhor, 'não há duas etapas visíveis que possam ser ligadas sem formar um ciclo')\n            const { A, B } = melhor!\n            // com muitas etapas o quadro mostra tudo miúdo: dá zoom (roda do mouse) no meio do par até as etapas ficarem grandes e continuarem as duas na tela\n            const meio = { x: (caixas.get(A)!.x + caixas.get(B)!.x) / 2, y: (caixas.get(A)!.y + caixas.get(B)!.y) / 2 }\n            await page.mouse.move(meio.x, meio.y)\n            const quadro = (await page.locator('.react-flow').boundingBox())!\n            const cabe = async (id: string) => { const c = await no(id).boundingBox(); return !!c && c.x >= quadro.x && c.y >= quadro.y && c.x + c.width <= quadro.x + quadro.width && c.y + c.height <= quadro.y + quadro.height }\n            // cada passo de zoom só vale se as duas etapas continuam na tela; se uma sair, volta um passo e fica no maior zoom em que as duas cabem\n            for (let i = 0; i < 12 && (((await no(B).boundingBox())?.width ?? 0) < 150); i++) {\n              await page.mouse.wheel(0, -250); await page.waitForTimeout(120)\n              if (!(await cabe(A)) || !(await cabe(B))) { await page.mouse.wheel(0, 250); await page.waitForTimeout(120); break }\n            }\n            test.skip(!(await cabe(A)) || !(await cabe(B)), 'as duas etapas a ligar não cabem juntas na tela depois do zoom')\n            const centro = async (l: Locator) => { const c = (await l.boundingBox())!; return { x: c.x + c.width / 2, y: c.y + c.height / 2 } }\n            const arrastar = async (de: { x: number; y: number }, para: { x: number; y: number }) => {\n              await page.mouse.move(de.x, de.y); await page.mouse.down()\n              await page.mouse.move(de.x + 6, de.y + 6, { steps: 3 }); await page.mouse.move(para.x, para.y, { steps: 20 }); await page.mouse.up()\n            }\n            const mudadas = async () => [...(await fotografar(view))].filter(([id, j]) => JSON.stringify(j) !== JSON.stringify(originais.get(id)))\n            const aresta = (de: string, para: string) => page.locator(`[data-testid^=\"rf__edge-edge-${de}-${para}-\"], .react-flow__edge[data-id^=\"edge-${de}-${para}-\"]`)\n\n            // 1) arrastar a etapa só a move na tela: nada é gravado\n            const posicao = async () => (await no(B).boundingBox())!\n            const antes = await posicao()\n            const corpo = { x: antes.x + antes.width / 2, y: antes.y + 14 } // a faixa de cima da etapa (sem botões)\n            await arrastar(corpo, { x: corpo.x + 90, y: corpo.y + 60 })\n            await expect.poll(async () => { const d = await posicao(); return Math.abs(d.x - antes.x) + Math.abs(d.y - antes.y) }, { message: 'a etapa se moveu na tela', timeout: 5_000 }).toBeGreaterThan(20)\n            await page.waitForTimeout(500)\n            expect((await mudadas()).length, 'mover a etapa na tela não grava nada').toBe(0)\n\n            // 2) ligar A -> B grava o id de A como etapa anterior de B (e só isso)\n            await arrastar(await centro(no(A).locator('.react-flow__handle.source').first()), await centro(no(B).locator('.react-flow__handle.target').first()))\n            await expect.poll(async () => String(val((await fotografar(view)).get(B), pred) ?? ''), { message: 'a etapa anterior de B é A no banco', timeout: 15_000 }).toBe(A)\n            expect((await mudadas()).map(([id]) => id), 'só a etapa de destino mudou').toEqual([B])\n            await expect(aresta(A, B).first(), 'a linha A → B aparece na tela').toBeAttached()\n\n            // 3) ligar B -> A fecharia um ciclo (A já vem antes de B): é recusado e nada muda\n            const aposLigar = JSON.stringify([...(await fotografar(view))])\n            await arrastar(await centro(no(B).locator('.react-flow__handle.source').first()), await centro(no(A).locator('.react-flow__handle.target').first()))\n            await page.waitForTimeout(1500)\n            expect(JSON.stringify([...(await fotografar(view))]), 'a ligação que formaria um ciclo foi recusada: o banco não mudou').toBe(aposLigar)\n            await expect(aresta(B, A), 'e a linha B → A não foi criada').toHaveCount(0)\n          } finally {\n            await devolverLinhas(view, originais) // as etapas voltam ao que eram, mesmo se o teste falhou no meio\n          }\n        })\n      }\n\n      // --- segurança: derivada da configuração de acesso do projeto (só com o tipo \"seguranca\"; cria usuários e grupos temporários e os apaga) ---\n\n      if (t.kind === 'seg_tabela') {\n        test(t.title, async ({ page }) => {\n          const tp = view.tablePerms ?? { create: true, update: true, delete: true }\n          await abrir(page, view.path)\n          await aguardarLista(page)\n          const visiveis = (loc: Locator) => loc.locator('visible=true').count()\n          expect((await visiveis(page.getByRole('link', { name: 'Novo Registro' }))) > 0, `\"Novo Registro\" visível (criar ${tp.create ? 'permitido' : 'proibido'} pelo Studio)`).toBe(tp.create)\n          const linhas = (await linhasDoGrid(page)).length\n          test.skip(linhas === 0, 'a lista está vazia: sem linhas não há ícones de editar e excluir para conferir')\n          expect((await visiveis(page.locator('main [title=\"Editar\"]'))) > 0, `ícone Editar visível (editar ${tp.update ? 'permitido' : 'proibido'} pelo Studio)`).toBe(tp.update)\n          expect((await visiveis(page.locator('main [title=\"Excluir\"]'))) > 0, `ícone Excluir visível (excluir ${tp.delete ? 'permitido' : 'proibido'} pelo Studio)`).toBe(tp.delete)\n        })\n      }\n\n      if (t.kind === 'seg_nivel_nenhum' || t.kind === 'seg_nivel_leitura') {\n        const nivel = t.kind === 'seg_nivel_nenhum' ? 'none' : 'read'\n        test(t.title, async ({ browser }) => {\n          const auth = manifest.auth!\n          const u = await criarUsuarioTemporario(auth, { nivel: { viewSlug: view.slug, nivel } })\n          const marcadorCampo = campoMarcador(view)\n          const marcador = `${RODADA}-forcado`\n          const ctx = await browser.newContext({ baseURL: `http://localhost:${CONFIG.port}`, locale: 'pt-BR', viewport: { width: 1280, height: 800 } })\n          try {\n            const pag = await ctx.newPage()\n            await entrarComo(pag, u.email, u.senha)\n            const menu = (await pag.locator('aside nav a[href^=\"/\"]').evaluateAll(as => as.map(a => (a as HTMLAnchorElement).getAttribute('href')))) as string[]\n            await abrir(pag, view.path)\n            if (nivel === 'none') {\n              expect(menu, 'o menu do grupo sem acesso não lista a tela').not.toContain(view.path)\n              expect(await pag.locator('thead th').count(), 'a tela bloqueada não mostra a lista').toBe(0)\n              expect(await pag.getByText(/TOTAL:\\s*\\d+/i).count(), 'a tela bloqueada não mostra o total').toBe(0)\n              await abrir(pag, `${view.path}/new`)\n              if (marcadorCampo) expect(await pag.locator(`[name=\"${nomeDoCampo(marcadorCampo.column)}\"]`).locator('visible=true').count(), 'o formulário não abre pelo endereço').toBe(0)\n            } else {\n              expect(menu, 'o menu do grupo de leitura lista a tela').toContain(view.path)\n              await aguardarLista(pag)\n              expect(await totalMostrado(pag), 'a lista abre e mostra o total').not.toBeNull()\n              expect(await pag.getByRole('link', { name: 'Novo Registro' }).locator('visible=true').count(), '\"Novo Registro\" escondido na leitura').toBe(0)\n              expect(await pag.locator('main [title=\"Editar\"]').locator('visible=true').count(), 'ícone Editar escondido na leitura').toBe(0)\n              expect(await pag.locator('main [title=\"Excluir\"]').locator('visible=true').count(), 'ícone Excluir escondido na leitura').toBe(0)\n              // o servidor recusa gravar mesmo se a pessoa forçar o endereço do formulário\n              if (marcadorCampo) {\n                await abrir(pag, `${view.path}/new`)\n                const campo = pag.locator(`[name=\"${nomeDoCampo(marcadorCampo.column)}\"]`).first()\n                if ((await campo.count()) && (await campo.isEnabled())) {\n                  await campo.fill(marcador)\n                  const criar = pag.getByRole('button', { name: 'Criar Registro' }).first()\n                  if (await criar.count()) await criar.click()\n                  await pag.waitForTimeout(1500)\n                }\n                const criados = Number((await consultar(`select count(*)::int n from \"${view.table}\" where \"${marcadorCampo.column}\"::text = $1`, [marcador]))[0].n)\n                if (criados > 0) await consultar(`delete from \"${view.table}\" where \"${marcadorCampo.column}\"::text = $1`, [marcador]).catch(() => {})\n                expect(criados, 'o servidor aceitou gravar com acesso só de leitura').toBe(0)\n              }\n            }\n          } finally {\n            await ctx.close()\n            await removerUsuarioTemporario(auth, u)\n          }\n        })\n      }\n\n      if (t.kind === 'seg_linha') {\n        const regra = regraDeLinha(view)!\n        test(t.title, async ({ browser }) => {\n          const auth = manifest.auth!\n          const u = await criarUsuarioTemporario(auth, { grupoSemRestricao: true })\n          const marcadorCampo = campoMarcador(view)\n          const ctx = await browser.newContext({ baseURL: `http://localhost:${CONFIG.port}`, locale: 'pt-BR', viewport: { width: 1280, height: 800 } })\n          try {\n            // linhas que a regra deixa este usuário ver: as que têm, na coluna da regra, o valor dele (sem o dado, a regra nega tudo)\n            const valor = await valorDaRegra(auth, u.id, regra.source, regra.attr)\n            const rel = regra.op === 'related' ? regra.related! : null\n            // 'related': a coluna aponta para uma linha de outra tabela cuja coluna é igual ao valor do usuário\n            const esperado = async () => valor === null ? 0 : Number((await consultar(rel\n              ? `select count(*)::int n from \"${view.table}\" where \"${regra.column}\" in (select \"${rel.key}\" from \"${rel.table}\" where \"${rel.column}\"::text = $1)`\n              : `select count(*)::int n from \"${view.table}\" where \"${regra.column}\"::text = $1`, [valor]))[0].n)\n            const noBanco = Number((await consultar(`select count(*)::int n from \"${view.table}\"`))[0].n)\n            const pag = await ctx.newPage()\n            await entrarComo(pag, u.email, u.senha)\n            await abrir(pag, view.path)\n            await aguardarLista(pag)\n            expect(await pag.locator('thead th').count(), 'a lista abriu para o usuário temporário (um grupo sem restrição de tela)').toBeGreaterThan(0)\n            expect(await totalOuZero(pag), `o usuário temporário (fora da exceção) vê só as linhas da regra; a tabela tem ${noBanco}`).toBe(await esperado())\n            if (noBanco > 0) expect(await totalOuZero(pag), 'a regra esconde as linhas de outras pessoas').toBeLessThan(noBanco)\n\n            // com a regra apontando para quem criou o registro: o que o usuário cria, ele passa a ver\n            if (/^(criado_por|created_by)$/i.test(regra.column) && regra.source === 'user.attr' && marcadorCampo) {\n              const antes = await esperado()\n              const marcador = caber(`${RODADA}-linha`, (await limitesDaTabela(view.table))[marcadorCampo.column])\n              await abrir(pag, `${view.path}/new`)\n              const limites = await limitesDaTabela(view.table)\n              const naoPreenchidos: string[] = []\n              let n = 0\n              for (const f of camposDeTipo(view).filter(x => !x.readOnly)) {\n                const p = await preencherCampo(pag, f, ++n, limites, f.column === marcadorCampo.column ? marcador : undefined)\n                if (!p && f.required) naoPreenchidos.push(f.label)\n              }\n              if (process.env.E2E_DEBUG && naoPreenchidos.length) console.log(`[seg_linha ${view.slug}] não preenchidos: ${naoPreenchidos.join(', ')} · url ${pag.url()}`)\n              test.skip(naoPreenchidos.length > 0, `campo(s) obrigatório(s) que o motor ainda não sabe preencher: ${naoPreenchidos.join(', ')}`)\n              await pag.getByRole('button', { name: 'Criar Registro' }).first().click()\n              await expect.poll(async () => Number((await consultar(`select count(*)::int n from \"${view.table}\" where \"${marcadorCampo.column}\"::text = $1`, [marcador]))[0].n), { timeout: 15_000 }).toBe(1)\n              await abrir(pag, view.path)\n              await aguardarLista(pag)\n              expect(await pag.locator('thead th').count(), 'a lista abriu depois do cadastro').toBeGreaterThan(0)\n              expect(await totalOuZero(pag), 'o registro criado pelo usuário aparece para ele').toBe(antes + 1)\n              expect(await totalOuZero(pag), 'e continua sem ver as linhas de outras pessoas').toBeLessThan(noBanco + 1)\n            }\n          } finally {\n            await ctx.close()\n            // o que o usuário temporário criou sai antes dele (a auditoria aponta para o usuário)\n            if (marcadorCampo) await consultar(`delete from \"${view.table}\" where \"${marcadorCampo.column}\"::text like $1`, [PREFIXO_E2E + '%']).catch(() => {})\n            await removerUsuarioTemporario(auth, u)\n          }\n        })\n      }\n\n      // --- gestão de acesso do app (Usuários, Grupos, Permissões de Telas): só com o tipo \"seguranca\" e a gestão de acesso ligada ---\n\n      if (t.kind.startsWith('acesso_')) {\n        const auth = manifest.auth!\n        const ac = auth.access!\n        const rotulo = (k: string) => new RegExp(`^(${(ac.labels[k] ?? [k]).map(escapar).join('|')})$`, 'i')\n        const porTitulo = (k: string, el = 'button') => (ac.labels[k] ?? [k]).map(v => `${el}[title=\"${v}\"]`).join(', ')\n        const confirmar = /excluir|delete|eliminar|confirmar|confirm|^sim$|^yes$|^sí$/i\n        const janela = (p: Page) => p.getByRole('dialog').last()\n        const novoContexto = (browser: import('@playwright/test').Browser) => browser.newContext({ baseURL: `http://localhost:${CONFIG.port}`, locale: 'pt-BR', viewport: { width: 1280, height: 800 } })\n\n        if (t.kind === 'acesso_abre') {\n          test(t.title, async ({ page }) => {\n            for (const [chave, tela] of [['users_title', ac.screens.users], ['groups_title', ac.screens.groups], ['perms_title', ac.screens.permissions]] as const) {\n              await abrir(page, tela.path)\n              await aguardarTela(page)\n              await expect.soft(page.getByText(rotulo(chave)).first(), `título da tela ${tela.path}`).toBeVisible()\n              await expect.soft(page.getByText(/Application error|Erro ao carregar/i), `erro em ${tela.path}`).toHaveCount(0)\n            }\n          })\n        }\n\n        if (t.kind === 'acesso_usuarios_lista') {\n          test(t.title, async ({ page }) => {\n            const usuarios = await comBanco(d => acesso.usuariosReais(d, auth, 5))\n            test.skip(usuarios.length === 0, 'a tabela de usuários está vazia')\n            await abrir(page, ac.screens.users.path)\n            await aguardarTela(page)\n            for (const u of usuarios) {\n              const linha = page.locator('tbody tr').filter({ hasText: u.email })\n              await expect.soft(linha, `usuário ${u.email} na lista`).toHaveCount(1)\n              const grupo = await comBanco(d => acesso.grupoDoUsuario(d, auth, u.id))\n              if (grupo && (await linha.count()) === 1) await expect.soft(linha.locator('select'), `grupo de ${u.email}`).toHaveValue(grupo)\n            }\n          })\n        }\n\n        if (t.kind === 'acesso_usuario_ciclo') {\n          test(t.title, async ({ page, browser }) => {\n            const grupos = (await comBanco(d => acesso.listarGrupos(d, auth))).filter((g: any) => !/^E2E-/i.test(String(g.nome)))\n            test.skip(grupos.length < 2, 'precisa de pelo menos dois grupos (que não sejam de teste) para trocar o grupo do usuário')\n            const [g1, g2] = grupos\n            const email = `e2e_seg_${unico()}@metabuilder.local`\n            const antesOutros = await comBanco(d => acesso.vinculosDeOutros(d, auth))\n            let uid: string | undefined\n            try {\n              await abrir(page, ac.screens.users.path)\n              await aguardarTela(page)\n              await page.getByRole('button', { name: rotulo('create_user') }).click()\n              const j = janela(page)\n              await j.getByPlaceholder(rotulo('name_optional')).fill('E2E Usuário Temporário')\n              await j.locator('input[type=\"email\"]').fill(email)\n              await j.locator('input[type=\"password\"]').fill('Senha-Inicial-1')\n              await j.locator('select').selectOption({ label: g1.nome })\n              await j.getByRole('button', { name: rotulo('save') }).click()\n              await expect.poll(async () => (await comBanco(d => acesso.usuarioPorEmail(d, auth, email))) ?? '', { message: 'o usuário aparece no banco', timeout: 15_000 }).not.toBe('')\n              uid = (await comBanco(d => acesso.usuarioPorEmail(d, auth, email))) as string\n              const hash = await comBanco(d => acesso.lerHashDoUsuario(d, auth, uid!))\n              expect(String(hash), 'a senha é gravada em hash, nunca em texto').not.toBe('Senha-Inicial-1')\n              expect(acesso.confereSenha(auth.hash, 'Senha-Inicial-1', hash), 'o hash confere com a senha informada').toBe(true)\n              expect(await comBanco(d => acesso.grupoDoUsuario(d, auth, uid!)), 'grupo escolhido ao criar').toBe(g1.id)\n\n              // o usuário novo consegue entrar\n              const ctx = await novoContexto(browser)\n              try { const p2 = await ctx.newPage(); await entrarComo(p2, email, 'Senha-Inicial-1') } finally { await ctx.close() }\n\n              // trocar de grupo pela lista\n              await abrir(page, ac.screens.users.path)\n              await aguardarTela(page)\n              const linha = page.locator('tbody tr').filter({ hasText: email })\n              await linha.locator('select').selectOption({ label: g2.nome })\n              await expect.poll(async () => await comBanco(d => acesso.grupoDoUsuario(d, auth, uid!)), { message: 'o grupo novo aparece no banco', timeout: 15_000 }).toBe(g2.id)\n\n              // redefinir a senha: a nova vale, a antiga não\n              await linha.locator(porTitulo('reset_password')).first().click()\n              const j2 = janela(page)\n              const senhas = j2.locator('input[type=\"password\"]')\n              await senhas.nth(0).fill('Senha-Nova-2')\n              await senhas.nth(1).fill('Senha-Nova-2')\n              await j2.getByRole('button', { name: rotulo('save') }).click()\n              await expect.poll(async () => acesso.confereSenha(auth.hash, 'Senha-Nova-2', await comBanco(d => acesso.lerHashDoUsuario(d, auth, uid!))), { message: 'a senha nova vale', timeout: 15_000 }).toBe(true)\n              const ctx2 = await novoContexto(browser)\n              try {\n                const velho = await ctx2.newPage()\n                await velho.goto('/login')\n                await velho.locator('input[name=\"email\"]').fill(email)\n                await velho.locator('input[name=\"password\"]').fill('Senha-Inicial-1')\n                await velho.locator('button[type=\"submit\"]').click()\n                await velho.waitForTimeout(2000)\n                expect(velho.url(), 'a senha antiga já não entra').toMatch(/\\/login/)\n              } finally { await ctx2.close() }\n\n              // excluir pela janela de confirmação do app\n              await abrir(page, ac.screens.users.path)\n              await aguardarTela(page)\n              await page.locator('tbody tr').filter({ hasText: email }).locator(porTitulo('delete')).first().click()\n              await janela(page).getByRole('button', { name: confirmar }).last().click()\n              await expect.poll(async () => (await comBanco(d => acesso.usuarioPorEmail(d, auth, email))) ?? '', { message: 'o usuário some do banco', timeout: 15_000 }).toBe('')\n              expect(await comBanco(d => acesso.grupoDoUsuario(d, auth, uid!)), 'o vínculo com o grupo também some').toBeNull()\n              // trocar de grupo e excluir um usuário não pode ter mexido no vínculo de ninguém mais\n              expect(await comBanco(d => acesso.vinculosDeOutros(d, auth)), 'vínculos dos outros usuários').toBe(antesOutros)\n            } finally {\n              if (uid) await comBanco(d => acesso.apagarUsuario(d, auth, uid!)).catch(() => {})\n            }\n          })\n        }\n\n        if (t.kind === 'acesso_email_repetido') {\n          test(t.title, async ({ page }) => {\n            const existente = CONFIG.user || (await comBanco(d => acesso.usuariosReais(d, auth, 1)))[0]?.email\n            test.skip(!existente, 'não há e-mail existente para repetir')\n            const contar = async () => Number((await consultar(`select count(*)::int n from ${auth.usersTable}`))[0].n)\n            await abrir(page, ac.screens.users.path)\n            await aguardarTela(page)\n            const antes = await contar()\n            await page.getByRole('button', { name: rotulo('create_user') }).click()\n            const j = janela(page)\n            await j.getByPlaceholder(rotulo('name_optional')).fill('E2E Repetido') // com nome, para o erro vir do e-mail repetido e não do nome vazio\n            await j.locator('input[type=\"email\"]').fill(existente)\n            await j.locator('input[type=\"password\"]').fill('Qualquer-Senha-1')\n            await j.getByRole('button', { name: rotulo('save') }).click()\n            await page.waitForTimeout(1500)\n            const depois = await contar()\n            if (depois > antes && auth.nameColumn) await consultar(`delete from ${auth.usersTable} where ${auth.nameColumn} = $1`, ['E2E Repetido']).catch(() => {})\n            expect(depois, 'nenhum usuário foi criado com o e-mail repetido').toBe(antes)\n            await expect(janela(page).getByRole('button', { name: rotulo('save') }), 'a janela continua aberta, com o erro dentro').toBeVisible()\n          })\n        }\n\n        if (t.kind === 'acesso_grupo_ciclo') {\n          test(t.title, async ({ page }) => {\n            const nome = `E2E-Perm-${unico()} UI`\n            const existe = async (n: string) => (await comBanco(d => acesso.listarGrupos(d, auth))).some((g: any) => g.nome === n)\n            try {\n              await abrir(page, ac.screens.groups.path)\n              await aguardarTela(page)\n              await page.getByRole('button', { name: rotulo('create_group') }).click()\n              await janela(page).getByRole('textbox').fill(nome)\n              await janela(page).getByRole('button', { name: rotulo('save') }).click()\n              await expect.poll(() => existe(nome), { message: 'o grupo aparece no banco', timeout: 15_000 }).toBe(true)\n\n              await abrir(page, ac.screens.groups.path)\n              await aguardarTela(page)\n              const linha = page.locator('tbody tr').filter({ hasText: nome })\n              await expect(linha, 'o grupo na lista').toHaveCount(1)\n              await linha.locator(porTitulo('rename')).first().click()\n              const novoNome = nome + ' B'\n              await janela(page).getByRole('textbox').fill(novoNome)\n              await janela(page).getByRole('button', { name: rotulo('save') }).click()\n              await expect.poll(() => existe(novoNome), { message: 'o novo nome aparece no banco', timeout: 15_000 }).toBe(true)\n\n              await abrir(page, ac.screens.groups.path)\n              await aguardarTela(page)\n              await page.locator('tbody tr').filter({ hasText: novoNome }).locator(porTitulo('delete')).first().click()\n              await janela(page).getByRole('button', { name: confirmar }).last().click()\n              await expect.poll(() => existe(novoNome), { message: 'o grupo some do banco', timeout: 15_000 }).toBe(false)\n            } finally {\n              await comBanco(async d => { for (const g of (await acesso.listarGrupos(d, auth)).filter((x: any) => String(x.nome).startsWith(nome))) await acesso.apagarGrupo(d, auth, g.id).catch(() => {}) }).catch(() => {})\n            }\n          })\n        }\n\n        if (t.kind === 'acesso_permissoes_matriz') {\n          test(t.title, async ({ page }) => {\n            const grupos = (await comBanco(d => acesso.listarGrupos(d, auth))).slice(0, 4)\n            await abrir(page, ac.screens.permissions.path)\n            await aguardarTela(page)\n            const cabecalho = await page.locator('thead th').allInnerTexts()\n            for (const g of grupos) expect.soft(cabecalho.some(c => norm(c).includes(norm(g.nome))), `grupo \"${g.nome}\" no cabeçalho da matriz`).toBe(true) // a tela mostra os nomes em maiúsculas (estilo): compara sem diferenciar\n            for (const v of manifest.views.filter(x => x.logicType !== 'gestao_acesso' && x.path).slice(0, 6)) {\n              await expect.soft(page.locator('td p').filter({ hasText: new RegExp(`^${escapar(v.path)}$`) }).first(), `tela ${v.path} na matriz`).toBeVisible()\n            }\n          })\n        }\n\n        if (t.kind === 'acesso_permissao_ciclo') {\n          test(t.title, async ({ page }) => {\n            const alvo = manifest.views.find(x => x.logicType === 'pesquisa_cadastro')\n            test.skip(!alvo, 'sem caso de uso para mudar a permissão')\n            const u = await criarUsuarioTemporario(auth, { grupoSemRestricao: true })\n            try {\n              const nomeGrupo = String((await comBanco(d => acesso.listarGrupos(d, auth))).find((g: any) => g.id === u.grupoId)?.nome)\n              await abrir(page, ac.screens.permissions.path)\n              await aguardarTela(page)\n              // a coluna do grupo de teste é achada pelo NOME no cabeçalho (nunca por posição: um clique no grupo errado alteraria um grupo de verdade)\n              const coluna = (await page.locator('thead th').allInnerTexts()).findIndex(c => norm(c).includes(norm(nomeGrupo)))\n              expect(coluna, `coluna do grupo ${nomeGrupo} na matriz`).toBeGreaterThan(0)\n              const linha = page.locator('tbody tr').filter({ has: page.locator('td p', { hasText: new RegExp(`^${escapar(alvo!.path)}$`) }) })\n              const celula = linha.locator('td').nth(coluna)\n              await celula.locator('button', { hasText: rotulo('level_none') }).click()\n              await expect.poll(async () => await comBanco(d => acesso.nivelDoGrupo(d, auth, u.grupoId!, alvo!.slug)), { message: 'o nível \"nenhum\" aparece no banco', timeout: 15_000 }).toBe('none')\n              await celula.locator('button', { hasText: rotulo('level_write') }).click()\n              await expect.poll(async () => (await comBanco(d => acesso.nivelDoGrupo(d, auth, u.grupoId!, alvo!.slug))) ?? 'write', { message: 'o nível volta a escrita', timeout: 15_000 }).toBe('write')\n            } finally { await removerUsuarioTemporario(auth, u) }\n          })\n        }\n\n        if (t.kind === 'acesso_so_admin') {\n          test(t.title, async ({ browser }) => {\n            const u = await criarUsuarioTemporario(auth, { grupoSemRestricao: true })\n            const ctx = await novoContexto(browser)\n            try {\n              const pag = await ctx.newPage()\n              await entrarComo(pag, u.email, u.senha)\n              for (const [tela, botao] of [[ac.screens.users.path, 'create_user'], [ac.screens.groups.path, 'create_group'], [ac.screens.permissions.path, 'level_none']] as const) {\n                await abrir(pag, tela)\n                await aguardarTela(pag)\n                await expect.soft(pag.getByRole('button', { name: rotulo(botao) }), `quem não é admin não vê o botão \"${botao}\" em ${tela}`).toHaveCount(0)\n              }\n            } finally { await ctx.close(); await removerUsuarioTemporario(auth, u) }\n          })\n        }\n      }\n    }\n  })\n}\n",
 "src/lib/testing/plan.ts": "import type { ManifestAuth, ManifestDetail, ManifestField, ManifestRowRule, ManifestView } from './manifestTypes'\n\n/**\n * Plano de testes de um caso de uso: a lista do que será conferido, derivada do manifesto. É a ÚNICA fonte: o painel da IDE mostra este plano\n * antes de rodar e o teste do Playwright (e2e/dynamic) gera exatamente estes testes, com estes nomes. Sem dependências: o e2e também a importa.\n *\n * Todas as regras daqui só LEEM dados: nenhuma grava no banco (o cadastro com dados gerados entra depois, junto com o banco de teste do cliente).\n */\nexport type PlannedKind =\n  | 'abre' | 'lista' | 'formulario' | 'mascara' | 'obrigatorios'\n  | 'grid_total' | 'grid_ordenacao' | 'grid_filtro' | 'exportacao'\n  | 'grid_paginacao' | 'filtro_opcoes' | 'visualizar' | 'exportacao_filtrada' | 'exportacao_marcadas' | 'central_downloads'\n  | 'botoes' | 'acoes_linha' | 'campos_tipos' | 'abas'\n  | 'crud_cadastro' | 'crud_reabrir' | 'crud_edicao' | 'crud_exclusao' | 'kanban_mover' | 'fluxo_conectar' | 'detalhe_adicionar'\n  | 'seg_tabela' | 'seg_nivel_nenhum' | 'seg_nivel_leitura' | 'seg_linha'\n  | 'acesso_abre' | 'acesso_usuarios_lista' | 'acesso_usuario_ciclo' | 'acesso_email_repetido' | 'acesso_grupo_ciclo' | 'acesso_permissoes_matriz' | 'acesso_permissao_ciclo' | 'acesso_so_admin'\n  | 'filtros_tela' | 'tipo_galeria' | 'tipo_kanban' | 'tipo_fluxo' | 'tipo_timeline' | 'tipo_gantt' | 'tipo_agenda' | 'tipo_mapa_mental' | 'tipo_mapa' | 'tipo_bi'\n\nexport interface PlannedTest {\n  kind: PlannedKind\n  /** nome do teste (é o nome que o Playwright reporta: o painel casa o resultado por ele) */\n  title: string\n  /** coluna, quando o teste é de um campo (máscara, ordenação, filtro) */\n  field?: string\n  /** formato, quando é de exportação (csv, json, xlsx) */\n  format?: string\n  /** rótulo do campo e máscara (entram no texto traduzido do teste) */\n  label?: string\n  mask?: string\n}\n\nexport type PlanLang = 'pt' | 'en' | 'es'\n\n/** Tipos de teste: funcional só LÊ dados; integração GRAVA (cadastro, edição e exclusão com dados gerados) e exige um banco de teste. */\nexport type TestType = 'funcional' | 'integracao' | 'seguranca'\nexport interface PlanOptions {\n  types?: TestType[]\n  /** configuração de login do projeto (manifest.auth): os testes de segurança por grupo e por linha dependem dela */\n  auth?: ManifestAuth\n}\n\n/**\n * Texto do teste no idioma da tela. O `title` (português) é o NOME do teste para o Playwright e a chave dos resultados e do histórico: não muda\n * com o idioma. Só o que aparece na tela (painel, relatório, comparativo) passa por aqui.\n */\nconst PLAN_TEXT: Record<Exclude<PlanLang, 'pt'>, Record<string, (p: PlannedTest) => string>> = {\n  en: {\n    abre: () => 'the screen opens without errors and shows the use case title',\n    lista: () => 'list: the use case filters and columns are on the screen',\n    formulario: () => 'new form: the fields exist, with required and read-only as configured',\n    mascara: p => `mask of \"${p.label}\" (${p.mask}) formats what is typed`,\n    obrigatorios: () => 'required fields: saving the empty form does not create a record',\n    grid_total: () => 'grid: the total shown equals the database total',\n    grid_ordenacao: p => `grid: sort by \"${p.label}\" in both directions`,\n    grid_filtro: p => `filter by \"${p.label}\": filters the rows and the Clear button undoes it`,\n    acesso_abre: () => 'access management: the Users, Groups and Screen Permissions screens open for the Administrator',\n    acesso_usuarios_lista: () => 'users: the list shows each user with the group that is in the database',\n    acesso_usuario_ciclo: () => 'users: create with group, sign in, change group, reset password and delete (without touching other users)',\n    acesso_email_repetido: () => 'users: a repeated e-mail shows the error in the window and creates nothing',\n    acesso_grupo_ciclo: () => 'groups: create, rename and delete a group',\n    acesso_permissoes_matriz: () => 'permissions: the matrix shows each group and each screen',\n    acesso_permissao_ciclo: () => 'permissions: changing a group level is saved and can be undone',\n    acesso_so_admin: () => 'access management screens are only for the Administrator (a user without admin rights does not get in)',\n    seg_tabela: () => 'table permissions: New Record, Edit and Delete appear only as Studio allows',\n    seg_nivel_nenhum: () => 'group access \"none\": the screen disappears from the menu and does not open by address',\n    seg_nivel_leitura: () => 'group access \"read\": opens and shows the data, but does not allow creating, editing or deleting',\n    seg_linha: () => 'row rule: whoever is not in the exception only sees the rows the rule allows',\n    crud_cadastro: () => 'registration: filling in generated data and saving writes everything to the database',\n    crud_reabrir: () => 'registration: reopening the record shows what was saved',\n    crud_edicao: () => 'edit: changing and saving writes only the change',\n    detalhe_adicionar: () => 'tabs: adding a row in each detail tab and saving writes it with the parent key, and deleting the parent takes the rows with it',\n    fluxo_conectar: () => 'flow: dragging a step only moves it; linking two steps saves the previous step in the database; a link that would make a loop is refused (and the steps go back afterwards)',\n    kanban_mover: () => 'kanban: dragging a card to another column saves the new column in the database (and the card goes back afterwards)',\n    crud_exclusao: () => 'deletion: deleting from the list removes the record',\n    grid_paginacao: () => 'grid: pagination respects the chosen page size',\n    filtro_opcoes: p => `filter by \"${p.label}\" option: only the rows of the option appear and Clear undoes it`,\n    visualizar: () => 'View: opens the record read-only, without a save button',\n    exportacao_filtrada: () => 'export: only what is filtered on the screen',\n    exportacao_marcadas: () => 'export: only the checked rows',\n    central_downloads: () => 'Downloads Center: lists the export and downloads the file',\n    botoes: () => 'buttons: the buttons configured in Studio are on the screen',\n    acoes_linha: () => 'row actions: each custom action opens the other screen in a window, filtered by the row',\n    campos_tipos: () => 'form: each field uses the configured component (text, number, date, options)',\n    abas: () => 'tabs: the detail tabs configured in Studio are in the form',\n    filtros_tela: () => 'filters: all the use case filters are on the screen',\n    tipo_galeria: () => 'gallery: one card per record, equal to the database',\n    tipo_kanban: () => 'kanban: the cards (plus those still to load) add up to the database total',\n    tipo_fluxo: () => 'flow: the diagram opens and the number of steps equals the database',\n    tipo_timeline: () => 'timeline: the screen opens with data refresh and no error',\n    tipo_gantt: () => 'gantt: Today button, sizes and row actions',\n    tipo_agenda: () => 'calendar: month, week and day show different views',\n    tipo_mapa_mental: () => 'mind map: the number of records equals the database',\n    tipo_mapa: () => 'map: the map opens and the total with coordinates equals the database',\n    tipo_bi: () => 'BI: the dashboard opens, refreshes and shows data',\n    exportacao: p => `${FORMATOS_EXPORTACAO[p.format || ''] || p.format} export: ${({ csv: 'header with the grid columns and one line per record', json: 'one item per record', xlsx: 'valid .xlsx file' } as Record<string, string>)[p.format || ''] || ''}`,\n  },\n  es: {\n    abre: () => 'la pantalla abre sin errores y muestra el título del caso de uso',\n    lista: () => 'lista: los filtros y las columnas del caso de uso están en la pantalla',\n    formulario: () => 'formulario nuevo: los campos existen, con obligatorio y solo lectura como configurado',\n    mascara: p => `la máscara de \"${p.label}\" (${p.mask}) formatea lo que se escribe`,\n    obrigatorios: () => 'obligatorios: guardar el formulario vacío no crea registro',\n    grid_total: () => 'grid: el total mostrado es igual al total de la base de datos',\n    grid_ordenacao: p => `grid: ordenar por \"${p.label}\" en ambos sentidos`,\n    grid_filtro: p => `filtro de \"${p.label}\": filtra las filas y el botón Limpiar lo deshace`,\n    acesso_abre: () => 'gestión de acceso: las pantallas Usuarios, Grupos y Permisos de pantallas abren para el Administrador',\n    acesso_usuarios_lista: () => 'usuarios: la lista muestra cada usuario con el grupo que está en la base de datos',\n    acesso_usuario_ciclo: () => 'usuarios: crear con grupo, entrar, cambiar de grupo, restablecer la contraseña y eliminar (sin tocar a otros usuarios)',\n    acesso_email_repetido: () => 'usuarios: un correo repetido muestra el error en la ventana y no crea nada',\n    acesso_grupo_ciclo: () => 'grupos: crear, renombrar y eliminar un grupo',\n    acesso_permissoes_matriz: () => 'permisos: la matriz muestra cada grupo y cada pantalla',\n    acesso_permissao_ciclo: () => 'permisos: cambiar el nivel de un grupo se guarda y se puede deshacer',\n    acesso_so_admin: () => 'las pantallas de gestión de acceso son solo del Administrador (un usuario sin permisos de administrador no entra)',\n    seg_tabela: () => 'permisos de la tabla: Nuevo Registro, Editar y Eliminar aparecen solo como Studio lo permite',\n    seg_nivel_nenhum: () => 'acceso \"ninguno\" al grupo: la pantalla desaparece del menú y no abre por la dirección',\n    seg_nivel_leitura: () => 'acceso \"lectura\" al grupo: abre y muestra los datos, pero no permite crear, editar ni eliminar',\n    seg_linha: () => 'regla por fila: quien no está en la excepción solo ve las filas que la regla permite',\n    crud_cadastro: () => 'registro: llenar con datos generados y guardar graba todo en la base de datos',\n    crud_reabrir: () => 'registro: reabrir el registro muestra lo que se guardó',\n    crud_edicao: () => 'edición: cambiar y guardar graba solo el cambio',\n    detalhe_adicionar: () => 'pestañas: agregar una fila en cada pestaña de detalle y guardar la graba con la clave del padre, y eliminar el padre se lleva las filas',\n    fluxo_conectar: () => 'flujo: arrastrar una etapa solo la mueve; unir dos etapas guarda la etapa anterior en la base de datos; una unión que cree un ciclo se rechaza (y las etapas vuelven después)',\n    kanban_mover: () => 'kanban: arrastrar una tarjeta a otra columna guarda la nueva columna en la base de datos (y la tarjeta vuelve después)',\n    crud_exclusao: () => 'eliminación: eliminar desde la lista quita el registro',\n    grid_paginacao: () => 'grid: la paginación respeta el tamaño de página elegido',\n    filtro_opcoes: p => `filtro de \"${p.label}\" por opción: solo aparecen las filas de la opción y Limpiar lo deshace`,\n    visualizar: () => 'Visualizar: abre el registro solo lectura, sin botón de guardar',\n    exportacao_filtrada: () => 'exportación: solo lo que está filtrado en la pantalla',\n    exportacao_marcadas: () => 'exportación: solo las filas marcadas',\n    central_downloads: () => 'Centro de descargas: lista la exportación y descarga el archivo',\n    botoes: () => 'botones: los botones configurados en Studio están en la pantalla',\n    acoes_linha: () => 'acciones de fila: cada acción personalizada abre la otra pantalla en una ventana, filtrada por la fila',\n    campos_tipos: () => 'formulario: cada campo usa el componente configurado (texto, número, fecha, opciones)',\n    abas: () => 'pestañas: las pestañas de detalle configuradas en Studio están en el formulario',\n    filtros_tela: () => 'filtros: todos los filtros del caso de uso están en la pantalla',\n    tipo_galeria: () => 'galería: una tarjeta por registro, igual a la base de datos',\n    tipo_kanban: () => 'kanban: las tarjetas (más las que faltan cargar) suman el total de la base de datos',\n    tipo_fluxo: () => 'flujo: el diagrama abre y el número de etapas es igual a la base de datos',\n    tipo_timeline: () => 'línea de tiempo: la pantalla abre con actualización de datos y sin error',\n    tipo_gantt: () => 'gantt: botón Hoy, tamaños y acciones de las filas',\n    tipo_agenda: () => 'agenda: mes, semana y día muestran vistas distintas',\n    tipo_mapa_mental: () => 'mapa mental: el número de registros es igual a la base de datos',\n    tipo_mapa: () => 'mapa: el mapa abre y el total con coordenadas es igual a la base de datos',\n    tipo_bi: () => 'BI: el panel abre, se actualiza y muestra datos',\n    exportacao: p => `exportación ${FORMATOS_EXPORTACAO[p.format || ''] || p.format}: ${({ csv: 'encabezado con las columnas del grid y una línea por registro', json: 'un elemento por registro', xlsx: 'archivo .xlsx válido' } as Record<string, string>)[p.format || ''] || ''}`,\n  },\n}\n\n/** Texto do teste para mostrar na tela, no idioma pedido (português = o próprio título). */\nexport const planTitle = (p: PlannedTest, lang: PlanLang): string => (lang === 'pt' ? p.title : PLAN_TEXT[lang]?.[p.kind]?.(p) ?? p.title)\n\n/** Gabarito de cada tipo de tela especial (além de \"a tela abre\" e dos filtros): o tipo de tela → a regra que o confere. */\nexport const TIPO_TELA: Record<string, PlannedKind> = {\n  galeria: 'tipo_galeria', kanban: 'tipo_kanban', blueprint: 'tipo_fluxo', timeline: 'tipo_timeline', gantt: 'tipo_gantt',\n  scheduler: 'tipo_agenda', mapa_mental: 'tipo_mapa_mental', map: 'tipo_mapa', analytics: 'tipo_bi',\n}\n/** Tipos de tela com gabarito (lista, formulário, grid, exportação, ou a regra própria do tipo). Os demais (telas de IA) têm só \"a tela abre\". */\nexport const SUPPORTED_LOGIC_TYPES = ['pesquisa_cadastro', 'gestao_acesso', ...Object.keys(TIPO_TELA)]\nexport const isSupportedView = (v: Pick<ManifestView, 'logicType'>): boolean => SUPPORTED_LOGIC_TYPES.includes(v.logicType)\n\n/** Nome do grupo de testes de um caso de uso (o \"describe\" do Playwright). */\nexport const describeName = (v: Pick<ManifestView, 'title' | 'slug' | 'logicType'>): string => `${v.title} (${v.slug}) · ${v.logicType}`\n\n/** Só máscaras de padrão fixo (0 = dígito; . - / ( ) e espaço literais). Máscaras numéricas (0.000,00) têm outra regra e não entram aqui. */\nexport const mascaraDePadrao = (m?: string): boolean => !!m && /^[0.\\-/() ]+$/.test(m) && /0{2}/.test(m) && !/^0\\.0+,0+$/.test(m)\n\n/** \"00.000.000/0000-00\" + dígitos → \"11.111.111/1111-11\" (cada 0 consome um dígito; o resto é literal). */\nexport function aplicarMascara(digitos: string, mascara: string): string {\n  let out = ''\n  let i = 0\n  for (const ch of mascara) {\n    if (i >= digitos.length) break\n    if (ch === '0') out += digitos[i++]\n    else out += ch\n  }\n  return out\n}\n\nexport const camposEditaveis = (v: Pick<ManifestView, 'form'>): ManifestField[] => v.form.filter(f => !f.isPrimaryKey)\n\n/** Campo de texto livre (serve para ordenar e filtrar por texto): não é lista de opções, nem fórmula, nem chave. */\nexport const ehTexto = (f: ManifestField): boolean =>\n  /char|text|string/i.test(f.dataType) && !f.options?.length && !f.hasFormula && !f.isPrimaryKey && !/select|sele[cç][aã]o|autocomplete/i.test(f.componentType || '')\n\n/** Campo de data/hora: o app usa o seletor nativo de data e a máscara de texto não se aplica (o tipo do componente no Studio manda sobre a máscara). */\nexport const ehData = (f: ManifestField): boolean => /date|time/i.test(f.dataType) || /data|date|hora/i.test(f.componentType || '')\n\nexport const FORMATOS_EXPORTACAO: Record<string, string> = { csv: 'CSV', json: 'JSON', xlsx: 'Excel' }\n\n/** A tela e os campos usados em cada regra de grid (a mesma escolha vale para o plano e para o teste). */\nexport const campoDeOrdenacao = (v: Pick<ManifestView, 'grid'>): ManifestField | undefined => v.grid.find(ehTexto)\n/** O filtro precisa estar também no grid: é pelas células do grid que o teste confere que as linhas casam com o filtro. */\nexport const campoDeFiltro = (v: Pick<ManifestView, 'filter' | 'grid'>): ManifestField | undefined =>\n  v.filter.find(f => ehTexto(f) && v.grid.some(g => g.column === f.column))\n\n/** Filtro por lista de opções (select) que também está no grid: dá para conferir as linhas pela célula. */\nexport const campoDeFiltroOpcoes = (v: Pick<ManifestView, 'filter' | 'grid'>): ManifestField | undefined =>\n  v.filter.find(f => f.options?.length && v.grid.some(g => g.column === f.column))\n\n/** Campos do formulário que o teste de tipos confere (têm nome no HTML: ficam de fora os calculados por fórmula). */\nexport const camposDeTipo = (v: Pick<ManifestView, 'form'>): ManifestField[] => v.form.filter(f => !f.isPrimaryKey && !f.hasFormula && f.dataType !== 'virtual')\n\nconst TITULO_TIPO: Record<string, string> = {\n  tipo_galeria: 'galeria: um cartão por registro, igual ao banco',\n  tipo_kanban: 'kanban: os cartões (mais os que faltam carregar) somam o total do banco',\n  tipo_fluxo: 'fluxo: o diagrama abre e o total de etapas é igual ao banco',\n  tipo_timeline: 'timeline: a tela abre com atualização de dados e sem erro',\n  tipo_gantt: 'gantt: botão Hoje, tamanhos e ações das linhas',\n  tipo_agenda: 'agenda: mês, semana e dia mostram visões diferentes',\n  tipo_mapa_mental: 'mapa mental: o total de registros é igual ao banco',\n  tipo_mapa: 'mapa: o mapa abre e o total com coordenadas é igual ao banco',\n  tipo_bi: 'BI: o painel abre, atualiza e mostra dados',\n}\n\n/**\n * Campo de texto que identifica o registro criado pelo teste de integração: o primeiro campo de texto livre, editável e sem máscara de padrão.\n * É nele que o motor grava o prefixo \"E2E-\" (a limpeza de sobras só apaga linhas assim) e é por ele que acha a linha no banco.\n */\nexport const campoMarcador = (v: Pick<ManifestView, 'form'>): ManifestField | undefined =>\n  v.form.find(f => !f.isPrimaryKey && !f.readOnly && !f.hasFormula && ehTexto(f) && !mascaraDePadrao(f.mask))\n\n/** Prefixo dos dados gerados pelo teste de integração. */\nexport const PREFIXO_E2E = 'E2E-'\n\n/**\n * Regra por linha que o motor sabe conferir: compara uma coluna com um valor que o motor controla no usuário temporário (id, e-mail, nome ou uma coluna dele).\n * Vale também para \"related\" (a coluna aponta para uma linha de outra tabela cuja coluna é igual ao valor do usuário). A lista de valores (\"in\") fica de fora.\n */\nexport const regraDeLinha = (v: Pick<ManifestView, 'rowPolicy'>): ManifestRowRule | undefined =>\n  v.rowPolicy?.find(r => (r.op === 'eq' || (r.op === 'related' && !!r.related)) && (r.source !== 'user.attr' || !!r.attr))\n\n/** Gestão de acesso (Usuários, Grupos, Permissões de Telas): só quando o app a tem (o projeto liga a opção) e o login é pelo banco. */\nfunction planoAcesso(auth?: ManifestAuth): PlannedTest[] {\n  if (auth?.type !== 'database' || !auth.access) return []\n  return [\n    { kind: 'acesso_abre', title: 'gestão de acesso: as telas Usuários, Grupos e Permissões de Telas abrem para o Administrador' },\n    { kind: 'acesso_usuarios_lista', title: 'usuários: a lista mostra cada usuário com o grupo que está no banco' },\n    { kind: 'acesso_usuario_ciclo', title: 'usuários: criar com grupo, entrar, trocar de grupo, redefinir a senha e excluir (sem mexer nos outros)' },\n    { kind: 'acesso_email_repetido', title: 'usuários: e-mail repetido mostra o erro na janela e nada é criado' },\n    { kind: 'acesso_grupo_ciclo', title: 'grupos: criar, renomear e excluir um grupo' },\n    { kind: 'acesso_permissoes_matriz', title: 'permissões: a matriz mostra cada grupo e cada tela' },\n    { kind: 'acesso_permissao_ciclo', title: 'permissões: mudar o nível de um grupo grava e pode ser desfeito' },\n    { kind: 'acesso_so_admin', title: 'as telas de gestão de acesso são só do Administrador (quem não é admin não entra)' },\n  ]\n}\n\n/** Testes de segurança derivados da configuração do projeto (criam usuários e grupos temporários no banco de teste e os apagam no fim). */\nfunction planoSeguranca(v: ManifestView, auth?: ManifestAuth): PlannedTest[] {\n  if (v.logicType === 'gestao_acesso') return planoAcesso(auth)\n  if (v.logicType !== 'pesquisa_cadastro') return []\n  const out: PlannedTest[] = [{ kind: 'seg_tabela', title: 'permissões da tabela: Novo Registro, Editar e Excluir aparecem só como o Studio permite' }]\n  if (auth?.type === 'database') {\n    if (auth.access) {\n      out.push({ kind: 'seg_nivel_nenhum', title: 'acesso \"nenhum\" ao grupo: a tela some do menu e não abre pelo endereço' })\n      out.push({ kind: 'seg_nivel_leitura', title: 'acesso \"leitura\" ao grupo: abre e mostra os dados, mas não deixa criar, editar nem excluir' })\n    }\n    if (regraDeLinha(v)) out.push({ kind: 'seg_linha', title: 'regra por linha: quem não é da exceção só vê as linhas que a regra permite' })\n  }\n  return out\n}\n\n/** Abas de detalhe em que o teste consegue adicionar uma linha: têm pelo menos um campo editável além da chave do pai, da chave primária e dos campos calculados. */\nexport const detalhesPreenchiveis = (v: Pick<ManifestView, 'details'>): ManifestDetail[] =>\n  (v.details || []).filter(d => d.fields.some(f => !f.readOnly && !f.hasFormula && !f.isPrimaryKey && f.column.toLowerCase() !== d.foreignKey.toLowerCase()))\n\n/** Testes de integração (gravam no banco de teste): cadastro, reabrir, edição e exclusão com dados gerados. Só para Pesquisa + Cadastro com pelo menos um campo editável. */\nfunction planoIntegracao(v: ManifestView): PlannedTest[] {\n  if (v.logicType === 'blueprint') return v.blueprintPredecessorColumn ? [{ kind: 'fluxo_conectar', title: 'fluxo: arrastar uma etapa só a move; ligar duas etapas grava a etapa anterior no banco; ligação que formaria um ciclo é recusada (e as etapas voltam depois)' }] : []\n  if (v.logicType === 'kanban') return v.kanbanGroupColumn ? [{ kind: 'kanban_mover', title: 'kanban: arrastar um cartão para outra coluna grava a nova coluna no banco (e o cartão volta depois)' }] : []\n  // com campo de texto, o registro é marcado com E2E-; sem ele (só listas, datas, números...), o motor o identifica pelo id novo e o anota num diário para limpar\n  if (v.logicType !== 'pesquisa_cadastro' || camposDeTipo(v).every(f => f.readOnly)) return []\n  return [\n    { kind: 'crud_cadastro', title: 'cadastro: preencher com dados gerados e salvar grava tudo no banco' },\n    { kind: 'crud_reabrir', title: 'cadastro: reabrir o registro mostra o que foi gravado' },\n    { kind: 'crud_edicao', title: 'edição: alterar e salvar grava só a alteração' },\n    ...(detalhesPreenchiveis(v).length > 0 ? [{ kind: 'detalhe_adicionar' as const, title: 'abas: adicionar uma linha em cada aba de detalhe e salvar grava com a chave do pai; excluir o pai leva as linhas junto' }] : []),\n    { kind: 'crud_exclusao', title: 'exclusão: excluir pela lista remove o registro' },\n  ]\n}\n\nexport function planView(v: ManifestView, opts: PlanOptions = {}): PlannedTest[] {\n  const types = opts.types ?? ['funcional']\n  return [\n    ...(types.includes('funcional') ? planoFuncional(v) : []),\n    ...(types.includes('integracao') ? planoIntegracao(v) : []),\n    ...(types.includes('seguranca') ? planoSeguranca(v, opts.auth) : []),\n  ]\n}\n\nfunction planoFuncional(v: ManifestView): PlannedTest[] {\n  if (v.logicType === 'gestao_acesso') return [] // a gestão de acesso só tem testes no tipo segurança\n  const plano: PlannedTest[] = [{ kind: 'abre', title: 'a tela abre sem erro e mostra o título do caso de uso' }]\n  if (!isSupportedView(v)) return plano\n\n  // telas especiais: o gabarito do tipo + os filtros configurados\n  const tipo = TIPO_TELA[v.logicType]\n  if (tipo) {\n    plano.push({ kind: tipo, title: TITULO_TIPO[tipo] })\n    if (v.filter.length > 0) plano.push({ kind: 'filtros_tela', title: 'filtros: todos os filtros do caso de uso estão na tela' })\n    return plano\n  }\n\n  const editaveis = camposEditaveis(v)\n  plano.push(\n    { kind: 'lista', title: 'lista: os filtros e as colunas do caso de uso estão na tela' },\n    { kind: 'formulario', title: 'formulário novo: os campos existem, com obrigatório e somente leitura como configurado' },\n  )\n  for (const f of editaveis.filter(x => mascaraDePadrao(x.mask) && !ehData(x))) plano.push({ kind: 'mascara', field: f.column, label: f.label, mask: f.mask, title: `máscara de \"${f.label}\" (${f.mask}) formata o que se digita` })\n  if (editaveis.some(f => f.required)) plano.push({ kind: 'obrigatorios', title: 'obrigatórios: salvar o formulário vazio não cria registro' })\n\n  plano.push({ kind: 'grid_total', title: 'grid: o total mostrado é igual ao total do banco' })\n  const ord = campoDeOrdenacao(v)\n  if (ord) plano.push({ kind: 'grid_ordenacao', field: ord.column, label: ord.label, title: `grid: ordenar por \"${ord.label}\" nos dois sentidos` })\n  const fil = campoDeFiltro(v)\n  if (fil) plano.push({ kind: 'grid_filtro', field: fil.column, label: fil.label, title: `filtro de \"${fil.label}\": filtra as linhas e o botão Limpar desfaz` })\n\n  const descr: Record<string, string> = {\n    csv: 'cabeçalho com as colunas do grid e uma linha por registro',\n    json: 'um item por registro',\n    xlsx: 'arquivo .xlsx válido',\n  }\n  for (const fmt of v.exportFormats.map(x => x.toLowerCase()).filter(x => FORMATOS_EXPORTACAO[x])) {\n    plano.push({ kind: 'exportacao', format: fmt, title: `exportação ${FORMATOS_EXPORTACAO[fmt]}: ${descr[fmt]}` })\n  }\n\n  // fase 3 (só leitura): paginação, filtro por opção, Visualizar, exportação filtrada/marcada, Central de Downloads, botões, tipos de campo e abas\n  plano.push({ kind: 'grid_paginacao', title: 'grid: a paginação respeita o tamanho de página escolhido' })\n  const opc = campoDeFiltroOpcoes(v)\n  if (opc) plano.push({ kind: 'filtro_opcoes', field: opc.column, label: opc.label, title: `filtro de \"${opc.label}\" por opção: só traz as linhas da opção e o botão Limpar desfaz` })\n  plano.push({ kind: 'visualizar', title: 'Visualizar: abre o registro só para leitura, sem botão de gravar' })\n  if (v.exportFormats.some(x => ['csv', 'json'].includes(x.toLowerCase()))) {\n    if (fil) plano.push({ kind: 'exportacao_filtrada', title: 'exportação: só o que está filtrado na tela' })\n    plano.push({ kind: 'exportacao_marcadas', title: 'exportação: só as linhas marcadas' })\n    if (v.exportFormats.some(x => x.toLowerCase() === 'csv')) plano.push({ kind: 'central_downloads', title: 'Central de Downloads: lista a exportação e baixa o arquivo' })\n  }\n  if (v.buttons.length > 0) plano.push({ kind: 'botoes', title: 'botões: os botões configurados no Studio estão na tela' })\n  if (v.logicType === 'pesquisa_cadastro' && v.buttons.some(b => b.actionType === 'custom' && b.placement === 'row')) plano.push({ kind: 'acoes_linha', title: 'ações da linha: cada ação customizada abre a outra tela em janela, filtrada pelo registro' })\n  if (camposDeTipo(v).length > 0) plano.push({ kind: 'campos_tipos', title: 'formulário: cada campo usa o componente configurado (texto, número, data, opções)' })\n  if (v.details.length > 0) plano.push({ kind: 'abas', title: 'abas: as abas de detalhe configuradas no Studio estão no formulário' })\n  return plano\n}\n",
 "src/lib/testing/manifestTypes.ts": "/**\n * Tipos do manifesto de testes (sem dependências: o teste do Playwright também os importa).\n * O manifesto descreve cada caso de uso como o dev o configurou no Studio. Ver manifest.ts.\n */\nexport const MANIFEST_VERSION = 1\n\n/**\n * Como o app exportado faz o login e controla o acesso. Com isto o motor cria sozinho o usuário de teste no banco de teste, para qualquer projeto.\n * `type`: database (tabela de usuários do próprio banco), none (app sem login) ou outro (managed, ldap...: ainda sem suporte nos testes).\n */\nexport interface ManifestAuth {\n  type: string\n  usersTable?: string\n  usersPk?: string\n  emailColumn?: string\n  passwordColumn?: string\n  nameColumn?: string\n  hash?: string\n  /** só quando a gestão de acesso está ligada: grupos, vínculo usuário-grupo e permissões por tela */\n  access?: {\n    groupsTable: string\n    groupsPk: string\n    groupsNameColumn: string\n    link: { kind: 'column'; column: string } | { kind: 'table'; table: string; userColumn: string; roleColumn: string }\n    permsTable: string\n    permsRoleColumn: string\n    permsViewColumn: string\n    permsLevelColumn: string\n    /** as três telas de gestão de acesso do app exportado (usuários, grupos, permissões de telas) */\n    screens: { users: { slug: string; path: string }; groups: { slug: string; path: string }; permissions: { slug: string; path: string } }\n    /** textos das telas (botões, ícones, colunas) nos três idiomas de geração: o motor casa por qualquer um deles, sem depender do idioma do app */\n    labels: Record<string, string[]>\n  }\n}\n\nexport interface ManifestOption { value: string; label: string }\n\nexport interface ManifestField {\n  /** nome da coluna no banco (é também o `name` do campo no app exportado) */\n  column: string\n  label: string\n  dataType: string\n  /** tipo de componente escolhido no Studio (Seleção, Numérico, Data/Hora, Autocomplete...) */\n  componentType?: string\n  /** máscara de entrada do Studio (ex.: 00.000.000/0000-00) */\n  mask?: string\n  /** obrigatório por configuração do Studio OU por ser coluna NOT NULL sem valor padrão */\n  required: boolean\n  readOnly: boolean\n  isPrimaryKey: boolean\n  hasFormula: boolean\n  options?: ManifestOption[]\n}\n\nexport interface ManifestButton { id: string; label: string; actionType: string; placement?: string }\n\nexport interface ManifestDetail {\n  table: string\n  /** coluna da chave primária da tabela da aba (para achar e limpar as linhas que o teste cria) */\n  primaryKey?: string\n  label: string\n  foreignKey: string\n  displayMode: 'tab' | 'inline'\n  fields: ManifestField[]\n  subDetails: Array<{ table: string; label: string; foreignKey: string; fields: ManifestField[] }>\n}\n\n/** Regra de acesso por linha do Studio (a tabela só mostra ao usuário as linhas em que `column` é igual ao valor dele), com a exceção por valor ou grupo. */\nexport interface ManifestRowRule {\n  column: string\n  op: 'eq' | 'in' | 'related'\n  source: 'user.email' | 'user.name' | 'user.attr'\n  attr?: string\n  /** só em 'related': a coluna aponta para a linha de `table` (coluna `key`) cuja coluna `column` é igual ao valor do usuário */\n  related?: { table: string; key: string; column: string }\n  bypass?: { source: string; attr?: string; values: string[] }\n}\n\nexport interface ManifestView {\n  slug: string\n  path: string\n  title: string\n  logicType: string\n  table: string\n  primaryKey: string\n  displayType: string\n  actionInterface: string\n  /** o que a tabela permite ao usuário final (Dados & Schemas): criar, editar e excluir */\n  tablePerms?: { create: boolean; update: boolean; delete: boolean }\n  /** regras por linha da tabela; ausente = todos veem todas as linhas */\n  rowPolicy?: ManifestRowRule[]\n  /** kanban: a coluna da tabela que define em que coluna do quadro o cartão fica (arrastar o cartão a muda) */\n  kanbanGroupColumn?: string\n  /** fluxo: a coluna que guarda a etapa anterior (ligar duas etapas grava o id da origem nela) */\n  blueprintPredecessorColumn?: string\n  filter: ManifestField[]\n  grid: ManifestField[]\n  form: ManifestField[]\n  buttons: ManifestButton[]\n  exportFormats: string[]\n  details: ManifestDetail[]\n}\n\nexport interface TestManifest {\n  version: number\n  generatedAt: string\n  project: { id: string; name: string; slug: string }\n  auth?: ManifestAuth\n  dbStack: string\n  views: ManifestView[]\n}\n",
 "src/lib/testing/results.ts": "/**\n * Resultado dos testes, como o relator do e2e (e2e/dynamic/ide-reporter.ts) o envia: uma linha por evento, começando com MB_PREFIX e seguida de JSON.\n * O painel da IDE lê a saída do Playwright, separa estas linhas e atualiza a tela a cada teste que começa e termina.\n */\nexport const MB_PREFIX = '@@MB@@'\n\nexport type TestStatus = 'pending' | 'running' | 'passed' | 'failed' | 'skipped'\n\nexport interface TestEvent {\n  /** begin = começou · end = terminou · done = a rodada acabou */\n  t: 'begin' | 'end' | 'done'\n  /** nome do grupo (caso de uso) e do teste, como em describeName/planView */\n  group?: string\n  title?: string\n  status?: TestStatus\n  ms?: number\n  /** primeiras linhas do erro, quando falhou */\n  error?: string\n  /** por que o teste foi pulado (o motivo que o próprio teste informou) */\n  reason?: string\n  /** arquivos de evidência da falha (captura da tela e vídeo), quando o motor os gravou */\n  shot?: string\n  video?: string\n  /** só em done */\n  total?: number\n  passed?: number\n  failed?: number\n  skipped?: number\n}\n\n/** Uma linha da saída do Playwright → evento, ou null se não for uma linha do relator. */\nexport function parseTestEvent(line: string): TestEvent | null {\n  const i = line.indexOf(MB_PREFIX)\n  if (i < 0) return null\n  try {\n    const ev = JSON.parse(line.slice(i + MB_PREFIX.length)) as TestEvent\n    return ev && (ev.t === 'begin' || ev.t === 'end' || ev.t === 'done') ? ev : null\n  } catch {\n    return null\n  }\n}\n\n/** Playwright: passed/failed/timedOut/skipped/interrupted → status do painel. */\nexport function statusFromPlaywright(s: string): TestStatus {\n  if (s === 'passed') return 'passed'\n  if (s === 'skipped') return 'skipped'\n  return 'failed' // failed, timedOut, interrupted\n}\n\nexport const eventLine = (ev: TestEvent): string => MB_PREFIX + JSON.stringify(ev)\n"
}
